/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20180918-9","meetingId":"h30-cm09","date":"2018年9月18日","dateIso":"2018-09-18","committee":"文教委員会","time":"午後 １時００分～午後 １時５８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"就学援助 新入学学用品費の入学前支給","agenda":"就学援助 新入学学用品費の入学前支給","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それぞれ金額が示されたのですが、この金額の内訳、入学準備に必要なものはどういうものがあると教育委員会としては考えているのか、１年生と７年生のその中身を教えていただきたいと思います。それが２つ目です。それから、１年生の場合、区の就学援助では、１年生の入学準備用品として２万３,８９０円となっているのですけれども、今回４万６００円ですか。これは７年生についても同じです。","respondent":"篠田学務課長","answer":"人数ですけれども、現在想定していますのは、小学校新１年生については、入学予定者が５５０人と見ております。これは例年の入学者に対する認定率と絡めて、そのぐらいだろうと思っています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"これからは新１年生は２万３,８９０円から４万６００円になるという理解でいいのですね。わかりました。国の補助金が引き上がったことで引き上げるのは、否定はしないのですけれども、実際どれくらいかかっているかということを調査して、その上で必要な額を算定して公表していくことがいいのかなと思っているのですけれども、そのあたりはどうだったのかを教えていただきたいと思います。","respondent":"篠田学務課長","answer":"ただ、例えば先ほど委員からご指摘の国の調査ですとか、さまざまな機関で新入学に関する経費に関しては調査がありますので、そういったものを踏まえつつ、今回は国の補助単価を踏まえた形で引き上げになっているものです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"それで、４万６００円に上がったことは否定するものでは決してないのですけれども、例えばこの４万６００円を受ける方、新１年生で、小中一貫校に入る場合は大抵制服があります。ランドセルにしても、かなり高いです。そういう実態を見たときに、この金額でどうなのかなと思うので、その辺の４万６００円の構成をどういうふうに組み立てたのかというところを教えていただきたいと思います。","respondent":"篠田学務課長","answer":"ですので、必要な経費として幾らかというのを把握するのは、当然必要なことだと考えていますが、それがイコール実態になっているかといったところもあろうかと思いますので、その辺を十分精査する必要があるのではないかと考えているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"出さなくはないのですけれども、年度に入ってから出す、その辺をどういうふうに考えておられるのかを、先ほどの答弁の関係では伺いたいと思います。それから、対象者の数字は先ほど紹介していただいたのですけれども、漏れてしまうことがないようにすることが、１つ大事なことだと思うのです。そのあたりの周知はどういうふうにされようとしているのか、先ほど説明がなかったと思うので、伺いたいと思います。","respondent":"篠田学務課長","answer":"したがいまして、今後、社会情勢等さまざまな変化があれば、場合によってはそういったモデルケースの対応というのもあり得るのかなと思いますけれども、その辺は十分周りの状況を注視しながら進めてまいりたいと考えているところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"ありがとうございました。漏れがないように、最大限努力をしていただきたいということが１つです。それから、さっき聞きそびれたのですが、制服の標準服の金額が２万円となっているのですけれども、私はもう少しこれより多いのではないかと思ってきたのですが、この金額、実態がどういうふうになっているかつかんでいるのか、つかんでいたら、その金額を教えていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。実際、現在の自民党の総裁選があって、誰が総裁になるか、まだわからないですけれども、どういうふうになったとしても、自民党政権として今年の１０月から３年間の中で、生活保護基準の引き下げが予定されているという報道があります。そういう点についての認識、見解を教えていただきたいというのを最後に言って、終わりたいと思います。","respondent":"篠田学務課長","answer":"この間、生活保護費の基準が下がったこともございましたけれども、これまで従前の、平成２４年の水準をもとにした形で、ずっと計算してございまして、今のところ、これを変更するという考えはございませんので、今後さまざまな社会情勢等の変化があれば。","voiceIndex":15,"id":"exchange-006"},{"speaker":"南委員","kind":"確認","question":"すみません。答弁の中で出てきた制服の関係です。２万円の支給額に比して、男子も女子も相当オーバーしているという実態があり、それが確認できたと思います。したがって、この２万円も、私は引き上げる必要があるのではないかと思っておりまして、この点についてだけ答弁いただいて終わりたいと思います。","respondent":"篠田学務課長","answer":"ただいま申し上げた金額が、就学援助の基準額を満たしていないです。確かにそういう面はありますので、今後、必要な検討は加えていく必要があるのかなと思いますけれども、基本的に、あくまで就学援助です。","voiceIndex":17,"id":"exchange-007"},{"speaker":"石田（し）委員","kind":"質問","question":"そもそも前倒しで支給してもらうということは、何かを購入するときに、手元にお金がしっかりあるようにということで、事前に支給してもらうのでしょうから、入学の学用品を購入される時期というのが、この支給時期の後であれば、非常にマッチする施策になるのですけれども、これが例えば２月の頭ぐらいに購入等を考えているのであれば、買うときにはこの支給がされていないわけですので。","respondent":"篠田学務課長","answer":"７年生に関しましては、現在就学援助が認定されている６年生の方にすべて出すというのが大前提ですので、別の機会を設けて新入学学用品費だけ別に、通常の支給とは別に出すという考え方もなくはないのですけれども、やはり事務上、できればできるだけ整理した形で。","voiceIndex":21,"id":"exchange-008"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひ実態と合うような支給の仕方をしていただければと思います。事務手続に時間がかかるというお話ですが、個別に通知をされているのだから、誰に支給をするかというのがわかっているわけですし、先ほど支給の人数が、新１年生と今の６年生を合わせても大体１,０００人ぐらいです。これは要望で終わりますが、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"今回挙がっている新入学学用品の内訳、全ての学年で学用品費が出ていますが、ここに当たるものが具体的に何なのかということをお伺いします。分かりました。よその自治体と比較して、その辺が変わっているのかというのが２点目。今回の４万６００円、国の基準のところが変わってきているということは、これが最低の金額で、自治体によっては上乗せもできるのかどうか、その辺も含めて教えてください。","respondent":"篠田学務課長","answer":"ただ、一定程度のよりどころを求めるといったところでは、例えば２３区であれば財調の単価を基準にある程度考えているところが多うありますし、今回は財調単価よりも国庫の補助の基準額の見直しがあり、そちらのほうが高くなったということがあったので。","voiceIndex":25,"id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問・要望","question":"金額的には自治体の判断。国のほうが少しずつは変わって、上がってきているのでしょうか、この４万６００円というと、多分上がっていると思うのですけれども、さっき南委員からありましたが、実態的に見ると金額が低い。ランドセルは２万円では買えないです。４万円ぐらいかかるといった報告も受けています。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"}]},{"id":"topic-02","title":"平成３０年度「秋の読書フェア」","agenda":"平成３０年度「秋の読書フェア」","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"この対象者というのは、どの層になるのですか。そこを教えてください。","respondent":"横山品川図書館長","answer":"かわりまして３番は、「秋の子ども読書の日フェア」ですので、こちらは子ども向けということで、０歳から最大１８歳ぐらいまでの方を想定しています。","voiceIndex":32,"id":"exchange-012"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"毎回我々申し上げていますけれども、ホームページというのは、何か情報をとるときに見るのですが、どちらかというとこういうのは、区から発信されて、こういうのをやっているのか、では行こうかなというイベントになるのかと思うので、特にしっかり対象世代を把握して、その世代に合った発信方法、今は品川区でもさまざま、インターネットを通じて発信されているのは重々わかっていますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"こういったイベントをいろいろ取り組まれて、いいなと思っているのですが、図書館の利用状況というのは、地域的な差などはどこかで調べたことがあるのでしょうか。私は目黒区沿いの方に住んでいると、図書館に行きたくてもなかなか行けないとか、あと、本当に地域の要望を聞くと、ぜひ図書館が欲しいという声がかなりあるのです。","respondent":"横山品川図書館長","answer":"委員ご案内の目黒サービスコーナーについては、非常に貸し出し数・返却数ともに伸びている状況で、こう言ってはなんですが、区外の方のご利用も非常に多い状況になっております。","voiceIndex":36,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"取り次ぎとか、いろいろ工夫はされていると思うのですけれども、１つ、移動図書館的なもので回るとか、図書に親しんでほしいアピールをするというのは、こういうところに触れると、いろいろやっているのだなと思いますけれども、実際的に姿を見せていただいて、アピールしてもらうようなことは考えられないのでしょうか。","respondent":"横山品川図書館長","answer":"本に触れる場として、病院であるとか、大きな保育園だとか、ご要望をいただければ団体貸し出しとして、５０冊、１００冊という単位で３カ月お貸し出しして、そこでご利用いただくという工夫もしておりますので、そちらをまずはご利用していただいて。","voiceIndex":38,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"意見","question":"それはお願いといいますか、いろいろ工夫していただけたら、例えば車で移動するとか、現在ある施設のコーナーを借りて、一時的に図書館のアピールをするとか、機会がいっぱいあれば、図書に触れる、音楽を聞く等、その楽しみを知るということは、年を重ねていく上でも、すごくいいことだと思うので、ぜひご検討いただけたらと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-016"},{"speaker":"南委員","kind":"提案","question":"その辺で、秋の読書フェアということで、それぞれの館でのテーマを設定するときに、例えば秋なら秋ということを大事に、コンセプトとして計画しましょうというような、そういう取り組み、提案になっているのか、こういうテーマをお決めになったときに、その辺が何となく醸し出されてきたのかなと思ったりして、どういうふうになったのかなというのを知りたいなと思います。","respondent":"横山品川図書館長","answer":"そのため、月に１回、地区の図書館長会を開いておりまして、秋の読書フェアについては年間で予定をしておりますので、大分前から各館で取り組むテーマを決めて、個別のテーマをつくって本を集めてほしいと依頼しました。","voiceIndex":42,"id":"exchange-017"},{"speaker":"つる委員","kind":"提案","question":"これは特に３の秋の子ども読書の日フェアですけれども、この間のそうした利用者等が、どういう傾向にあるのか参考に教えていただければというのと、当然、児童・生徒ないし親の負担になってはいけないのですが、夏であれば夏の読書感想文とかに関連してあったりするのですが、特に学校の行事と無理やり関連づける必要はないかと思うのですが、そうした学習能力の向上にもある程度寄与しているのであれば。","respondent":"横山品川図書館長","answer":"学力との相関なのですが、夏に行いました「読書の木」、読書のスタンプラリーで本を３冊読んでスタンプを集めると、ノートがもらえるという催しをしましたときに、あわせて、そのときの感想を短いですけれども書いてもらって、その書いてもらったものを集めて貼って。","voiceIndex":45,"id":"exchange-018"},{"speaker":"つる委員","kind":"質問","question":"これは学校図書館だけではない、地域の図書館がそういう子どもたちにどうアプローチをしていくかということ。そこが当然、読書に触れることで、お伝えしたとおり、学習能力にプラスの効果があるわけですから、そのあたりの今後の強化策とか、当然こういうフェアは毎年、年間を通してもいろいろあるわけですので、そのあたりについて何かお考えか教えてください。","respondent":"横山品川図書館長","answer":"特に子どもについて、品川区においては子ども読書活動推進計画、図書館ではそれだけですので、その改訂を平成３１年度までの計画期間後に予定しておりますが、そちらの中で、より広げていかなければならないですし、また。","voiceIndex":47,"id":"exchange-019"},{"speaker":"つる委員","kind":"提案","question":"前に、児童センター等で読み聞かせをやっているグループが、大きな本の持ち運びが大変なので、図書館で取り次ぎ等ができるといいのですけれどもとおっしゃっていて提案させていただいたことがありました。先ほど移動図書館という話もありましたけれども、中国などは図書館の自動販売機があったりするのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"いろいろ出たのですが、２つだけ伺います。児童・生徒が、学校の図書館で今こういうフェアをやっているのだということが、すぐにわかるようになっているのかということです。それからもう一つは、さきほど１８歳までが対象範囲だとおっしゃったので、区内には公立・私立の高校があると思うのですが、そちらでも、区立図書館でこういうことをしているというのが在校生にわかるのでしょうか。","respondent":"横山品川図書館長","answer":"広報しながわや統合チラシ、ホームページ等でお知らせして、それを見ていただいて、なるべく来ていただくような形をとらせていただいております。こちらの部分についても、これから力を入れていかなければいけないと考えます。","voiceIndex":51,"id":"exchange-021"}]},{"id":"topic-03","title":"品川図書館エレベータ改修工事","agenda":"品川図書館エレベータ改修工事","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"一番下に書いてある誰でもトイレの３カ所というのは、１フロアに１カ所ということで、新たに誰でもトイレを設けるということなのでしょうか。","respondent":"横山品川図書館長","answer":"各フロアに１カ所ありますので、改修工事をいたしまして、オストメイトほかの設備をつけていくような予定です。","voiceIndex":62,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"おむつ交換する台、着がえができるようなところなど、いろいろタイプがあるのですが、前にも車椅子を利用されている方が、いろいろ設備がつくと、車椅子が中で回れないとか、いろいろあちこちで起こったりするので、ぜひその辺は、利用者の声とか、実際に意見を聞いて、いいものを使っていただいて、せっかく改修するので、いろいろな方が本当に便利に使えるようにしていただきたいです。いかがでしょうか。","respondent":"横山品川図書館長","answer":"３カ所あるうち、４階のトイレが一番広いので、そちらについてはある程度、車椅子で入ってもご不便ないような形で、オストメイト等の設備ができるのですが、２階・３階については狭くて、なかなか着がえの場所等をつけることができないので。","voiceIndex":64,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4952#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":19568,"voices":69}},{"id":"h30-20180918-5","meetingId":"h30-cm09","date":"2018年9月18日","dateIso":"2018-09-18","committee":"総務委員会","time":"午後 １時００分～午後 １時４６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"「」を聴取いたします。 まず、(1)シティプロモーションの取組","agenda":"「」を聴取いたします。 まず、(1)シティプロモーションの取組","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"今回は東急バスではなく都営バスにしようというふうになった経緯を教えてください。やはり、東京都内の人にも品川区を知ってもらうというのは大切ですけれども、例えば東急バスでは、五反田駅から川崎駅ラゾーナ広場行が結構の数１日往復していますので、やはり他県にも品川区というインパクトを与えるのも必要ではないかと思うのですけれども、なぜ都営バスだけなのかということです。","respondent":"木村報道・プロモーション担当課長","answer":"ご指摘の東急バスなのですけれども、検討はもちろんしてございまして、ただ、おっしゃるように、荏原地区あるいは東急バスで展開したということもあり、今回は都営バスでやってみようというところで、区内も走りますし、区外へ１台ですけれども走るというところもございまして。","voiceIndex":5,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"だから、ぜひ奇をてらったとまでは言えないですけれども、普通では思いつかないような広告の打ち方をやはり考えていかなければ、例えば、それが航空法か何かで禁止されていたらあれなのですが、昔デパートとかでやったアドバルーンで上げるというのも、それは１つの考え方で、やはり目を引きますので、品川区なのだという、そういう思いにさせるというのも大切なので。","respondent":"木村報道・プロモーション担当課長","answer":"東八潮の紹介と、それから奇をてらった、もう少し違った観点での広報というところでございまして、ご意見を今頂戴いたしましたので、そういった観点からも検討を進めてまいりたいと思います。","voiceIndex":7,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいことは、交通広告ということですけれども、今回の広告に幾らかかっているのか、それぞれＪＲ京浜東北線サイネージ、ＪＲ京浜東北線中吊り貸切、品川駅自由通路、都営バス、ＳＮＳ、日経新聞折込タブロイド紙、それぞれの費用についてご説明いただきたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"品川駅自由通路に関しましては１３０万円、都営バスのラッピングにつきましては２１０万円、日経新聞の折込につきましては４４０万円、ＳＮＳ広告に関しましては４５万円、あとは諸経費となっております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"全体で１,５００万円弱ということですけれども、これは全部一般財源なのでしょうか。財源についても伺いたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"ご指摘のとおり一般財源です。","voiceIndex":12,"id":"exchange-004"},{"speaker":"中塚委員","kind":"意見","question":"一般財源を使った区独自の事業ということですけれども、苦しい区民生活がある中で、果たしてここに１,５００万円をかける必要性や緊急性があるのかどうか、やはりこれは十分検証していく必要があると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"それと、事業推進・効果測定の中に、効果検証が予算化されているのですけれども、これは前にやったことについての効果を検証しつつ、次の予算立てがされる、次の事業が進められるというように理解をしているのですが、効果検証というのはどのタイミングでされるのか、その辺についてお伺いします。","respondent":"木村報道・プロモーション担当課長","answer":"今回の交通広告に関しましても、この広告の効果というような形で効果測定の分の経費を見込んでおりまして、今回のこのタイミングで、交通広告の効果というようなところも検証を行う予定です。","voiceIndex":16,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。交通機関活用による認知度向上の中に電車車内サイネージ３３０万円という予算がありますので、この予算が該当すると考えていいのですね。ですから、駅ばりポスターは予算化されていますけれども、中吊りや電車広告はまた別ですよね。当然、検証の結果というのは、また改めてご報告がいただけると考えてよろしいでしょうか。","respondent":"木村報道・プロモーション担当課長","answer":"検証の結果につきましては、何らかの形でご報告をさせていただきたいというふうに思っております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"何か中途半端ではないのかなと。やはり、人に来てもらうのにどうすればいいのかなと。いろいろ取り組んでいるけれども、こんなに中途半端にやるぐらいならやらないほうがいいのではないですかと、一般企業だったら考えると思います。やるなら徹底してやらなければいけない。でも、予算に限りがある。区としては本当にこれでいいと思っているのですか。嫌な質問で恐縮なのですけれども、教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"委員も今おっしゃったように、予算も限りがあるという中で、だから何もしないということではなく、いかに効果的にいろいろなＰＲができるかというところをやはり考えて、実際に品川区に訪れていただきたい、住んでいただきたい、あるいは品川区を認知をしていただきたい。","voiceIndex":20,"id":"exchange-008"},{"speaker":"須貝委員","kind":"意見","question":"観光振興を狙って、それぞれ県とか区とか、さまざまな遠い地方で観光事業を主にして予算を組んでいろいろとＰＲしていると思います。試行錯誤をしているのもよくわかります。ですけれども、やはり少し立ち止まってみるということも、私は大切なことだと思いますので、これは意見として言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-009"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"ご説明ありがとうございました。今伺いましたので内容は理解をしておりますが、何点か確認なのですけれども、ＳＮＳとＷｅｂ広告、そしてこのタブロイド判の内容というのは、同じものが使用されていくと思っていいのでしょうか。先日土曜日にテレビ東京の番組「アド街ック天国」で大井町が特集されました。","respondent":"木村報道・プロモーション担当課長","answer":"タブロイド紙につきましては、いわゆる区政、あるいはサービス、前回の委員会でＰＲ冊子をご説明いたしましたけれども、区の打ち出している事業などをかみ砕いて、あるいはそれを実際に区民の方で、例えば子育て中の方などにインタビューをしたものを掲載するという形で。","voiceIndex":24,"id":"exchange-010"}]},{"id":"topic-02","title":"旧荏原第四中学校保育園仮移転改修その他工事請負契約","agenda":"旧荏原第四中学校保育園仮移転改修その他工事請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"実はプールの解体はすごくうるさいのです。機械で割るというよりも、手で少しずつ砕くと言うのでしょうか、振動も騒音も大きく、周辺への影響が大きい。私も原小学校のプールを解体するときに、ご近所の方から、さすがにこれはたまらないという話をたくさん伺っただけに、今回どのように周辺への説明をされたのか、影響を少なくするための工事になるのか、またできるのか、ご説明いただきたいと思います。","respondent":"小林施設整備課長","answer":"説明の方法については、１軒１軒近隣を回っております。その状況によりますと、聞いている話では、解体そのものは喜ばれております。","voiceIndex":34,"id":"exchange-011"},{"speaker":"いながわ委員","kind":"確認","question":"済みませんが確認です。これも所管から外れるのですけれども、今後、何か用途があって、その用途のための工事を一緒にしてしまおうという感じなのか。ここ５、６年か何年かずっと貸し付けと言うか、中学校がなくなった後、朋優学院や青陵高校がここを有効利用してきたのは、それは全然いいと思うのですけれども、何か今後のことを見据えた改修工事なのかと思えてしまうのですけれども。","respondent":"小林施設整備課長","answer":"塀についてのご質問にお答えします。これは、既存プールのプールサイドが、隣地の塀を兼ねているのです。それを壊すと、敷地境界の部分になにもなくなってしまいますので、そこの部分の改修をやらざるを得ません。","voiceIndex":36,"id":"exchange-012"},{"speaker":"いながわ委員","kind":"質問・要望","question":"別に何が云々とかそういうのではないので、もし、これだけ１億６,０００万円ぐらいかけて工事をするのであれば、また次に何かをするときに、また同じお金をかけてまた何かを壊すとかではなく、１回で終わればそれはいいのかなという思いがありますので、計画的にやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-013"}]},{"id":"topic-03","title":"東品川橋架替工事（その３護岸・道路復旧）請負契約の変更","agenda":"東品川橋架替工事（その３護岸・道路復旧）請負契約の変更","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"確認なのですが、これは、工期が伸びたわけですよね。工期が伸びたことによって、費用は発生したのかどうなのか。ボーリング調査をしたときに何となくわからないのかと、いつも不思議に思っていて、これも確認です。これはやはり掘らなければわからないものなのか、どうなのか。その都度、そこで費用がかかっているようにも思えるし、その辺がどうかということを教えてもらっていいですか。","respondent":"立木経理課長","answer":"２点ほどご質問いただいた件ですが、工期が伸びることによる費用の変更というのは、今回、所管のほうから上がってきておりませんので、費用はかからないものと考えております。","voiceIndex":48,"id":"exchange-014"},{"speaker":"いながわ委員","kind":"確認","question":"基本的に日本に２台しかない機械を持って来たら、絶対にそれは前の見積もりでは無理のような気がしたので質問させていただいたのですが、費用に変更がないということなのであれなのですけれども、そういう部分で、非常に日本に少ない重機を使ってやるということを考えたら、もっと事前に土壌調査とかボーリング調査をして、確認をしたほうが工事がスムーズに進むのではないかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"そもそもの変更理由が、仮締切工の構造を一部変更したことによるという、何かがずれたというふうに説明されたと思うのですけれども、ずらさざるを得ない事情があったのだとは思いますが、その理由を伺いたいと思います。","respondent":"立木経理課長","answer":"そういったことで聞いております。当初、囲むべきところよりも少し外側に出るような感じで、川の方に少し護岸から離れるような形にする必要となったということです。当初の計画と少しずれてしまったと聞いております。","voiceIndex":52,"id":"exchange-016"},{"speaker":"吉田委員","kind":"確認","question":"そういうふうに言われたら、そうですかと言うしかないのですけれども、ほかのこともそうなのですけれども、やってみて初めてわかったと言うか、事前の調査などで発見することは難しいものなのでしょうか。そうなることによって、橋の架けかえ自体への影響と言うのでしょうか、そういうことがないのか、その辺を確認させてください。","respondent":"立木経理課長","answer":"事前の調査の部分や、設計の部分に関しては所管のほうにしっかり伝えてまいりたいと思います。工期が伸びることによる橋への影響ですが、こちらは橋の架けかえ工事が終わった後の補修工事ということになっておりまして、道路部分、それから護岸部分というところの補修工事です。","voiceIndex":54,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2118#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":13276,"voices":59}},{"id":"h30-20180919-14","meetingId":"h30-cm09","date":"2018年9月19日","dateIso":"2018-09-19","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時２３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"基礎自治体のあり方に関することのうち児童相談所移管","agenda":"基礎自治体のあり方に関することのうち児童相談所移管","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"２カ所視察された考察ということで、計画的な人材の確保・育成と、児童相談所と他機関との役割分担の２点が主に挙げられているのですが、もう少しほかにあれば伺いたい。(1)、(2)の人材の確保・育成、また役割分担は品川区でも必須だということなのですけれども、品川区はどれぐらいからこれを始めることができるのか。要は、事前に必要なのか、それとも開設してからかということです。","respondent":"二ノ宮児童相談所移管担当課長","answer":"特に熊本市は設置時期が比較的浅いというところではあるのですが、やはり同じように人材の確保が一番難しい。即席で養成できるものではないということで、かなり時間等を要するところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、開設前にどれぐらいからというと、ここからというのはないと思うのですけれども、人材確保も含めてなのですが、どんな準備をどのようにするか、少し具体的に伺いたいのです。それと、同じ学校の子を同じ一時保護所に入れないという説明もあったのですけれども、そこの対応はどうされていたのか。児童相談所は０歳から１７歳が対象だと思うのですけれども、両市はどういう年齢配分になるのでしょうか。","respondent":"二ノ宮児童相談所移管担当課長","answer":"ご指摘がありましたとおり、親御さんの意に反して一時保護した場合に、区でやる場合には、基本的に区の保護所に入ることになるかと思いますので、そこはこれから建物の設計もそうなのですけれども。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"今回、視察された２カ所の一時保護所ではどのように対応されていたのかということを伺ったので、あらためてご答弁お願いします。","respondent":"二ノ宮児童相談所移管担当課長","answer":"そこについての直接的な質疑はなかったのですけれども、０歳から２歳の子ども、また車椅子が必要な子どもの設備はあったのですが、中を視察させていただいた限りでは、そういったお子さんは実際にはいらっしゃらなかったという状況です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"前回、足立児童相談所を視察して、さまざまなお話をお伺いいたしました。要は、品川区は面積が狭い地域ですから、親でも親族でも、子どもがどこに入っているか探そうと思えば、一時保護施設のどこに入っているということを探し得ることは比較的可能です。秘匿性などを考えると、やはり近隣の区との連携を考えていかないと難しいのではないですかという話を担当の方がおっしゃっていました。","respondent":"二ノ宮児童相談所移管担当課長","answer":"例えば児童福祉だけではなくて生活保護や生活困窮者自立支援制度などに詳しい職員がいれば、それはそれでいろいろなケースに対応できることもあります。確かにそこはなかなか難しいところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、本当に今、こうやっていろいろ視察をしながら、いろいろなところを回りながら、また職員を派遣しながら、どんどん勉強されていると思うのですが、本当に慎重に進めていただきたいと思います。期限は期限としても、さまざまな問題を抱えていると思います。でも、それより、つくった後の問題のほうがすごく大きいと思うので、その辺は上の偉い人にも慎重に進めるように言ってください。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"こんの委員","kind":"質問","question":"その中から数点お伺いしたいのです。視察をされた後の福岡市の特色の中に、(1)常勤弁護士の配置というお話がありました。この判断をどうしたらいいか。そのお考えをお伺いしたい。それと合わせてお伺いしたいのが、他課との連携というところで、考察でもおっしゃっておりますけれども、他課との連携は、それぞれの分野を活かしつつというのが大事であろうと思うのです。この２点をお願いします。","respondent":"二ノ宮児童相談所移管担当課長","answer":"その後、平成２８年から期間の定めのない職員としてそのままいてもらうということで、こういったことに関与してくれる弁護士、かつ職員として働いてくれるという方が実際にあらわれたのは、非常にうらやましいと申し上げるか。","voiceIndex":16,"id":"exchange-006"},{"speaker":"こんの委員","kind":"質問・要望","question":"ごめんなさい。いずれにしても、今ご説明いただいたように、常勤弁護士の配置は、ぜひ品川区としても考えていっていただきたいと私は思っております。品川区のハード面では、そこまでの平米数がとれるのかどうかというところもあると思うので、その辺の状況を教えてください。相談室のほかに、療育の部分での部屋などはどのように考えていらっしゃるのか、あわせて教えてください。","respondent":"二ノ宮児童相談所移管担当課長","answer":"現在の建設予定地の建物の中にどこまで入るのかということなのですけれども、資料にありますとおり、福岡市は延床面積が１万２,０００m2を超える非常に大きな建物になっております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"こんの委員","kind":"質問・要望","question":"スペースが限られるのは、私も理解いたします。ハード面が先なのか、機能が先なのか。ハード面に限界があるから、これしかできないよとなってしまうと、それは違うと思います。だけど、ハード面に限りがあるから、やはり人員やしつらえもおのずと限られてしまう。どうか機能とハード面と両面からこのことは進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"松永委員","kind":"質問","question":"先ほど、こんの委員からも質問があったのですけれども、常勤弁護士に任期が決められているということなのですが、大体どのくらいなのか。次に、ハード面なのですけれども、足立児童相談所を見学させていただいた中で、天候や節電の関係かもしれないのですが、明かりが少なく暗い雰囲気であったなと感じました。なければ、子どもたちはどのように遊んでいるのか。その取組みについてお知らせください。","respondent":"二ノ宮児童相談所移管担当課長","answer":"特に、一時保護所につきましては、子どもたちが２４時間３６５日生活する場所にもなりますので、そこは居心地がいいとか、そういう問題ではないのですけれども、例えば朝はちゃんと日が入ってくる中でご飯を食べられるようにということは。","voiceIndex":22,"id":"exchange-009"},{"speaker":"松永委員","kind":"意見","question":"やはり外で遊べる環境というのは、子どもたちにとってはとても大事ではないかなと思います。例えば場所がなければ、安全を考慮して、屋上等に柵をつくって、外から見えないような感じで、今後建物を建設するにあたっては、そうした場所の確保は必要だと思いますので、どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"足立児童相談所の視察を行いまして、改めて虐待などの相談件数の増加の状況や、その中で、人権侵害の深刻な実態などに思いをはせましたし、また、親の孤立や貧困など、このあたりの背景を含めて、深刻さを改めて実感いたしました。児童虐待をゼロにしていくには何が必要なのか、お考えをお聞かせいただきたいなと思います。児童虐待をゼロにするには何が必要なのか、区の考えをお伺いしたいと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"必要に応じて家庭訪問をするということをやった上で、今行っている区の子育て支援事業等につなげていくということが大事なのかなと考えています。そういったことを地道にずっと続けていくということがまずは大事なのかなと考えています。","voiceIndex":26,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"現在検討している体制と考え方を伺いたいのです。区設置の児童相談所における児童福祉司の体制は、何人ぐらいの配置を目指しておられるのか伺います。さらに、専門性や経験を積むためには、やはり時間がかかりますので、開設前に計画的に都の児童相談所に、区の児童福祉司の資格を持っている方が研修に行くという計画を持って進めるべきだと思いますけれどもいかがでしょうか。","respondent":"二ノ宮児童相談所移管担当課長","answer":"先ほど来、ご指摘がある、例えば法的対応が必要なケースもあれば、親御さんも子どもも非常に安定していて、あまり日常的に手をとられない業務もあろうかと思います。","voiceIndex":28,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"メンタルの問題を抱え、バーンアウトする人も少なくないというお話も伺いました。厚生労働省が２００８年にまとめた報告書では、児童福祉司と同数を目指して配置すべきとありますけれども、児童心理司の配置の考え方を伺いたいと思います。私は同数を目指すべきだと思いますけれどもいかがでしょうか。この設置基準、運営基準をどのように考えておられるのか伺いたいと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"ご指摘のあった児童心理司の充実というのも、当然それ相応にそろえなければいけないことですので、進めてまいりたいと考えているところです。","voiceIndex":30,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"どんどん状況が変わってくるということなのですけれども、一時保護所も先ほど言ったように一人ひとりの子どもたちの背景、状況に応じた対応ができるような基準をぜひつくっていただきたいなと考えています。その辺をどのように考えているのか伺いたいと思います。東京都の児童相談所、または他区の児童相談所との連携した年齢配分も必要になるのかなと思いますけれどもいかがでしょうか。","respondent":"二ノ宮児童相談所移管担当課長","answer":"他方で、例えば通学の過程で親に会い、子どもに危害が加えられるようなおそれがある場合は、当然外には出せないということになってしまいますので、一時保護所内での学習は、教員免許を持つ者などを配置しないといけないということは、十分認識しております。","voiceIndex":32,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"協議の内容はどのようなことが話されていて、今どのような状況になっているのかということを少しお伺いしたいというのが１点です。何がどこまで検討が進められていって具体化されていくのか、全体像とそれぞれ具体的な対応について、各種関係部署との連携を行うとともに、議会への丁寧な報告をこれからも求めていきたいと思いますけれどもいかがでしょうか。最後にお伺いします。","respondent":"二ノ宮児童相談所移管担当課長","answer":"仮に練馬区以外の２２区全てに児童相談所を設置したとしても、東京都自体も、多摩市、八王子市等に引き続き児童相談所を持っておりまして、社会的養護の児童養護施設等は、都内各域に散らばっております。区によっては、そういった社会的養護の受け皿が一切ないこともあります。","voiceIndex":34,"id":"exchange-015"},{"speaker":"横山委員","kind":"質問","question":"幾つかお伺いしてまいります。福岡市についてです。そのあたりも視察の中でお話があったのかなと思うのですけれども、負の連鎖みたいなところから、正のループにどう工夫してやっていかれたのか。今現在のお考えといいますか、福岡市や熊本市の事例をお伺いする中で、どういった可能性があるのかというところをお聞かせいただけたらと思います。","respondent":"二ノ宮児童相談所移管担当課長","answer":"里親の話です。国としても家庭養護の推進ということで、里親を充実させていこうという話があって、そういったことも必要かなと思う反面、今区内には１つ児童養護施設がございまして、そういった存在そのものを否定することもなかなか難しい。","voiceIndex":37,"id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"視察のご説明、どうもありがとうございました。これは、熊本市と福岡市ですね。できるところは、課長を含めた職員の方々が視察に行ったということで、ぜひこれを反映させていただきたいと考えています。６月の委員会のときの資料ですと、世田谷区と荒川区と江戸川区の３区をモデル的確認実施区とすることが確認されたということで今進んでいると思うのです。","respondent":"二ノ宮児童相談所移管担当課長","answer":"委員がご指摘になった広域調整の部分は、先行３区プラス中野区、新宿区、港区など幾つか入っているのとは別に、各区が個別に都と協議している場もございまして、今、委員からご指摘のありました「みんなで子どもを守るまち・せたがや」というのは。","voiceIndex":40,"id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひとも来年度の実施設計を含めて調査研究をしていただいて、児童相談所移管に向けて進めていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-018"},{"speaker":"こんの委員","kind":"質問","question":"先ほどのハード面でもう一点お聞きしたいのですが、一時保護所で足立児童相談所の視察をさせていただいたときに、年齢に応じて、たとえ少数でも、何人か一緒のお部屋よりもプライベートが保てるようなお部屋が必要ではないかと考えますというお話を伺ったと思うのです。私もそれは非常に大事な観点であるかなと思います。特に中学生以降は思春期を迎える。","respondent":"二ノ宮児童相談所移管担当課長","answer":"男児・女児問わず、基本個室、場合によっては２人部屋もあろうかなというところで考えておりますが、委員ご指摘のとおりです。","voiceIndex":44,"id":"exchange-019"},{"speaker":"こんの委員","kind":"質問・要望","question":"あるいは４カ月、１歳６カ月健診未受診のお子さん、こうした年齢に応じて健診を受けていくわけですけれども、それが未受診だったときに、例えば保育園、幼稚園に通っていれば所在が明らかなので、そこと連携すれば所在も安否確認もできる。平成２９年度では、かなりの成果を上げていると承知をしておりますが、その辺をご紹介いただければと思いますが、いかがでしょうか。","respondent":"高山子ども育成課長","answer":"そのようなことができるのが区で児童相談所を設置する最大のメリットだと思いますので、そうした既存の児童福祉の部門と、新たに迎え入れる児童相談所の機能をしっかりと融合させて、このことを受けとめてまいりたいと感じています。","voiceIndex":46,"id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"少しご紹介がなかったのですが、お聞きしますところ、夜の時間帯に訪問する。それは、民生委員や児童委員が代わって、職員の勤務時間外のところをカバーしてやってくださっているということも聞き及んでおります。どうかこれからもその辺の連携もしていただきながら、児童相談所の役割もぜひお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6058#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":25416,"voices":52}},{"id":"h30-20180920-18","meetingId":"h30-cm09","date":"2018年9月20日","dateIso":"2018-09-20","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 ３時４０分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、特定事件調査","agenda":"の１、特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"このオリンピック・パラリンピック推進特別委員会は、４年前に立ち上がり、私は委員としてほぼ入っておりますけれども、その中で文化プログラムについてはさまざまに、提案も、質問も含め、させていただいてきました。ここについてどういうふうにすればいいか、まずどういうふうにお考えになっているか、お聞かせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"品川区文化芸術振興協議会というものが今年できまして、さまざまな芸術をされていらっしゃる団体の方が一緒になって、今現在、２０２０年に向けて何ができるか、何か一緒にできることがあるのではないかということで、いろいろ策を練っているところだと聞いております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問","question":"区のほうが一生懸命取り組まれているというのは理解しているのです。その上で、少し細かいことを伺います。先ほど部を挙げて取り組むということがありましたけれども、これはどういうコンセプトで、どういうふうに盛り上げて、これを区民にどういうふうに周知していくのか、改めて具体的に伺います。","respondent":"立川文化観光課長","answer":"ＵＮＩＴＥ ＨＥＡＲＴ ＦＥＳＴＩＶＡＬにつきましては、文化観光課が取りまとめておりますので、私からご説明いたします。","voiceIndex":7,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"改めて伺います。コンセプトはわかりました。部を挙げて、課を挙げて取り組むと、先ほどご説明がありましたけれども、今の説明だけでは恐らくさらっとした一過性のイベントで終わってしまうのではないかという危惧があって、区民の方にどういうふうに、２０２０年のオリンピック・パラリンピックとつながるのかということを伝えるのかという手段をお伺いいたしました。","respondent":"立川文化観光課長","answer":"このイベントの中身の説明を少ししますと、例えばこのイベントに参加していただきますと、いわゆるスポーツイベント、オリンピアン、パラリンピアンなどによるトークセッション。","voiceIndex":10,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ただ、先ほども何度も申し上げているように、区民の方へ文化プログラムとは何ぞやというところから、また区民の方に２０２０年の文化プログラムを盛り上げるために参加してくださいねと呼びかける、そういうところでの非常に大きな契機と、何度も繰り返しになって恐縮ですけれども、課を挙げて、部を挙げてというお話があったので、そういうところももう少し意識をしていただいて、スポーツは当然。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今回のＵＮＩＴＥ ＨＥＡＲＴ ＦＥＳＴＩＶＡＬを使って、その中でもまたさらに、文化からも盛り上げていくのだということを、目でもわかるような形で表示したり、伝えていけるような仕掛けをしていきたいと考えています。","voiceIndex":12,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"提案","question":"今回障害者福祉の担当の方はいらしていないのですけれども、例えばこの２０２０年に照準を合わせて、区内中の障害者の方の作品を展示する等、たしか以前にも提案させていただいたことがあるのですが、町内会等も含めて、町も含めてそういうことをやれば、例えば区内競技を見に来られた方が、そういったものも見に来られることも可能でしょうし、そういったことについてどのようにお考えになるか。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"例えば区内のいろいろな施設でも、そういった取り組みがされているところで、今は施設等で障害者作品展などが単体で行われているだけですので、それをまた東京２０２０大会にどう結びつけるか、今後の課題ではありますが、何かうまく結びつけて。","voiceIndex":14,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"非常にわかりやすく、また行政ともつなげやすい、福祉ともつなげやすいというところで、シンボリックなものになるのではないかと思いますので、ぜひご検討をお願いしたいと思います。ここから随分、２カ月、時間がたっています。今、どのぐらいの糾合ができて、どういう発信をこれからされていくのか、最後にそれだけお伺いしたいと思います。","respondent":"立川文化観光課長","answer":"そのグループごとにどういった、いわゆる機運醸成に係るイベントを実施するかという具体的な中身を協議していただくという、そのスタートラインに立つ直前です。","voiceIndex":16,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問・要望","question":"あえて数は伺いませんけれども、私がそのとき感じたのは、区内を代表するような芸術家団体、非常に名前が通っているような方たちがやはり表に出られていました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つかお聞きしたいと考えています。これはお願いだけにしておきます。私が聞きたいのは、しながわ文化プログラムについてということで、区の伝統文化の魅力発信や新たな文化の発掘等と書かれていて、これが今、３２件あるということですが、こういうのがあって、伝統文化の魅力発信ができてよかったと思っているとか、新たな文化の発掘ができたと思うような、実例があれば教えていただきたいです。","respondent":"辻オリンピック・パラリンピック準備課長、いながわ委員長、安藤文化スポーツ振興部長","answer":"けんちくのしくみ２０１８」というものですとか、神明雅楽などを認定しているところで、雅楽などは新しいものかなと思っているところです。石田秀男委員は、魅力の発信とか、発掘に関して具体的な事例をということを聞いていると思うので、その薪能というのは多分魅力の発信だと思いますし。今後そういうことで、文化芸術振興協議会を十分活発に動かして、文化プログラムに結びつけていきたいというふうに考えています。","voiceIndex":19,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"私の言いたいのは、例えば神楽でも、雅楽でも、建築模型という話でもいいのですが、区内の方々が活動してこられていて、それが区としても、これは区民の方々に広く、部長がおっしゃったように知らしめていこうという判断があるではないですか。魅力があると思われているから指定されている部分もあり、活動をずっとしてきているわけではないですか。その辺のお考えはどうか、お聞きしたいです。","respondent":"安藤文化スポーツ振興部長","answer":"そういうものも、意思に基づいて使っていただいて、あらゆる手段に対してＰＲしていき、２０２０年以降も継続してそれが発展していけるような工夫を、今考えていたところですので、今後、また皆さんと話し合って、続けて行きたいというふうに思っています。","voiceIndex":23,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"これは決算特別委員会でやろうかなと思っていたことなので、頭出しだけしておきます。別にどうということはないわけですから。そういう動き、区がバーチャルとしてこういうふうにしていくのだとか、それは品川歴史館も使えるかもしれないし、そういうことをして、これは文化プログラムですけれども、それを観光に結びつけていくとか、そういう方向性というのは何かお考えなのでしょうか。","respondent":"安藤文化スポーツ振興部長","answer":"４年目になりますけれども、私どもの部が今、文化スポーツ振興部ということで、観光行政を取り込んです。その中で、伝統の文化、今の品川歴史館の話ではないですけれども、品川歴史館において琴の伝統文化の発表をさせていただいたり、そういうものも地道にやっているところです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"提案","question":"アール・ブリュットという言葉を使わないでほしいというお話がありましたけれど、アール・ブリュットという言葉は、前に一般質問でもやりましたけれど、１９６０年代にジャン・デュビュッフェというフランス人の方が、いわゆる生のままの芸術ということで定義をされました。そういう意味での流れがあるということは私も存じ上げていますので、これはご理解いただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-011"},{"speaker":"大倉委員","kind":"質問","question":"例えば先ほどのしながわ文化プログラムのバッジも、「これ何ですか」と聞いた人に、説明をして、さらにそういう人たちに広げていってもらう。よくわからないけれども、何か関心があるというところの人たちにアプローチしていくという視点が必要なのかなと思っているのですけれど、その辺の考え方について、お聞かせください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今までそういったところから申請があったとき、私どもは、文化プログラムとはこういうことですので、皆さん、広めてくださいねと説明するとともに、バッジを差し上げていたというような状態です。","voiceIndex":30,"id":"exchange-012"},{"speaker":"大倉委員","kind":"意見","question":"今、バッジの話をしていただきましたけれど、例えばイベントも含めた、このGOOD PARK! 2018は大井どんたくに合わせてやって、よりいろいろな人たちに見てもらおうという形をとったというようなお話も聞いています。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今までですと同じ日に重なってしまいますと、お客様の取り合いのようなイメージもあったかもしれないですが、これからは、わざと同じ日にセッティングをして、相互に宣伝をし合い、相乗効果を出すということについて、今後も研究してやっていきたいと思います。","voiceIndex":32,"id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういった中で参加し、こういうのがあるのだ、品川はすごいね、品川区でこういうのをやっているよとほかの人にもアピールしてもらい、まさに先ほどの缶バッジではないですけれど、広がっていくという中で、ちょっとやってみようと、品川のそのすごい取り組みに自分も参画する、それこそ地域愛、地域プライドみたいなものを持ってもらうというところまで、見て、やっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"果たして、その一体感というところをつくっていくにあたって、このしながわ文化プログラムが３８万、３９万区民お一人おひとりの中に、どれだけ認知されているのか、その一体感が、この間取り組んできた中でどれだけつくれたという認識なのか、まずそこを教えていただきたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"文化面でのといいますか、オール品川で取り組むという一体感や、周知の程度ということですが、今のところ認知度としてはやはり、参加している団体の方はご存じですけれども、全体から見ると多いとは言えないかなというふうに認識しております。","voiceIndex":37,"id":"exchange-015"},{"speaker":"つる委員","kind":"質問","question":"ですからブランディングではないですが、この文化プログラムについてもやはり行政の中のセクションとしては広報広聴課が、区のさまざまな施策の発信母体となるわけで、この辺の連携というのは庁内でどうとりながら、区民への伝え方をやっているのか、庁内での連携とか、チラシの作成一つとってもそうだと思うのですが、このあたりがすごく気になるところであります。","respondent":"中山企画部長","answer":"いずれにしてもプロモーションの観点であったり、全庁的な周知の中に、いろいろな個々の事業の盛り上げと同時にその主旨、本日議論になっている文化プログラムの位置づけの中でやっていくということは、今後係るさまざまなメディアの中でも。","voiceIndex":39,"id":"exchange-016"},{"speaker":"つる委員","kind":"質問・要望","question":"区民の方が、区外の方とか国内外にかかわらず伝えていただく担い手になるわけですから、その人たちが魅力を感じて、また文化プログラムを含めて伝えていただくとか、取り組んでいただく、主体者を一人でも増やしていかないといけないと思います。さまざまな課題がある中で一生懸命取り組んでいただきたいと思いますし、先ほど言った区民運動になるようなものを、何か一つやっていただけたらと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"前回のときにもしながわ文化プログラムのデザイン料を伺ったかもしれないのですけれども、このバッジの量、金額、あとその予算はどこから来ているのかというのを教えていただきたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"こちらはただいま見積もりをとっているところで、まだ作成ができておりません。それほど高いものにはならないかと考えています。","voiceIndex":42,"id":"exchange-018"}]},{"id":"topic-02","title":"ボランティアの募集","agenda":"ボランティアの募集","exchanges":[{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのが、応募資格のところで１８歳以上の方ということですが、例えば小学生とか、中学生とか、それこそオリンピック・パラリンピックのキャラクターのときも関係している中で、そういった方たちも参加できないのでしょうか。１８歳以上のみなのか。小学生、中学生といった子どもたち向けの何か考え方というのがあってもいいのかなと思うのですが、教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"小中学生向けの区独自ボランティアですが、今回募集するのは、イベント等にボランティアとして参加していただいたり、道案内ということですので、なかなか小中学生ですと難しいかなです。","voiceIndex":50,"id":"exchange-019"},{"speaker":"大倉委員","kind":"質問・要望","question":"区市町村推薦枠のほうは、都からということで分かりました。１点だけ。小学生とか子どもたちがぜひ参加できるようなボランティアや、体験ができるような取り組みを考えていただきたいと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-020"},{"speaker":"塚本委員","kind":"質問","question":"もう一つは、都市ボランティアの中での区市町村推薦枠、１５０人が上限とございましたけれども、区独自ボランティアが両方兼ねるようなことは、考えられるのかどうかということについて、お伺いしたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"都市ボランティアと区独自ボランティアのすみ分けというようなことですが、都市ボランティアの人数とか配置の場所とか、その辺がまだ明らかにされていないので、難しいところですが、例えば大井競馬場前駅から会場までの間に、都市ボランティアの道案内が１人や２人だと。","voiceIndex":53,"id":"exchange-021"},{"speaker":"塚本委員","kind":"質問・要望","question":"区独自ボランティアにお願いすることというのは今後出てくるだろうということですけれども、募集人数が一応５００人ということで、活動期間も、大会期間を除いて前後に非常に長い期間があるということで、これは基本的にオリンピック・パラリンピックに興味がある方というのが応募資格になっているので、オリンピック・パラリンピックにかかわるボランティアということが前提だと思うのですが。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"区独自ボランティアの方の活動内容で今のところ考えておりますのは、オリンピック・パラリンピックが始まる前までは、私どもが開催するイベントのお手伝いがまずありますので、こういったイベントがあります、こういうお手伝いの方がいてくださると助かりますということで。","voiceIndex":55,"id":"exchange-022"},{"speaker":"塚本委員","kind":"意見","question":"わかりました。いずれにしても登録していただいた方が、登録した甲斐があるといいますか、せっかくそういう気持ちを持って応募される方たちですので、ぜひやってよかったと思えるように、さまざまな形での活躍の場を提供していただけるよう、お願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問","question":"区独自ボランティアについて伺いたいのですけれども、勉強不足で申しわけありませんが、区独自ボランティアというのは全ての区で設置するものなのでしょうか。その辺を教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"やろうと思っている区がやるということで、私の知っているところでは今のところ渋谷区が、独自ボランティアを予定しています。豊島区は、応援団というのを掲げる形でやっていると聞いております。江東区もこれからやるというふうには聞いております。","voiceIndex":58,"id":"exchange-024"},{"speaker":"田中委員","kind":"意見","question":"やはり都の状況がわからないということで、手を挙げない区が多いのではないかというお話もあったとおり、これを読んだとき、どういう内容のボランティアをしていくのかとか、観光案内といっても知識がないと難しいのではないかと思ってしまったりするので、９月２６日から募集を開始するということですけれども、やりたいと思った人に具体的な中が見えてこないのではないかというのを、ちょっと思いました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"なので、その中で身につけるのかなというふうには思っております。私どものほうも、観光と書いてはありますが、難しいところもありますので、そこは今後、検討するところです。","voiceIndex":60,"id":"exchange-025"},{"speaker":"田中委員","kind":"質問","question":"区独自ボランティアのところで、健康に自信がある方というのがあるのですけれど、これをわざわざ書いた意味、ここに明記した意味を教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"今年の猛暑を考えますと、やはり健康に自信のない方に従事していただいて、具合が悪くなったら本末転倒ですので、そこは健康に自信がある方というふうに明記させていただいたところです。","voiceIndex":62,"id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"もう一つ、その他のところで区独自ボランティアは報酬なしでボランティア保険だけはしっかり掛けるという中で、大会と都市のボランティアにはユニフォームの支給があると思うのです。区の場合は、レベルの差はあると思うのですけれど、それに準ずるようなものを用意する考えがあるのかどうか、教えてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"それから支給物品ですが、大会ボランティア、都市ボランティアはおそろいのＴシャツとかいろいろあると思います。区独自ボランティアのほうも、何の物品にするかは検討中ですが、同じように一体感の出るようなものを支給するつもりでおります。","voiceIndex":64,"id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"もししないのだったら、しっかりと期間中ということで募集を打って、また別の形でお手伝いいただくほうがいいのではないかと思います。それと大会ボランティアと都市ボランティアのほうは、来年２月から５月が面接とか研修という段取りになっていると思うのですが、品川区の場合も基本的に同じようなスケジュール感でいいのかというのを、最後にお伺いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"その方が従事する前に簡単な研修、ボランティアの心構えとか、そういったものはアナウンスするつもりではいます。従事する内容によっては、研修の内容とか長さといったものが変わると思いますが、もう少し手軽にできるようにというふうに考えております。","voiceIndex":66,"id":"exchange-028"}]},{"id":"topic-03","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"田中委員","kind":"質問","question":"大会と記念事業についてですけれども、やはり障害のある方たちへの周知のところが、いつも気になっています。団体の方たちへの告知などはいつもご答弁いただくのですけれども、それだけではなく、こちらからも呼びかける動きというか、そういうものがあったらいいなと思います。障害のある方たち一人ひとりに情報が届くような周知をしてほしいのですけれども、何かありますでしょうか。","respondent":"池田スポーツ推進課長","answer":"ホームページや広報紙等でもご案内しているところですけれども、さらに周知については研究するよう、努力いたします。","voiceIndex":72,"id":"exchange-029"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"最初に申請した時点で、今、課長がおっしゃった大井ふ頭中央海浜公園という正式名称で申請しているので、それを変えることはできないと、そういう意味で、一番最初に戻った、そういう回答だったと理解しています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"意見","question":"私が聞きそびれたのかどうかわからないのですが、１番のところで、我々は常々、ホッケー会場の多目的利用の話をしてきたと思っています。ここで意見交換しておかないと、そのままになってしまうのではないかと思っていて、多目的利用をするのであれば、芝のこととかをどうするのかというふうに、必ずなると思っているのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":82,"id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"確認","question":"そのときに話してもいいのですが、多目的利用って相当方向性が変わると思うのです。ホッケー協会は聖地だという話をしているし、我々区としては多目的利用できるように、という話をしているのだと思っているのですが。大分違うと思っているので、どうなのかなと。この委員会では、多目的利用という確認は何度もさせていただいていると思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"先ほど熱中症予防対策ということにとどめてしまって、私たち会派が出した意見が消去されてしまったという、その辺の判断はどういうふうにされたのか、一つ伺いたいのと、その場面で意見として申し上げておきたいというふうには思っているのですけれども、いかがなものでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-033"},{"speaker":"南委員","kind":"提案","question":"ですから、私たちはそういうことをもっと考えていくべきだという提案もし、大会組織委員会にもそういう意見は届いているとは思いますけれども、どういうふうにそこを考えていくかというあちらの見解も、せっかく行くのですから伺いたいと思うのです。ですから、ぜひそこは範囲を広げていただいて、発言は許していただきたいと考えていますけど、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"確認","question":"今、正副がおまとめいただいたものについては、私も先ほど大変気を遣って、皆さんの前で多目的利用をするというのも確認しながら、行政側もどうだという意見をまとめて、出しているつもりです。暑さ対策として時間調整、こういう時間帯にというのはあるかもしれないですけれども。私は現実的でないと思うし、それならどういうことで暑さ対策ができるかという議論をしたほうが、よほどいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-035"},{"speaker":"南委員","kind":"質問","question":"前倒しをするなら現実的ではないという表現は妥当性があるかもしれませんけれども、先送りするわけですし、遠い将来に先送りするわけではありません、９月か前回やった１０月が適切ではないかという意見は、一般的にはたくさんありますよね。ですからそういう点で、やはりこの委員会として発言をしていく、そういう声も届けるということを重要に捉えていくべきだと、そういうふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-036"},{"speaker":"塚本委員","kind":"質問・要望","question":"大会組織委員会との意見交換ということであれば、大前提として委員会として一つの合意というか、要望事項等に含まれているものが一つの下敷きになるかもしれませんけれども、そういうものに沿ってなされるのが妥当だろうと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-037"},{"speaker":"南委員","kind":"意見","question":"もちろんこの委員会でそういうふうに言うのはまかりならぬと、そういうふうに皆さんが意見を出されて却下されれば、それは従おうと考えていますので、ぜひ全会派の、一人ひとりのご発言をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":92,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど暑さ対策について、ミストの設置というお話を委員長がされていたので、そこの部分だけを要望するとかではなく、というところを言いたかったのです。対策についてどのように考えているのかということと、ミストに限らず、命を守る対策をきちんと進めてほしいということについて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6544#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":34200,"voices":103}},{"id":"h30-20180921-10","meetingId":"h30-cm09","date":"2018年9月21日","dateIso":"2018-09-21","committee":"議会運営委員会","time":"午後 １時００分～午後 １時０９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5300#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":3518,"voices":22}},{"id":"h30-20181015-10","meetingId":"h30-cm10","date":"2018年10月15日","dateIso":"2018-10-15","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時００分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"たします。 なお、議席の変更届については、先ほどの説明にもありましたが、議運終了後お配りしますので","agenda":"たします。 なお、議席の変更届については、先ほどの説明にもありましたが、議運終了後お配りしますので","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"局長に確認させていただきたいのですが、この資料No.２では、補選前ということで区民委員会、厚生委員会が７名、７名ということを資料として出されましたけれども、改めて現在、委員会としてあいている空席がどこに幾つあるのかということを教えていただきたいと思います。","respondent":"久保田区議会事務局長","answer":"補選が終わった後の常任委員会の委員の数ですけれども、区民委員会が７名、厚生委員会が７名、建設委員会が西本議員が失職したことによりまして７名となっているものです。","voiceIndex":12,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"基本的なルールとしては、そのあいた３つの中から選ぶことができるというルールでいいのか確認だけお願いしたいと思います。","respondent":"久保田区議会事務局長","answer":"今、欠員になっている中から選んでいただくですので、議運の中でお話し合いをした上で決めていただければと思います。","voiceIndex":14,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"委員長の提案ということは、区民１、厚生１ということでの提案なんですけれども、共産党として、おくの晋治が当選をさせていただきまして、今回、新議員ということになったわけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-003"},{"speaker":"石田（し）委員","kind":"意見","question":"本来、区民、厚生が、都議選で失職された２名のあいている分であり、今回の補欠選挙というのは、その２名分の補充の選挙であるという意味でいけば、そのまま区民、厚生という枠でいいのかなというふうに思っていますので、委員長案に賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"補選前にあいていた、そこの委員会を埋めなければならないというルールは、この議会の中にはないわけです。あるのですか。そこのところを、補選前に……。〔「委員長」と呼ぶ者あり〕ちょっと待ってください発言中なので。〔「さっきと同じこと聞いているじゃない」と呼ぶ者あり〕 補選前に……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"いや、そういうふうにされては困りますので、改めて発言をしているわけです。改選前のものにしなければならないという理由はあるのかどうか、局長に確認をさせてください。","respondent":"久保田区議会事務局長","answer":"改選前にしなければならないルールというものは特に規定はございませんけれども、議運の中でお話し合いをしていただいて、割り振りを決めていただくというのがルールだと思います。","voiceIndex":23,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"だから、補選前の２名の欠員のところに、埋めなければならないというルールはどこにもないわけです。それで、現在３つのポストがあいているわけです。その中で、希望しているわけですから、その希望のところに入れないというのは、委員長としての考え方はどういうことで提案をされたのですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この２つの委員会を埋めるための補欠選挙だったというふうなことではないと思うのです。補欠選挙というのは、４０の定数に足りない分について補欠選挙を行うというのがルールなわけです。それなので、本人が希望したい、また、会派として希望したい。なぜ、その希望が受け入れられないのかというふうなことを説明してください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"現在あいているのは３名なわけです。３つの委員会があいているというのが事実なのです。そこの中で、この委員会を希望しているわけですから、そこの希望が認められない理由というのが……。〔「認められない理由はないですよね」と呼ぶ者あり〕 認められない理由というのが何かあれば聞かせてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"本人は、今現にあいている３つのうち建設委員会を希望したいという意思があるわけです。付託を受けているわけですから。誰もかれもなれるわけない」と呼ぶ者あり〕 ですから、議員が付託を受けて、みずからの使命を果たすための権利を行使するときにそれを妨げる障害があるとすれば、特別なものがあるのであれば別ですけれども、特に何もないわけじゃないですか。あくまで委員長の案ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"意見","question":"今回は、２名の方が都議選に出られて、そこの中で補欠選挙が２名ということで決定をしたということです。今おっしゃったように、自分が希望するからどうこうという話ではなくて、それで言うのであれば、来年４月に選挙があったときに４０人が選出されて、その中で会派構成も出た中で、議運の中で会派構成、それでは我々の会派が１０人であれば２人ずつ５常任で、会派の中で選出してください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"３つあいているわけですから、現に今。今の時点で。この２人がかぶったということならば、それは自民党とも調整が必要だと思います。だけれども、かぶらないのであれば、なぜ本人の希望を認めないのですか。しかも、それは希望すればできるというルールになっているにもかかわらず、そのルールを委員長として認めないで、それを押しつけるというやり方は横暴ではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"だから、これは希望を通すというふうなことで、ルールにのっとってやるべきだということで言っているわけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"提案","question":"指名されてから発言してくださいね。先ほどから石田秀男委員とか本多委員が言っているとおりだと思いますし、先ほどからかなり一方的な押しつけのご意見を拝聴していましたけれども、１つだけ決まっているルール、これは議運の話し合いで決めるということ。それで、私どもの会派の意見としては、委員長がご提案をされたこの案に賛成だということは、ここではっきりともう一度申し上げておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-014"},{"speaker":"飯沼副委員長","kind":"提案","question":"それに不都合があるのかどうか。どうでしょうか。〔「初めからそう言ってくればいいんだよ」呼ぶ声あり〕 委員長案は出ましたけれども、ぜひ意見を聞いた上で、どうでしょうかというところなので、問題がなければというか、よりよい方法で進められたらいいのではないかなという提案なので、ぜひご理解をいただきたいと思っての提案なのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-015"},{"speaker":"石田（し）委員","kind":"意見","question":"会派構成だったり、それこそ無所属の方たちというのは、限られた枠の中で入るわけなので、みんながみんな希望に沿うことというのはないわけで、今回は補充の２名というのは区民委員会と厚生委員会に所属をされていた方たちの２名なので、我々としてはそのままその２つの空席を埋めるのがすんなりといくのではないかということで委員長案に賛成をしたということなので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"２つの空席があるので、そこを埋めるのがすんなりする。それも一つの考えであると思います。でも、先ほど私が申し上げたのは、建設委員会を一つ埋めることで何か全体的に不都合があるのかどうか。だから、建設委員会を選ぶことに不都合があるのかどうかというところをぜひ聞かせていただきたい。なければ、希望というか、そこがあいているので選ばせていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問","question":"別に建設委員会がどうしても８人にならなくてはいけないとか、どこの委員会がどうだとかというのはないわけで、あくまで５つの常任委員会があって、各委員会それぞれ必要なもので、委員会が設置されているので、逆に区民委員会と厚生委員会、委員長案の２名の補充に対して逆に不都合があるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-018"},{"speaker":"飯沼副委員長","kind":"質問","question":"そういう質問に対してはどう答えていいのかわかりませんが、３つの委員会というのは同じだと思います。そういった意味において、どこを選ぼうと同じではないか。そういった面で、特に建設委員会を選びたいということに対して、先ほどから聞いていますけれども、何か不都合があるのでしょうか。３つとも同じだと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"提案","question":"不都合がどうとか、希望がどうということはここで議論している話ではなくて、今委員長が提案しているのは、そこの２名の方々の補充の部分でやっているので、委員長案があるので我々はそれでいいでしょうということを意見として言っていること。その欠員が生じた中の補充をするという話をしているわけで、それはその構成でいいのではないですかということを話しているだけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４年前の改選のときに、少数会派も含めてここの委員会に所属したいとかという、さまざま希望がかなわないということは確かにあると思います。今回は、改選前は区民と厚生ということですけれども、現在は建設も含めて３つあいているわけです。それを多数決という形ではなくて３つの中から選ぶ、かぶった場合は調整をするという形で議運の中でも決めていくべきだと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"こちらも重要な案件だと思うのですけれども、西本前議員がどこに所属していたのかというのを今、失念していますが、常任委員会のほうはなぜか補選前のものを出されて、資料No.６のほうは補選が終わった後の資料を出されていて、これから議論していくことになると思うのですけれども、それは整合性がとれていないといいますか、常任委員会のほうの構成をあえて補選前ということで。","respondent":"久保田区議会事務局長","answer":"議会改革検討組織のメンバーにつきましては、これから決めていただくものですので、そこで整合性がないと言われると確かに整合性がないのかもしれませんけれども、私どものほうとしましては、最新のものとしてこれをお示しさせていただいたというものです。","voiceIndex":47,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"ですから、やはり恣意的なものをどうしても感じてしまうといいますか、それであるならば、やはり常任委員会だって、今現に欠員が３つの委員会で出ていて、どこも大事な委員会ですし、その中で、２人が補充されたとしても、１つの委員会は必ずあきが出てしまうわけです。ですから、そこでやはり希望を考慮に入れても何も問題ないと思いますので、ぜひ……。今回、実際あったわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"自分の意見が１００％正しいというわけではなくて、これはあくまでも議会運営委員会でどのようにしていきますかという意見を皆さんに聞いている場なのに、自分の意見と違うからって「硬直化だ」というのは本当おかしい話なので、ぜひ発言を控えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-024"},{"speaker":"本多委員","kind":"質問","question":"５つの常任委員会は全て重要だと思うのです。共産党の要求をどうすればかなえられるかとずっと今考えていたのですが、会派内でメンバーを差しかえるとか、それは会派内で話し合いができるではないですか。もちろん本会議で「選任」という手続はありますが、そんなに希望、希望というのであれば、会派内で建設委員会１議席をメンバーチェンジするとかでいいのではないかというアドバイスをして終わります。","respondent":"久保田区議会事務局長","answer":"先ほど議会改革検討組織のほうで、私１点答弁が漏れたのですけれども、これを立ち上げるときに会派のほうで調整していただいて、都議選に出る方はもともとこのメンバーの中には入っておりません。","voiceIndex":51,"id":"exchange-025"}]},{"id":"topic-02","title":"そのように決定をいたします。 自民党・子ども未来におかれましては、議運終了後、附属機関等議会選出委員届を事務局までご提出ください。 次に、(5)議会改革検討組織","agenda":"そのように決定をいたします。 自民党・子ども未来におかれましては、議運終了後、附属機関等議会選出委員届を事務局までご提出ください。 次に、(5)議会改革検討組織","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"なので、その２名がご希望を出されて、まずは委員長に一任をしたいと、我々としては。〔「正副でしょう」と呼ぶ者あり〕正副、はい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-026"}]},{"id":"topic-03","title":"品川区長期基本計画策定委員会委員の推薦","agenda":"品川区長期基本計画策定委員会委員の推薦","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"そのためにも、議会選出の委員もそういう構成ですべきであると思いますし、できるだけ多くの会派を入れてほしい、入れるべきだと。具体的には、無所属品川と生活者ネットワークも委員に入れるという提案を議会に通して提案すべきではないかと思います。５名程度ということですので、やはり構成を重要視したほうがいいと考えていますので、そのような意見を述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはりドントというか、増やしたとしても、一定自民党が多いのは間違いないので、やはりすべての会派を入れていただきたいと思いまして、多様な会派構成にしてこそ、よりよい長期基本計画の策定になると思いますけれども。ぜひ、入れないという理由があれば……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私が言うのも変ですが、せっかく飯沼副委員長もいらっしゃるし、同じ会派の中でいろいろ……。それは正副案として、また改めて議運に出していただくとか、そういうことをしていただかないと、毎回今みたいに二度も三度も出てくるのであれば、それは今までのやり方を根本から変えるような発言を毎回されるのであれば、それは注意していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"議論をする場であるということと、決して多数決ではなく話し合いによって結論を導いていくというやり方はこれまでどおり踏襲していただきたいと思いますけれども、やはり新しくいろんなものに対応していくという意味では、意見は意見かもしれませんけれども、従来どおりでオーケーというのではなく、やはりそれと違った意見が出たときには議論をしていただきたいと思いますけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問","question":"石田秀男委員のおっしゃるとおりだと思うのですけれども、安藤委員は多数の区民の意見を反映させるために少数の会派のことをお話ししています。逆に伺いますけれども、比例配分、これは区民の代表である私どもの議席の数に応じて配分をするということだと思うのですけれども、逆に不都合があるのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-031"},{"speaker":"安藤委員","kind":"意見","question":"私がそう言っていることは、不都合というよりも、多様な代表で、いろいろな会派の方が区民の付託を受けて選出されているので、なるべくいろいろな会派が入ったほうがいいのではないか。そちらのほうに重きを置いて発言させていただいたということなので、比例で議席を案分するということ自体が全く民主的ではないとか、そういうことを言っているわけではないです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-032"},{"speaker":"あくつ委員","kind":"確認","question":"民主的ではないというわけではないということが今、安藤委員からも確認できたので、私も別に前例を踏襲しているということではなくて、民主的なやり方だからこれに賛成をしているわけですので、前例をそのまま踏襲しているようなご意見が飯沼副委員長からありましたけれども、そういうことではなく、民主的にのっとった形で一番わかりやすい形だからこれに賛成しますと申し上げただけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-033"},{"speaker":"石田（し）委員","kind":"意見","question":"意見をということだったので、我々の考えを述べますが、そもそも区長から議会に対して長期基本計画策定委員会のメンバーを議会として５名推薦してくださいという区長部局からの要請にのっとって、選ぶ手続だと思います。うちが何人とかどうこうというよりも、まずは区長部局から来ている内容について我々として、これで行きましょうと。","respondent":"久保田区議会事務局長","answer":"今回の比例配分で割り振りますと、前回同様、自民党・子ども未来が２名、公明党が１名、共産党が１名、国民民主党・無所属クラブが１名となるというものです。今回の選出方法についてご確認いただきまして、各会派で１０月３０日までに氏名報告を事務局までお願いいたします。","voiceIndex":99,"id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5302#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":19105,"voices":108}},{"id":"h30-20181024-10","meetingId":"h30-cm10","date":"2018年10月24日","dateIso":"2018-10-24","committee":"議会運営委員会","time":"午前１０時３０分～午後 ０時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の順番を入れ替えまして、予定表の３、平成３０年第３回定例会についての(1)理事者から発言を求められている件","agenda":"の順番を入れ替えまして、予定表の３、平成３０年第３回定例会についての(1)理事者から発言を求められている件","exchanges":[{"speaker":"本多委員","kind":"提案","question":"発言を求めます。本会議が明日から開かれますが、議会の正常化に関する決議を提案したいと思います。委員長、どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"お配りさせていただきました。明日の本会議に、議会の正常化に関する決議を上げたいと思います。現在、提出者は２０名で、表題は議会の正常化に関する決議であります。文面をお読みいただきましてご確認をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-002"},{"speaker":"飯沼副委員長","kind":"質問","question":"今、お読みになってということなので、ちょっと読み切れていないのですが、この取扱いについて、どのように取り扱われるのか、ちょっと教えてください。","respondent":"久保田区議会事務局長","answer":"議事日程の整理をしなければならないのですけれども、通常であれば一般質問が行われる前あたりにこの議案を入れるような形で、追加議事日程として入れていいかどうかというのをこの後確認をしていくという流れになります。","voiceIndex":12,"id":"exchange-003"},{"speaker":"飯沼副委員長","kind":"質問","question":"ということは、ここで別に議論することではなく、本会議場で議論をするということですか。","respondent":"久保田区議会事務局長","answer":"今、議会運営委員会でご提案が本多委員よりありましたので、この内容については議会運営委員会の中でいろいろご議論いただいた上で、最終的な採決については、これまでの例にならいますと無記名投票によって採決を本会議で行うといったことになってありますので。","voiceIndex":14,"id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"質問","question":"副委員長の立場でお聞きしますが、委員長はいつこれをお知りになったのか。正副の打合せを開いたばかりなのですが、ちっともこの件が出されていなかったので、今日突然なのかどうか、委員長は事前に把握をされていたのかどうか、お伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ぜひこういうことについては、事前に伝えてほしい。やはり議論をするかしないか、議論が深まるかどうかというのは、はっきり言って、今提出されて、まだ私も半分しか読んでいないのですけれども、これでこの場できちんと議論ができるかどうかというのは甚だ疑問ですし、私もびっくりしているのですけれども。これはちょっと、議論するのだったらはっきり言って持ち帰らせていただきたいぐらいの中身です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そのことと、それからあと、今、この趣旨が今ひとつよくわからないのですけれども、そこに書いてあるとおりですということなのですけれども、どういう趣旨でこの決議を出したのかというところを、今出された本多委員のほうから提案があったということなので、もう少しこの趣旨についてご説明いただきたいと思うのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-007"},{"speaker":"本多委員","kind":"意見","question":"５月２９日から約５カ月間におきまして、議会運営上ありました事柄から、やはり明日から始まる第３回定例会に向けては、今まで議会でも、議会の意思を出してきたわけですね。明日から始まる第３回定例会に向けて、いろいろと議会では議会の意思決定があったわけですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"結局この決議というのは正常化に関する決議ということですけれども、現議長のもとでも、「引き続き与えられた使命を全うすべく区政の課題に取り組んでいく」と書かれているということは、現議長のもとで今までどおりのというか、正常の議会運営のため自分たちは行動していきますよということを、改めて決議で出すということでいいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"出席するということを決議で上げる……。決議で上げなくても、前ももう既に出席もされていますし、そのまま出席すればいいのではないかなと思うのですけれども、そこをあえてこの決議という形で出された意味というのは何なのかということもちょっとお聞かせください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-010"},{"speaker":"本多委員","kind":"意見","question":"それは、議会人として議会の意思を尊重するがゆえに、こうした決議を出したいという思いです。思いはそういう思いです。はその決議を上げた上で、議会活動を進めていきましょうという趣旨です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問","question":"よろしいですかって、では取扱いはどうなるのでしょうか。ここで議論ということにこれ以上ならなくて、それを取り上げていくかどうかは、これは出されたのだから取り扱うということでいいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことであれば議論する場はこの場ということですので、ちょっともう本当に何名も議員がそろっているわけではないのですけれども、本当に私たちはこれを初めてここで出されて、これに対してどう考えたらいいのかというところの検討をする時間というのを、今、委員長のほうから言われたように、十分な検討はなかなか難しい状況ではありますけれども、休憩をとっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"意見","question":"私も、何のために正副委員長の打ち合わせをしたのか意味がない。やはり議会運営委員会もきちんと進めていく、あと、やはり各会派、区民の皆さんの意見を持っていらっしゃる。本当に充分に議論をして事を進めていくというのが、やはり議会運営委員会に与えられた使命だと思うのですが、このような出し方は甚だ遺憾に感じています。それだけはちょっと言っておきたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"意見","question":"それは今までそうしてきたけれども、正常化をしていこうという我々の意思の一つのけじめの部分であるならば、それはやはり議会運営委員会でしっかり議事日程にも入れていただいてやっていこうということで、いろいろ我々も議論はあったけれども、それはやはり動議という形ではなく、議会運営委員会に出して正常化を図っていこうということなので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-015"},{"speaker":"石田（し）委員","kind":"確認","question":"局長に確認をしますが、先ほどから提出方法についていろいろとおっしゃっている方たちがいますが、これは正式なルールにのっとって提出をされているのかどうか、確認をさせてください。","respondent":"久保田区議会事務局長","answer":"ただ、その正副委員長の打ち合わせ等ありますので、そこのタイミングでというのはあるとは思いますけれども、提出される方が最終的に提出をするという判断をどこでされたか、その時間的なタイミングというのもあるとは思いますので。","voiceIndex":36,"id":"exchange-016"},{"speaker":"石田（し）委員","kind":"確認","question":"正式なルールにのっとっているというのを確認をしまして、それに無理がない、普通にルールにのっとった提出方法をされているので、そのことに関してああでもない、こうでもないと言われても、ルールにのっとってしっかりと提出をされているので、そこはぜひご理解いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、ルールにのっとっているからいいのだということではなくて、やはりこれだけ大問題になり、これだけ議会の中を混乱させ、これだけ議論がされてきた問題ですから、この問題については、きちんと各会派がこれに対して改めてどう考えるかというところの検討の時間を取るということはやはり配慮していただきたい、配慮すべきものではないかということで、意見を申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-018"},{"speaker":"石田（し）委員","kind":"質問","question":"鈴木ひろ子委員から、もうこの件に関しては議論をたくさんしてきたと言っているのであれば、もう議論はされているのではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問","question":"いやいや、だって自分で今言ったではないですか。もう散々議論をしたと。ということは、各会派もそれなりの会派としての考え方というのをお持ちであるのであれば、この件に関して何ら大きな議論をするようなことであるのかという。自分でみずからがこの件に関しては議論をたくさんしてきたのだと言っているのであれば、今、ここでまた何かを今後議論するというのは必要なのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"すごく細かいことを言いますけれども、鈴木ひろ子委員の発言の中で、本会議に出席しなかったというお話がありましたけれども、今まで出席しなかったことは一度もないのです。定刻に集まらなかったことは実際ありました。ですから、今までそれを回避するためにここでやってきたわけでしょう。それを今までずっとやってきたということですので、正確な表現に気をつけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その議論をしてきたということですけれども、今回のこの決議に対しては、議論をしたことがありませんので、新たな決議ということで、決議という形で出たわけですから、それに対してはどう考えるのかというところをしっかりと団でも議論をして、そして意見を述べたいということで申し上げております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問","question":"委員長、言い忘れたのですみません。正副との関係については、先ほど「遺憾に思う」という表現がありましたけれども、そこに留めていただいて、そこはもう正副に我々は信頼をしてお任せしているわけですから、それをこの場で、ほかの方が言うのはいいですよ。ですから、あまりここでそういうことを言わないほうがいいのではないかなということは申し添えておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-023"},{"speaker":"飯沼副委員長","kind":"意見","question":"議会運営委員会が公開になりました。公開ということは、区民の皆さんにやはり運営のこと全てを知っていただくということで公開になっています。把握してどう受けとめられるのかというのを含めて、私たちは発言をし、行動をしなくてはいけないと思っているのです。そういった意味では、副委員長であろうと私が発言しても許されると思うので、今日は発言させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問・要望","question":"繰り返しになりますけれども、先ほどそのことは同じことを伺いました。そのことを何度も何度もおっしゃって、それで何か物事が進むのでしょうか。表明はしっかりと受けとめましたけれども、先ほど申し上げたように、副委員長という立場をしっかり尊重していただいて、進行していただきたい。このように考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この決議を改めて議員団のほうでも議論をいたしました。そもそも、この松澤議長の不信任決議ですとか、辞職や辞任を求める決議、この３本の決議そもそもが、議長職を辞めさせる理由が不当な理由であり、議長職を辞めなければならない理由には相当しないということで私たちは主張してきました。それが１点です。よって、今回の決議に対しては、共産党としては反対ということを述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-026"}]},{"id":"topic-02","title":"議会運営上の変更","agenda":"議会運営上の変更","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"定員というのはどこで定めたのか、ちょっと記憶が失念してしまったので、ちょっと教えていただきたいのが１つと、それと定員８名で、今７名ということで伊藤リーダーのほうからそういうお話があったのですが、できる限りやはり本人がやりたいということが活かされたほうが私はいいと思いますので、今回２名ということなのですけれども、一番望ましいのは２名とも入っていただくのが一番望ましいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-027"},{"speaker":"伊藤委員","kind":"意見","question":"定員のことについては議会改革推進会議で決めたことだと思われますので、私個人はどうこういう立場ではありませんけれども、ＩＣＴ推進会議としては８名以内で進めするわけでありますので、ご報告をします。","respondent":"久保田区議会事務局長","answer":"定員の話ですけれども、今、伊藤委員のほうからもありましたように、前身の会議体の状況等を踏まえ、平成２９年５月１９日の議会運営委員会の中で定員を決めていただきまして、それぞれ申し合わせ確認事項の中に記載をされているというものです。","voiceIndex":66,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"広報も議会報告会等準備会議のほうも、我が共産党の会派も複数入っていますので、ＩＣＴ推進会議に１人入っても問題にはならないと思うのですけれども、別に共産党が何が何でもＩＣＴ推進会議と言っているわけではなくて、２人とも今回当選されたということで、皆様そうですけれども、議員としての思いを持って議会に入ってきたわけですから、せっかく１名定員が空いているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"意見","question":"我々は、先ほども委員長から話がありましたように、芹澤裕次郎議員はＩＣＴという話をいただいたということで、我々会派の中では、今、伊藤リーダーからも話があったように、そういうことで広報、議会報告会等準備会議、それはこれから半年ということでもありますので、その中で様々ご本人は勉強したいという話は受けておりますので、今我々としては。","respondent":"渡部委員長","answer":"結局、広報と議会報告会等準備会議のほうは、かなり定数に対して欠員が当然生じている形での運営となっているということで、私自身もこの２つに割り振りしていただくのがいいのではないかと考えておりますが、他会派の方々のご意見を聞かせていただけますか。","voiceIndex":69,"id":"exchange-030"},{"speaker":"あくつ委員","kind":"提案","question":"これはフラットに伺いまして、どちらのご意見も本当に言い分もあるし、思いもあるなと思いましたけれども、できれば抽選とかではなくて、やはり話し合いで決めるというところで、私も今このご提案を初めて聞いたのですけれども、どちらも入りたいというところをどちらか１人入るのではなくて、確かに欠員が多いですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-031"},{"speaker":"石田（し）委員","kind":"質問","question":"我々としても、定員１４名のうち１０名、１４名のうち１１名ですから、広報と議会報告会等準備会議にそれぞれ１人ずつ入っていただければ特段問題はないかなと。そこは入られるお２人でお話をされるのか、議会運営委員会の正副委員長のほうで判断をされるかはお任せしますが、そちらのほうへ行っていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-032"}]},{"id":"topic-03","title":"決算特別委員会","agenda":"決算特別委員会","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"資料No.１５なのですけれども、実務上可能であれば、意見表明の原稿ですけれども、当日中に出すというのは、態度表明したものをもう少し編集しなくてはいけないので、ちょっと大変なのです。もし可能であれば、翌日とかそういったことにできないのか、そうしていただければ助かると思ったのですが。","respondent":"久保田区議会事務局長","answer":"すみません。１１月１６日が金曜日ですので、月曜日になってしまうと作業上厳しいところがありますので、できましたら１６日金曜日にお願いをしたいと思います。","voiceIndex":97,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5304#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":20493,"voices":118}},{"id":"h30-20181026-4","meetingId":"h30-c-settlement","date":"2018年10月26日","dateIso":"2018-10-26","committee":"決算特別委員会","time":"午後 ２時１６分～午後 ２時２３分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1450#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":1879,"voices":17}},{"id":"h30-20181029-6","meetingId":"h30-cm10","date":"2018年10月29日","dateIso":"2018-10-29","committee":"区民委員会","time":"午前１０時００分～午前１１時４０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２９年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２９年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"総括シートなのですけれども、情報量が少なくて、よくわからないというところがあります。具体的にどういうふうに下回ったのかというのがわからないという状況になっていますので、この改善を求めたいわけですけれども、事業報告書を一緒に添付していただきたいと思いますが、いかがでしょうか。経営会議に出されるときに、この資料１枚で経営会議でも議論が行われているのかを伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"事業報告書等につきましては、ホームページに掲載していますので、ご参考にしていただきたいということと、それから工房につきましては、先ほど申し上げたとおり、少し口頭で説明が必要なものについてはフォローするようなところで、もう少し詳しく申し上げますと、稼働可能時間。","voiceIndex":10,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"事業報告書についてはホームページに公開されているということなのですか。それは、この報告がされる前にホームページにアップされて、見ることができるということでいいのかと確認させていただきたいのですが。経営会議でいろいろ、議論の過程で資料が出てくるということなので、ここでもぜひ、事業報告書などの資料をさらに充実させていただきたいと思いますが、いかがでしょうか。","respondent":"山崎商業・ものづくり課長","answer":"委員会におきましても、指定管理の施設の適正な運営、あるいは改善が必要な事項といったものを議論していただく場ですので、そうした資料の最適な部分といいますか、そこは十分、本日の報告以外の部分にも係る話だですので、いろいろ研究してまいりたいです。","voiceIndex":12,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"ホームページアップというのは、ＳＨＩＰ以外のこともあるのですけれども、今のＳＨＩＰの話だとトピックだということなので、一部ということになるのかなという感じがするのですが、事業報告書全てがホームページにアップされているということでよろしいのかというところは確認させていただきたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"ただ、この施設がそれにどれだけ寄与しているのかということにつきましては、なかなか一口で説明するのも難しいところではありますが、本施設が開設して、いろいろ施設を利用して新しい事業を創業していくようなときに寄与するということについては、十分寄与しているかなと。","voiceIndex":16,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"体育館では、こちらでもいろいろ意見を聞いているということですが、アンケートとかの実施を考えていらっしゃるのか、また要望意見箱とか、いろいろ意見を聞いているところで、どういった意見があったのかということと、東京都の立入監査があったということで、おおむね良好という中身をもう少し、どういったところが評価されて。","respondent":"山崎商業・ものづくり課長、立川文化観光課長、池田スポーツ推進課長","answer":"利用者満足度の数字なのですけれども、満足度の数字を比較するときには、土台となるアンケートの仕組みだとか、そういったものが画一的に整理されて。荏原平塚総合区民会館については、事業も実施しておりますので、民間の相場よりもちょっと安い価格でコンサート等を実施しておりますので。体育館のアンケート、それから意見についての活用の状況についてですけれども、通常、要望意見箱というものを用意していますので。","voiceIndex":21,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"ＳＨＩＰのほうは、トータル的にニーズは高いということでしたけれども、今、ホールの稼働率も約９４％ということで、そういった稼働率が高くなってくると、収益上はいいのでしょうけれども、利用者が借りるとなると、またとりにくくなるのかなという思いもありまして、そういったところがこの利用の満足度に影響しているのかなと考えているのですが、このところの区の認識を伺いたいと思います。","respondent":"山崎商業・ものづくり課長","answer":"今ご指摘をいただいた面につきましては、区では今のところ、そういった考えはしておりません。３階につきましては、マグネットスタジオの管理運営の部分ですけれども、あの手のホールで稼働率が９０％を超えるというのは、非常に驚異的な数字です。","voiceIndex":25,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろなことがあると思いますが、いわゆるアンケートとかも行っていらっしゃいますので、ぜひ、全て４つの施設の利用者の意見をしっかりと聞いて、利用しやすいようにしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"細かなところなのですけれども、施設名称の部分で、品川区立品川産業支援交流施設は、（ＳＨＩＰ）とかというのを書いていないのは、何か意味があるのですか。区民満足度についてのお話があったのですけれども、そもそも区民満足の視点をどのように調査されたのか、それぞれお知らせいただけますか。","respondent":"山崎商業・ものづくり課長、立川文化観光課長、池田スポーツ推進課長","answer":"満足度調査につきましては、例えば項目としましては、接遇する職員の説明事務の正確さですとか、施設の備品・設備の清潔さ。満足度の関係です。こちらは両施設ともアンケートを実施しておりまして、その辺を分析した結果です。スポーツのほうは特段、満足度というところは記載がないのですけれども、ただ、ご意見・要望を聞いて。","voiceIndex":28,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"他区では財務のことは税理士などがモニタリングをしているということなのですけれども、区ではどういう形で財務に関してモニタリングを行っているのかということを伺いたいのと、労務のモニタリングについても、きっと区でも労務のモニタリングをしていると思うのですけれども、報告書にないのはなぜなのかということを教えてください。","respondent":"山崎商業・ものづくり課長、立川文化観光課長、池田スポーツ推進課長","answer":"会員が大体、先ほど個人・法人１５０程度ですけれども、有効回答が１０９ということでいただいております。アンケートについてお答えいたします。２種類あります。私どものほうですけれども、一斉のアンケートは特に実施はしてございませんが、イベントや教室等が終了するたびに、利用者からのアンケートを行うほか。","voiceIndex":32,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"労務についてもそれぞれどうなのでしょうか。伺わせていただきたいのですけれども。","respondent":"山崎商業・ものづくり課長、立川文化観光課長、池田スポーツ推進課長","answer":"すみません、私の先ほどの答弁は、区がまとめる側として、出された帳票についてのチェックという意味でお話ししたのですけれども、指定管理者として。事業団の労務の関係については、社会保険労務士等を活用して適正にやっていると報告をいただいているところです。私どものスポーツ協会においても、適正にやっているところですけれども、実際に労務関係についての変更等がありますと、理事会や評議委員会を通じまして。","voiceIndex":40,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"それぞれやられているというのは、よかったです。今後は労務のモニタリングの報告も、ぜひ資料としていただきたいと思うのですが、いかがでしょうか。","respondent":"堀越地域振興部長","answer":"これをどのように広げていくかということと、それから、モニタリングをしっかりするというのは、ポイントを絞ってしっかりチェックするというのが必要だと思いますし、それに伴って、モニタリングが見方によっては、一方でかなり事務的に煩雑になるとなりますと。","voiceIndex":44,"id":"exchange-010"},{"speaker":"田中委員","kind":"意見","question":"指定管理なので、がちがちなのはよくないとも思っています。もっと自由にあるべきとは思っているのですけれども、やはりチェック、モニタリングというのは、労務に関しては特に必要な部分だと思うので、今検討中ということだったのですけれども、ぜひ報告がされるように、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":46,"id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問","question":"ＳＨＩＰのところなのですが、ＳＨＩＰの設置目的のところにある「区民の地域活動を推進し」という定義の中で、区民の位置づけ。それと、ＳＨＩＰの稼働率のところ。それは実態上、どのように行政として捉えているのかを教えてください。何がいいのですかと言ったら、広報だとか、チラシ１つとってみても、企画がおもしろいと。インパクトがあると。そういう言い方をされました。その辺をどう捉えているか。","respondent":"山崎商業・ものづくり課長、立川文化観光課長、池田スポーツ推進課長","answer":"４階の事務室も１６室満室になっておりまして、ここもそうした民間の事業所に比較して、極端に安価で安いということではありません。完売御礼が多いですが、情報発信につきましてはさまざま工夫して実施してきたというところがありますので、その辺の成果かなと考えているところです。体育館の利用料金のことですけれども、確かに委員のおっしゃるように、日曜日については１００％近い利用率ということで。","voiceIndex":47,"id":"exchange-012"},{"speaker":"渡辺委員","kind":"質問","question":"それで、最後に伺いたいのは、２０２０年というものが、多分こういう全ての事業団にしろ施設にしろ、非常に大きなタイミングだと思います。伺いたいのは、まずきゅりあんのところ、施設の老朽化という記載もありました。どうしても場の提供というところに行き着くと思うのですが、文化の点もそうですし、スポーツの点とあわせて、活動の場の確保というのでしょうか、行政として。","respondent":"立川文化観光課長、池田スポーツ推進課長","answer":"今、委員ご指摘ございましたとおり、改修に合わせて、これまでなかなか直せなかった、いじれなかった部分についても、あわせて実施したいと考えているところです。その他、今、文化とスポーツということで、融合といいますか、一緒に、これからは競技スポーツだけでなく、レクリエーション的なスポーツも皆さん楽しみたいですので、そういった意味では今回。","voiceIndex":51,"id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"それぞれなのですけれども、事業報告書をもとに、その後、調査に入ったりということはしているのかということを伺いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"事業報告書が出ているから、それをネットで見てというのはわかるのですが、せめて、入りがこういうふうに出ているわけですから、大きく人件費等を含めて経費がどのぐらいかかって、どのぐらい残るかというのぐらいは、この１枚にまとめたいというお気持ちはわかるのですけれども、入りと出と、残るのがどのぐらいかというぐらいの数字は、私は出すべきだと考えています。","respondent":"山崎商業・ものづくり課長","answer":"平成２９年度の本施設の運営につきましては、１億６,０００万円ということで、収支は黒字で８,８００万円です。ここに所要の税の処理などを行いまして、平成２９年度につきましては、品川区に本施設運営の歳入として５,６００万円、区に戻っているという状況です。","voiceIndex":60,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"きゅりあんについてお伺いするのですけれども、他の委員から、きゅりあんはこのごろ、すごくいい企画で、そして評判がいいというお話のときの答弁に、「理事長はじめ」ということがありましたが、今の理事長はどういう経歴の方がやっているのか教えていただきたいのと、私はもう一つ、これは課長の答弁で抜けているなと思ったのは、理事長はじめ、職員の方というのはあったのですけれども。","respondent":"立川文化観光課長、池田スポーツ推進課長、山崎商業・ものづくり課長","answer":"区の職員のＯＢですけれども、今、正確な数字を持っていないのですが、管理職のＯＢは３名と聞いております。スポーツ協会です。スポーツ協会で区の元管理職としまして、１名行かれているです。一般財団法人品川ビジネスクラブには１名です。","voiceIndex":62,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"これは絶対プラスにして、連携をとってやっていかないといけないと思うし、思う気持ちで質問させていただいているので、これはよくわかってください。これからも、区の職員のＯＢの方々が、各指定管理者に行かれるでしょう。ぜひ連携をとって、行政が区民のためになるように一生懸命働いてくれれば幸いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-017"},{"speaker":"浅野副委員長","kind":"質問","question":"最初に、品川産業支援交流施設について質問します。指定管理業務の概要ということで、（３）の承認の取消しですとか、使用の停止、使用条件の変更に関することとなっているのですけれども、こちらの承認取消しですとか使用停止についての基準というのでしょうか、どういうことをしたら、このような罰則が適用されるのかということについて、１つ教えていただければと思います。","respondent":"山崎商業・ものづくり課長","answer":"知的創造空間で、例えば満員電車のように１００％がいいのか、一定程度空間ですので、そのあたりは現状をいろいろ研究しながらということですが、今、４階のラウンジでは、電車に例えるとあれですけれども、１００％混み合っているという状況にはありませんので。","voiceIndex":68,"id":"exchange-018"},{"speaker":"浅野副委員長","kind":"質問・要望","question":"もう１点、別なのですけれども、体育館で、こちらは非構造部材の耐震化工事で順次休場があって、トラブルなく工事が終わったと聞いているのですけれども、最近、非構造部材ということもなかなか聞かなくなったということは、これは品川区としても定着がしたのかなと私は考えております。これは要望で終わりますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-019"}]},{"id":"topic-02","title":"今定例会の一般質問に係る所管質問ですが、本定例会の一般質問中、区民委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問ですが、本定例会の一般質問中、区民委員会にかかわる項目","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"委員長にいつもお許しをいただいて、質問をその他でさせていただいているのですけれども、前々回でも質問させていただきましたが、五反田で何十億円という詐欺、マスコミ等で大分、前々回か前々々回質問したときよりも進展があったということで、今わかる範囲でいいので、特に品川区という意味で注目される事件の一つですから、ちょっと説明を生活安全担当課長からしていただければ幸いです。","respondent":"菅生活安全担当課長","answer":"これは捜査二課というところが事件を担当しておりまして、詳細についてはなかなかわからないところもありますけれども、報道等によりますと、１０人目の逮捕者が出たと聞いております。まだ全部の事件解明まではされていないということで、主犯格とされている男もまだ逃亡中です。","voiceIndex":76,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2822#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":27829,"voices":78}},{"id":"h30-20181029-7","meetingId":"h30-cm10","date":"2018年10月29日","dateIso":"2018-10-29","committee":"厚生委員会","time":"午前１０時００分～午後 ３時７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第７８号議案、品川区公衆浴場の設置場所の配置および衛生措置等の基準に関する条例の一部を改正する条例","agenda":"第７８号議案、品川区公衆浴場の設置場所の配置および衛生措置等の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それが平成１５年２月１４日に国から通知が来た、技術的助言として作成している「公衆浴場における衛生等管理要領」において、「毎日完全に換水して浴槽を清掃すること」、ただしということで「週１回以上完全に換水して浴槽を清掃」という記述もあるということで、この平成１５年に技術的助言があって、それを現在平成３０年に実施する理由も伺いたいなと思います。","respondent":"鈴木生活衛生課長","answer":"１点目の近年の衛生状況、環境等の向上の理由ですが、一つには機器等の性能の向上が考えられると思います。","voiceIndex":8,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、２３区内ではほかは第３回定例会が終わってきていると思うのですけれども、そこではどこがこの条例改正をしたのかというのは把握されていないということですか。もしもわかれば、もう結構進んでいるのかどうかというのを伺いたいなと思ったので、お願いしたいと思います。一般的に感染力は強くないそうですが、新生児や高齢者、糖尿病や透析患者などハイリスクな方は感染しやすいとされています。","respondent":"鈴木生活衛生課長","answer":"委員のご指摘にもありましたように、路上や河川等通常の場所にも存在する菌であって、また感染力も弱いというところがありますが、基本的には毎日換水をしているということで、お湯を入れかえた時点で１回洗浄・消毒をして、その都度きれいになる状態ですので。","voiceIndex":10,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういうところでは専門的知識のないもとでの衛生管理になってくるかと思うのですけれども、講習とか研修、そういうことを区あるいは保健所としてやったり周知といいますか、安全性を高めるためにそういったことはされているのかどうか伺いたいと思います。それで、週１回以上の換水で良いとされる要件、1)、2)、3)を満たす施設は区内にどれくらいあるのかを伺いたいと思います。","respondent":"鈴木生活衛生課長","answer":"実際に週１回の換水が認められるためには保健所に届け出が必要になりますので、その届け出があった時点で改めて保健所のほうで現地の施設の調査に入りまして、要件を満たしているかどうかを確認した上で、週１回の換水を認めるという形になります。","voiceIndex":12,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"意見","question":"該当する施設が区内に何件あるかっておっしゃっていただけましたか。今要件３個を満たすものを言っていただいたのですけれども。聞き逃していたらすみません、もう一度お願いしたいと思います。この公衆浴場の条例に該当する区内の施設の数。","respondent":"鈴木生活衛生課長","answer":"区の衛生の基準等が適用される公衆浴場ということであれば、総数は平成２９年度末、今年の３月で６０件になります。そのうちこの３要素を全て満たすものが、先ほど申し上げた５件ということになります。","voiceIndex":14,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"ちょっとできれば内訳を教えていただけたらなと思うのですけれども、この６０件のうち銭湯が幾つでとか、多分シルバーセンターのお風呂とかも入ってくるのかなと思うのですけれども。それから要件を満たす５件のうち、その他の２件は何なのか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"その他の２件、３つの要件を満たす５件のうちのその他の２件は何なのかというのも伺ったのですけれども。これが品川区内のどういった施設でこの条例が改正されることで週１回になっていくのかというのを知りたかったので伺っているのですけれども。なので、その他の２件というのは内訳がわかれば教えてください。","respondent":"鈴木生活衛生課長","answer":"済みません、手元に台帳を全て持ってきていないので、要件に該当する件数を申し上げたのですが、その他に含まれる施設としては、先ほど申し上げましたように、シルバーセンターのお風呂であったり。","voiceIndex":19,"id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今公衆浴場の対象になる施設が、銭湯が２４件で、シルバーセンターがゆうゆうの２カ所も入れて１０件で、サウナ等が２４件で、個室つき浴場が２件でしたよね。そうしたら、スポーツジムというのはどこに入るのでしょうか。","respondent":"鈴木生活衛生課長","answer":"一番最後のシルバーセンター等というくくりでカウントしております。","voiceIndex":21,"id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"シルバーセンターでたしかお風呂があるのが８カ所で、ゆうゆうが２カ所で、これで私は１０件かなと思ったのですけれども、スポーツジムが何件かというのがわかったら教えていただきたいと思います。こういう研修がされているかどうかを品川区として把握されているのかについても教えてください。","respondent":"鈴木生活衛生課長","answer":"この３条件を満たした場合に週１回が認められる中の維持管理が良好で公衆衛生上支障がないと認められるのは誰がですが、これは先ほど申し上げましたように、区の保健所のほうで年１回の菌の検査、それからそれ以外の巡回指導等に入っておりますので。","voiceIndex":23,"id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"レジオネラなのですけれども、品川区でも５０前後の検査を行って毎年数％出ているということなのですが、検出されないように指導をしているということなので、指導をされたら翌年はもう出ないということになってくるのかなと思うのですけれども、にもかかわらず毎年数件ずつ出続けているというのはどういうふうに考えたらいいのかということと、あとは私。","respondent":"鈴木生活衛生課長","answer":"しかしながら、それを踏まえた上で、先ほどご指摘があったように１５年前、平成１５年に週１回でいいという国の技術的助言が出たですので、全国的に感染の発症が皆無とは申し上げませんが。","voiceIndex":25,"id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"それで、レジオネラ菌に対して検査は１年間に１回行うということなのですけれども、それがもしこれを週１回以上ということにかえるのであれば、その頻度も上げることが必要だと書かれているのですけれども、そうなると区としては認められるということになった場合、この検査の頻度というのはどういうふうに上げていく考えなのかについてもお聞かせください。","respondent":"鈴木生活衛生課長","answer":"先ほど申しましたように、区のほうの検査、年１回の検査とは別に、事業者のほうが自主的に行う検査が１回、この自主的な検査の回数が国のほうの技術的助言で規定をされているものですので、もし区のほうに申請をして週１回の換水にするということであれば。","voiceIndex":27,"id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうしましたら、その検査の結果というのも区としては、東京都のほうの条例審査を見ましたら、何か毎月そういうふうに東京都に報告させているというようなところもあったのですけれども、品川区としては１回で、業者がやった検査についても区としてしっかりと把握していくと、そういう体制をとるということでよろしいでしょうか。","respondent":"鈴木生活衛生課長","answer":"水質検査につきましては、自主的に行ったものについても区の保健所のほうに報告をいただいておりますので、区の検査と自主検査両方を把握しております。","voiceIndex":29,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"確認","question":"確認だけよろしいですか。先ほど来シルバーセンターって出てきますけれども、シルバーセンターはゆうゆうプラザを含めて１０カ所ということになるかと思うのですけれども、それは対象にしていないと、毎日換水するということでよろしいのでしょうか。","respondent":"鈴木生活衛生課長、宮尾高齢者地域支援課長","answer":"シルバーセンターはゆうゆうプラザも含め、ちょっと新しい浴室は私は直接見ていないのですが、循環式でなければ対象にはならないので、毎日１回になると思います。シルバーセンターおよびゆうゆうプラザの浴室に関しては、毎回全部お湯を入れかえて清掃しています。","voiceIndex":31,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それが今質問していた内容かと思ったので。それから、事務事業概要を見ると、シルバーセンター等１０件でサウナ等が２４件になっているから、ジムはサウナ等に入っているのではないのと書類見ながら思ったので、一応確認だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-013"},{"speaker":"こんの委員","kind":"確認","question":"今、鈴木真澄委員の質問に関連するというところなのですけれども、私もまず参考までに。この国の要領では「毎日完全に換水して浴槽を清掃すること。ただし、これにより難い場合は」と。この「より難い場合」ってどういう場合なのかというところを参考までに。そうなると、次確認ですけれども、この６０件中５件以外は全て毎日換水するということでいいかと。ここをお聞きしたいと思います。","respondent":"鈴木生活衛生課長","answer":"対象施設以外は毎日換水かというご質問ですが、先ほど申し上げた要件を満たせる５件についても、事業者のほうで週１回に切りかえたいという判断があって届け出を出した場合のみですので、当然対象になっていないそのほかの施設については週１回の換水は認められませんので。","voiceIndex":35,"id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"意見","question":"改正内容のところで（１）、（２）、（３）とあると思うのですけれども、やはりこの（１）の浴槽水の換水頻度の見直しのところで、レジオネラ菌が減少してきたとはいえ検出施設がゼロではないということ、それとやはり換水頻度を現行の毎日から週１回以上であればいいという規制緩和になってくると思いますので、ここはやはり慎重にすべきと考えますので、この条例には反対をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-015"}]},{"id":"topic-02","title":"第８１号議案、指定管理者の指定","agenda":"第８１号議案、指定管理者の指定","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"それでもうちょっと体制のところを伺いたいなと思うのですけれども、高齢者の介護予防のところ、地域ミニデイですね、ここは何人ぐらいの受け入れで何人体制でやられて、この間ゆうゆうプラザ、地域ミニデイをやっているところもあると思うのですけれども、利用料なんかはそこと同じようになってくるのかどうかというのと、あと、子育て世帯のポップンルーム。","respondent":"宮尾高齢者地域支援課長","answer":"地域ミニデイに関しましては、既に先行事例もありますので、そういったものも十分に加味しながら進めていきたいと考えています。オアシスルーム、ポップンルームにつきましては、保育部門は管理者を含めて全部で７人と今事業者の方と話を進めさせていただいているところです。","voiceIndex":48,"id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"提案","question":"今打ち合わせ中ということなのですけれども、やはりどういったサービスでどういう人員配置にされるのかというのが、大枠わかってないというか、そういう提案が今からされるということなのですか。人員のところ、先ほど管理者を含めて７人とおっしゃっていて、前回の答弁のところでは非常勤を含めると９人だとおっしゃっていたのですけれども、非常勤を入れると９人になるということでいいのですか。","respondent":"宮尾高齢者地域支援課長","answer":"施設のオープンに向けて、今細部をまさに詰めさせていただいているです。そして、人員体制の７人、９人というところですが、９人というのは施設全部の管理スタッフも含めて９人。うち、オアシス・ポップンルームの従事職員が常勤換算で７人と考えています。","voiceIndex":50,"id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今のところなのですけれども、地域ミニデイってボランティアを活用して今のゆうゆう、社協でやっているのは社協の職員が１人来て、あとは地域のボランティアの方を募集して、それで１週間に一遍やると、そういうものだと思うのですけれども、そういうおおよその枠というのはあるのではないかと思うのですけれども、そこら辺のところを教えていただきたい。それで、管理者、職員に対しても改めて。","respondent":"宮尾高齢者地域支援課長","answer":"保育部門の人員に関しましては、まず常勤でいきますと管理者も含めまして常勤の職員は５名今のところ配置する予定です。常勤換算で２名。ですから、この２名という常勤の枠を実際には非常勤の職員で充当するというような形で考えてあります。","voiceIndex":52,"id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"総合事業でミニデイをやるわけですから、多分これは今までのゆうゆうを参考にしながら同じような形で利用料とか、それからボランティアの体制とかそういうふうなのを同じような形でやるというふうに考えていいのでしょうかということと、あと、先ほど健康増進の事業というのもあったのですけれども、そういうのはどう考えられているのかということと。","respondent":"宮尾高齢者地域支援課長","answer":"地域ミニデイにつきましては、委員おっしゃるようにまずほかの場所で今やっているもの、こちらのうまくいっている点、それと課題等々ありますので、そういったほかの場所での事業をしっかりと参考にさせていただいて進めてまいりたいと考えています。","voiceIndex":54,"id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"おおよそわかってきました。それはもう事業計画書ということで福栄会から既に品川区に対しての提案書としておおよそこういう事業でこれぐらいの予算でやるということはできているわけだと思いますので、細かいところまでは結構ですので、これだけの人員体制であればこれだけの運営費が委託費としてかかりますというあたりを改めてお聞かせいただきたいと思います。","respondent":"宮尾高齢者地域支援課長","answer":"来年度の運営経費につきまして、こちらはまさに今平成３１年度予算は編成段階になっているところです。その金額を今こちらで申し上げてまだこれから査定とかいろいろな段階を踏んで決まっていくものです。","voiceIndex":56,"id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それと、改めて条例審査に当たって出される資料が本当に少ないです。それでその結果がトータルで８割、８０点という前回のご報告だったと思うのですけれども、１番、２番、３番でそれぞれの点数みたいなのがわかっているのであれば、それも教えていただけたらと思います。","respondent":"宮尾高齢者地域支援課長","answer":"トータルで８割程度の点数だったと前回お答えをさせていただいたとおりですが、それぞれいろいろな要素もこの中には含まれておりまして、そのトータル全てでそれに十分近い数字を今回出していただいたです。","voiceIndex":58,"id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひそういうふうなところも、私たちもそういうことだったのかというところがわかるような形での資料というのはぜひ検討していただきたいと思います。先ほどの４億２,０００万円が２億５,０００万円になったというものの理由とかがわかれば、最後教えていただけたらと思います。","respondent":"宮尾高齢者地域支援課長","answer":"工事の金額につきましては、最終的に工事が１月末の竣工に向けて金額がしっかり固まってきたというところで、２億５,０００万円という数字が見えてきたです。","voiceIndex":60,"id":"exchange-022"}]},{"id":"topic-03","title":"第７４号議案、平成３０年度品川区一般会計補正予算（厚生委員会所管分）","agenda":"第７４号議案、平成３０年度品川区一般会計補正予算（厚生委員会所管分）","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"おくれた理由としてこの３点が挙がっているので、あんまりではないかというところなのですけれども、ほかにも質問しますけれども、通知を利用者の方に早くやっていただきたいなということがまず一点です。それは要望です。補正ということで確認なのですが、債務負担が加わることによって総工事費は幾らになるのかが見えないので、総工事費はお幾らぐらいになりますか。","respondent":"飛田障害者施策推進担当課長","answer":"総工事費としまして、５４億４,４８０万円となります。","voiceIndex":73,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"一遍に聞けばよかったですけれども、工事監理費も教えてください。","respondent":"飛田障害者施策推進担当課長","answer":"それにプラスしまして、工事監理費となりますと５,４７９万６,０００円という額になります。","voiceIndex":75,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"去年の決算が１０億９,０００万円で今年の予算が４３億円なのですね。これで５０億円になるのだけれども、実際幾らここで工事費が増えるか見えてこないのだけれども、そこの数字はどうとったらいいのか教えてください。","respondent":"飛田障害者施策推進担当課長","answer":"そのほかのところでは、工事費に関しましては工事延伸に伴う重機のリース代と人の確保等で、増額分、最大１億１,２３０万円ということで工事費は入れておりまして、工事監理費としてはこちらのほうも工事延伸に伴う人件費として１,３００万円プラスとなっております。","voiceIndex":77,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この今回の債務負担の２９億５,０００万円はこの１億１,２３０万円が乗っかっているのですか。それがトータルなのか。","respondent":"飛田障害者施策推進担当課長","answer":"詳細となりますと、当初の予定でした工事の出来高払いというのが工事費として２８億３,７７０万円。プラス、今回工事延伸になります先ほどの人の確保、重機等の増額分ということで１億１,２３０万円、それを合わせて２９億５,０００万円というふうになります。","voiceIndex":81,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、今年度は２８億３,７７０万円の出来高予定だということですか。予算４３億円のうち２８億円が今年度の出来高で支払いするということでいいのですか。","respondent":"飛田障害者施策推進担当課長","answer":"平成３０年度の出来高のところが１４億３７０万円というところです。今回のところがプラス１億１,２３０万円ということで２９億５,０００万円となります。","voiceIndex":83,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"確認","question":"内容はわかりました。６カ月延期したことによっての出来高といったら残っている金額は大してないはずなのに、これもだから財政の問題になってしまうのだけれども、支払いは業者としては相当負担が大きいのではないかと。債務負担を設定することは了解をするのですけれども、その辺できるだけ聞かせてもらうことはできないでしょうか。どこまで答えられるか。監理ということで確認だけお願いします。","respondent":"飛田障害者施策推進担当課長","answer":"工期のところです。今回騒音のこととか地中障害物の撤去、また近隣の車両の搬入口ということで、今まで２カ所予定していたところを１カ所というところです。","voiceIndex":100,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後に。お近くの方から工事がおくれていることでちょっとお話がいろいろ出ています。最初に建てるときに本当にみな何も反対がなくスタートしていった状況の中で、工事がおくれることによって騒音の問題だとか、早くでき上ってほしいねということを言っていることもあるので、これからの説明の中でも地域の方にうまくその辺の了解が得られるような形の説明をしていただきたいと、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"騒音に伴う近隣配慮によるというところは、これも最初からわかっていたことなのでしょうか。それと、地中の障害物の発生があった、それの処分作業もというところでは、これはいつ発見したものなのかというところも伺いたいと思うのです。ですので、この時点でも工期がおくれるということは想定できなかったのか、それでも頑張って進めようと思っていたのか、ちょっとそこら辺を伺いたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"そのときはまだ何とか工期に間に合うようにということで頑張って４月オープン、２月竣工ということでやっていたと私も聞いておりましたけれども、ここのところは先ほども言いましたが。","voiceIndex":103,"id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"それでやはり工期がおくれることで、裏面の利用者への対応のところで開設をおくらせる事業として生活介護、就労Ｂ、日中一時、地域活動支援センター、訪問系サービス、医療系サービスとあるのですけれども、結構前に委員会で配っていただいた資料で、生活介護は４０人、就労Ｂが２０人、日中一時は２０人ということで想定してつくるという図が出されたと思うのですが、それが全部おくれていくということで。","respondent":"飛田障害者施策推進担当課長","answer":"そういういろいろな可能性があると思いますので、保護者に対して、また利用者に対して丁寧に対応できればと考えております。","voiceIndex":105,"id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは特別支援学校にも事業所にも障害者団体へもこの告知をするということですので、誰でも説明会には参加できるということでいいでしょうか。それと、あと町会長へ報告というのがあるのですけれども、これは近隣町会長ということなのでしょうか。お願いします。","respondent":"飛田障害者施策推進担当課長","answer":"今回、この１１月１５日の説明会なのですが、広報、ホームページ等、各団体、学校等、特に利用する方のみということではなく、この施設に興味のある方に来ていただいて周知を図ろうとしているところです。町会長、こちらに書いてあるのは近隣です。","voiceIndex":107,"id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"生活介護と就労Ｂとあわせてということなのか、教えていただきたいのと、本当に総合支援施設なので、生活介護と就労Ｂだけではなくて、さまざまな障害者の方からも本当に期待されて待たれている施設だと思うのですけれども、そこら辺の具体的なところでは一番替えがなくなってしまうというのが生活介護と就労Ｂなのかと思うのですが。","respondent":"飛田障害者施策推進担当課長","answer":"先ほど新施設の希望者ということで第１希望、第２希望合わせると１１名程度ということですが、これは生活介護、就労支援Ｂ型を合わせての数となります。","voiceIndex":109,"id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"１１名という、卒業される方の中でということだと思うのですけれども、それ以外の方でもここができるということを楽しみにして、できたら通いたいというふうに思われている方もたくさんいらっしゃるのだろうなと思いますし、また、区内の施設が定員を大きく超えて受け入れざるを得ないという状況の中で、さらにというふうなことはなかなか現実問題本当に難しい状況になるのかなと思うのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-034"},{"speaker":"若林委員","kind":"質問・要望","question":"６カ月竣工がおくれ、開設も１０月になるということで、大変残念な報告になってしまったかなと思っています。その中で、先ほどのご報告では１.５カ月おくれるというのが今年の７月ぐらいでした。理由も理由ですので、サービスがおくれるということもありますので、そこについての周知のやり方、説明のより丁寧なあり方について、さらにお考えがあればお聞かせいただきたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"個人的にやはり特に丁寧に対応していかないといけないと思いますので、もちろんこのときの説明会だけではなく、特に今３年生の方なんか、新設を見据えて実習等もしていましたけれども。","voiceIndex":112,"id":"exchange-035"},{"speaker":"若林委員","kind":"質問・要望","question":"２つ確認というか、要望というか。ここら辺ちょっとお聞かせいただきたい。説明の仕方については、より丁寧な直接の利用者への説明というところも含めて、明確なご答弁がここでもらえるとは思いませんけれども、しっかりこれは１１月１５日の区役所講堂で昼と夜１回ずつやりますよということ以上に、やはり現場の利用者の皆さんの声も聞きながら、より丁寧にやっていただきたいという要望をします。","respondent":"飛田障害者施策推進担当課長","answer":"３つの理由で今回、工期の延期となりました。このところについて、また施設整備課とも関連するところでありますので、詳細なことを聞きながら情報提供していきたいと考えております。","voiceIndex":114,"id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今、学校という話が出たけれども、最初の説明会でも学校が音を物すごく気にしていました。僕が説明会に出たときにそれは言っていたので、今言ったように学校側は最初からそれを指摘していた部分だと思うので、よくその辺注意しておいてもらいたいと思う。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-037"},{"speaker":"木村委員","kind":"質問・要望","question":"一応３つの延長理由に対して、住民にこれからもいろいろな事情があろうと思いますけれども、近隣の方々に対しての配慮、また学校に対してもいろいろとあろうかと思いますけれども、しっかりしてやっていただきたいと考えています。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-038"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"その内訳は、養護者による虐待が１３件、施設の職員による虐待が３件、使用者による虐待が１件と答弁されました。今回施設のところが問題というか訴えられているわけですけれども、施設の職員による虐待が３件というのは、いつのことなのでしょうか。今回の分もきっと入っていると思うのですけれども、３件を教えていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"３件のうち１件はこちらに報告しているものです。その他２件については、本日資料を持ち合わせておりませんが、東京都が必ず公表をしているものです。","voiceIndex":129,"id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、改善報告書の提出をしなさいとされているわけですけれども、これはどういう間隔で、先ほどこれで終わりではなく継続してとありましたけれども、ここを改善させました、１から１２まで改善させましょうというふうに出されているのですけれども、そのことに関しての報告が常に来ている状況になっているのか、伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"区だけではなく東京都と一緒に報告は受けております。平成２９年５月で報告を受けるのはそれで完了ということになっておりますので、現在は通常のほかの法人と同様に指導・検査を機会を捉えて行っております。","voiceIndex":131,"id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、虐待認定をされたこの件に関しては、障害者虐待防止等対応の手引きというのが厚労省から出ているのですけれども、そこによると、終結の宣言みたいなものがあるのです。この事案について改善が認められたとなると、モニタリング、そして虐待対応の終結というのを出すことになっているということなので、これに基づいて虐待対応の終結がされたということなのでしょうか。伺いたいと思います。","respondent":"松山障害者福祉課長","answer":"先ほどの答弁の繰り返しになってしまいますが、平成２９年５月に最終報告を受けまして、この事案についてはそちらで一旦区切って終結ということになっています。","voiceIndex":133,"id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほど人員配置の区分は会館は３.６だからそれを６で割ると４人になると。その４人は満たしているのだということだったのですけれども、会館の実態は身体介護のほうが大変でそっちに手をとられて知的のほうが薄くなるとここで訴えられて陳情にも書かれていますけれども、やはりそういう状況が現場でもあるということは、区としては把握されているのでしょうか。","respondent":"松山障害者福祉課長","answer":"知的の先ほどのひまわりグループにつきましても、８名のところ、平均障害支援区分が５.１、配置基準上必要な職員数は２.６のところを４名の方を配置して対応しております。そういった状況は把握しております。","voiceIndex":135,"id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"そこをさらに研修等で深めていくために、サービス向上委員会だったり、あとは虐待防止の委員会もつくられているということですけれども、やはりそこで委員会がつくられて中身で何をするのかだと思いますので、そこら辺、一人の人間として見ていくその評価をしていかなくてはいけないのではないかと思うような改善計画書だったので、先ほど職員研修をされているということでしたけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問","question":"今そういった中身のことを聞いたのは、人員のところでは努力されていると。では、質の部分というところなのかというところで、どういう中身で改善計画がされているのかということをお聞きしました。それで、努力をされているというところですけれども、一応改めて人員をさらに配置していく、利用者が安心して通える施設にするためにも、人員体制をというところには区としてはどうお考えでしょうか。","respondent":"松山障害者福祉課長","answer":"ただし、各グループごと、グループ単独で動くということではなく、あるいはここに併設の地域活動支援センターにおけるボランティアの方々、あるいは地域の方々も含めて、どうやったらそれぞれの個別支援計画でご利用者が希望されたこと。","voiceIndex":140,"id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回の品福の、平成２８年１月２０日に厚労省から東京都を通して品川区に情報があったこの事案に対しては、虐待認定という形で認定されたわけですけれども、この虐待認定というのはどこがどういう仕組みで行うのかということも教えていただきたいと思います。","respondent":"松山障害者福祉課長","answer":"３件のうちの１件、残り２件についてなのですが、先ほど申しましたように、今手元にはない状況ですので、今お答えしかねます。この３件と申しますのは、品川区内ということではなく、品川区民の方が例えばほかの地方に入った場合でもカウントしているものです。","voiceIndex":142,"id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それで、今回の品福の問題についてこういうふうな形で起こっていると、認定されたというのはずっと後になって知ったのですけれども、虐待というのは本当にあってはならないことで、もしもあったらやはりそれを教訓にしながら二度と起こさない対策というのが求められる、本当に人権の問題ですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そこら辺の質の問題というのも、職員の研修というのもあるのかもしれないのですけれども、やはり一人ひとりの障害者の方々に合った形での中身の提供というところの人員体制はどうなのかという思いがしているのです。そこら辺のところはいかがでしょうか。実際問題のところとあわせて。","respondent":"松山障害者福祉課長","answer":"人を配置するというよりはその本人の特性をきちんと理解して、知識を持って、あるいはどういう支援をすればご本人がより落ち着き、会館で楽しく日中活動が過ごせるかどうかというところが非常に大事だと考えていますので、私といたしましては。","voiceIndex":147,"id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは品川区に限ることではなくて、あらゆる事業者であり法人にも活かされなければならないことだと思うのです。障害者の人権を尊重するというところでの職員自身の研修も含めた意識にぜひとも持っていっていただきたいと思っているのですが、その点で最後にちょっとお伺いできたらと思います。","respondent":"松山障害者福祉課長","answer":"障害者の方に対してサービスを提供するサービス事業者やほかの法人も含めて、全ての障害者にかかわる方に対して、本当に人権意識の向上を図って、二度とこういうことが起こらないようにということで、区の指導もきちんと行ってまいりたいと考えています。","voiceIndex":149,"id":"exchange-048"},{"speaker":"若林委員","kind":"確認","question":"この陳情の理由の中に、何回もお話が出ていますけれども、さくらとひまわりの２クラスがあって、さくらグループでは２４人の利用者に３人の職員しかいないと。この陳情者の方は現場のお声も含めてこういうことで、これは会館のほうですか、こういう体制だと決定されているわけですけれども、先ほどの説明では、看護師等も含めて常勤換算で０.５と０.５を足して４になるのですと。","respondent":"松山障害者福祉課長","answer":"こちら、さくらグループですと生活支援員の方の３名の名前、この方が担当者ですというような、家族会では恐らくご説明を差し上げているですので、そういった意味ではリーダーや看護師をどう捉えるかといったところでは説明が不足していたかと思われます。","voiceIndex":151,"id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"そうですよね。そもそものお互いの認識がずれていると、いわゆるボタンのかけ違いから誤解しなくてもいいことを誤解したりということは普通にあることなので、そこは重々これからご対応いただいて、その上で足りないよねとかいう話は当然よくわかりますので、まずそこのボタンのかけ違いは今後なくしていただきたいということと、あともう一つ確認。","respondent":"松山障害者福祉課長","answer":"あるいは職場です、そういう職員同士何かあった場合にはお互いに気づきを高めようという職員のモラルというのが低下していたというところが要因として挙げられるかと考えています。","voiceIndex":153,"id":"exchange-050"},{"speaker":"若林委員","kind":"質問","question":"いずれにしても、平成２４年１０月から障害者虐待防止法が施行されて、その中でも虐待を見たら報告する義務が明確にうたわれているということで、今の報告書の中でも平成２４年１０月に施行されて、これが平成２７年に発生した事案なので、当然虐待防止法が施行されている中で、残念ながらこの防止法で懸念されている大きな点が改善報告書でも出ているということで、法律をつくったから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-051"},{"speaker":"鈴木（真）委員","kind":"意見","question":"結論を出すということで、お願いいたします。その意味で、自民党・子ども未来については、今回不採択ということでお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":157,"id":"exchange-052"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり先ほど課長もおっしゃっていたように、一人ひとりの障害を持たれた方の希望に沿って、そして重度によって難しかったりしてくる人員配置というのが、基準ではなく特性を把握してよりよい支援につなげるためにもまだまだ工夫の余地があるというお話でしたので、人員配置をさらに充実させていただきたいと思いますし、さらにここで職場環境を整えということも言われていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-053"},{"speaker":"木村委員","kind":"意見","question":"結論を出すということでお願いします。不採択でお願いします。今回このようなことで人的要因ではないと、数が少ないからどうのこうのではなくて、本当に違うところに原因があるのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":162,"id":"exchange-054"}]},{"id":"topic-04","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"鈴木（真）委員","kind":"確認","question":"質疑というか、これは仕方がないかなと思うのですが、この方、けがは大丈夫ですか。そちらを心配。事故を起こすと本人も大変なことだし、その辺だけちょっと確認をしておきたい。","respondent":"矢木生活福祉課長","answer":"幸いにもけがはございませんで、一旦停止はしたのですけれども、前に出たところでぼーんというふうに、前輪に当たって前輪が破損したという、その程度で済んです。","voiceIndex":170,"id":"exchange-055"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"この各地区の懇談会に出されたこういう声というのは、住民の皆さんに公開はされているのでしたか。どういう形で。結構みんなも思っていることなのだろうと思うのですけれども、それをやはり見ないというか、会議体はあったにしても共有していくというか、そういう場、そういうものがあるのでしたか。","respondent":"大串福祉計画課長","answer":"ただ、地域福祉計画の策定委員会をこれまで３回実施をしておりまして、そのときには皆様方に情報提供というか、こういった意見もありましたよということでご紹介をさせていただき、なおかつ説明もさせていただいているところです。","voiceIndex":176,"id":"exchange-056"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"包括的な支援体制の構築を国から求められているということなのですが、これは基本的に品川ではどこが担う考えなのか。それと、各地区支え愛活動会議の委員というのが、どういうメンバーか教えてください。","respondent":"大串福祉計画課長","answer":"２つご質問をいただきました。２個目の質問からお答えします。各地区支え愛活動、各地区の構成メンバーは異なっております。","voiceIndex":178,"id":"exchange-057"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今年に入って地域包括支援センターの機能強化についてですとか一部改正についてというのが厚労省から幾つか文章が出されているのですけれども、その中で改めて改正後の地域包括支援センターの目的というところで、「地域住民の心身の健康の保持及び生活の安定のために必要な援助を行うことにより、地域住民の保健医療の向上及び福祉の増進を包括的に支援することを目的として。","respondent":"大串福祉計画課長","answer":"ただ、求められているありようといいますかそういったものがやはり我が事、丸ごとといったところで進めていくという大きな流れの中では、地域包括支援センターが中核的な役割といったところで求められていると考えておるところです。","voiceIndex":180,"id":"exchange-058"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"３区ぐらいやられているのですけれども、その中で世田谷区で話を伺ってきたところでは、本当に地域包括支援センターに保健師、社会福祉士、主任ケアマネと３職種が配置されて、そこで障害者の相談も受けるというふうなことにしたというお話を伺って、それは障害者のところですごく相談する場所が増えた、また保健師や社会福祉士も一緒に相談に乗るということで。","respondent":"大串福祉計画課長","answer":"そこからさらに専門的な領域といったところ、各専門機関へつなげていく。このつなぎがスムーズに進めていければ品川区なりの包括支援体制といったものが構築できると考えているところです。支え愛・ほっとステーションにつきましては、昨年全地区展開できたといったところです。","voiceIndex":182,"id":"exchange-059"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点では、やはり専門職をしっかりと配置していただければもっと充実をするのではないかと私はずっと思っていますので、改めてその辺のところは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-060"},{"speaker":"こんの委員","kind":"確認","question":"ちょっと現状というか確認です。平成２８年度から平成２９年度の間で、いわゆる各地区の会議体ごとに独自の取り組みを実施してきましたというところ。今、支え愛・ほっとステーションの話もありましたけれども、そうした支え愛・ほっとステーションの実績など、各地区で具体的にどのような独自の取り組みをしてきたのか、まず教えてください。","respondent":"大串福祉計画課長","answer":"従来から民生委員等々を中心に交流会をやっていただいていたところもあります。そういった形で、本当に各地区それぞれいろいろな取り組み方があるところですけれども、そうした中で少しずつでも進めていく。","voiceIndex":185,"id":"exchange-061"},{"speaker":"こんの委員","kind":"質問","question":"これは機運醸成ではないですけれども、皆さんがこうだよね、ああだよねという地元の課題をご自分たちで意識して出して進めていくというのがある意味ポイントかと思うので、そこら辺のところは引き出してあげながら進めていくのは、やはり区の支えと区の呼びかけというのが必要かと思いますが、その点はどういうふうにされているのかというのと、あわせて支え愛・ほっとステーションの実績などは。","respondent":"大串福祉計画課長","answer":"まさにいみじくも言っていただいたように、本当に各地区で千差万別です。各地区が持っていらっしゃる課題もそれぞれ異なっているといったところ。だから、一律１３地区全体に何かというところはやはり難しいのかなと考えているところです。","voiceIndex":187,"id":"exchange-062"},{"speaker":"こんの委員","kind":"意見","question":"今課長がおっしゃっていただいた、区からの押しつけではない地域の皆さんのそれぞれの課題を自分たちでどうするかというところで、自分たちもこれから先このままではだめだよねと何となくイメージはしているのですが、それを具現化というか、では誰が先導してどういうふうに具体的にしていくのか、できそうでできないというか、決められそうで決められないというか。","respondent":"大串福祉計画課長","answer":"地域福祉計画を策定しますので、そういったものも皆様方にご説明しながら、そういった流れ、方向性といいますか、そういったものを皆さんと探っていきたいと考えております。","voiceIndex":189,"id":"exchange-063"},{"speaker":"こんの委員","kind":"質問","question":"だから、その全区公平性とかいう観点で、一カ所だけではなくて全部にそういう声が出ないとできないよではなく、それが一つの包括ケアのきっかけになるのだと捉えていくという考え方の事業展開をしていくものが、もし予算が必要であれば、そういったところもつけていくような進め方が必要ではないかと思うのですが、その点はいかがですか。","respondent":"大串福祉計画課長","answer":"その辺、先行事例も幾つかあると認識しておりますので、その辺も見させていただきながら、どういった形で本当に品川区という都心の区、あるいは各１３地区それぞれ個性がある地区展開をしております。","voiceIndex":191,"id":"exchange-064"},{"speaker":"若林委員","kind":"質問","question":"結局一つの感想は、今までの既存のサービスを誰かがやると、いわゆる縦割りの中で行われているのが今のサービスの現状、今度は、新たな目玉事業というのも、それは小山台の跡地に共生型の富山型デイサービスをつくったらいいとか、いわゆる共生型のモデル事業をとかということは議会の中で言わせていただいておりますけれども、それはそれとして、いわゆるソフトの面で。","respondent":"大串福祉計画課長","answer":"そういったものをうまく連携させるような形、連携させていくにはどうしたらいいかといったところはこれからも考え続けていきたいと考えております。","voiceIndex":193,"id":"exchange-065"},{"speaker":"若林委員","kind":"提案","question":"地域の方と、さっきの、昔は協働型、提案型というテーマを決めないでと、でも何年かやったけれども出てこなくなって結局区のほうからのテーマを出してそこに手を挙げてくださいということで、それで上がってくるのですけれども、やはりご提案に対して区としては策定委員会を設けてこれはできます、これはできません、ここはこうしてくれればできますという。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":195,"id":"exchange-066"},{"speaker":"こんの委員","kind":"意見","question":"今委員長がおっしゃったところの視点は非常に大事だと思うところで、また全国都市問題会議の話で大変恐縮なのですが、ちょっと言葉をどういうふうに入れていいかあれなのですが、要するに、今委員長がおっしゃったようなことに踏み込んで皆さんへのご紹介というのはあるのに、区の方が汗をかいていただかないと、機運醸成は自然発生的なものではないので、このようなやり方もあんなやり方もと踏み込んだ。","respondent":"大串福祉計画課長","answer":"そうでなければ共生というともに地域をよくしていこうという気持ちというのは育まれていかないと思っていますので、そこについては我々のほうでもぜひ地域の皆さんの中に入らせていただいて、この地域にとって何が一番大事なのか。","voiceIndex":197,"id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3520#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":66393,"voices":204}},{"id":"h30-20181029-8","meetingId":"h30-cm10","date":"2018年10月29日","dateIso":"2018-10-29","committee":"建設委員会","time":"午前１０時００分～午後 ３時３２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を86件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第７９号議案 品川区手数料条例の一部を改正する条例","agenda":"の第７９号議案 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"別紙２のほうですけれども、改正の１点目の内容についてまずお伺いします。現行で審査会の同意を必要としていた理由は、防火上ですとか安全上ですとか衛生上という話はわかりましたけれども、そういった観点から、これまでは必要だったからだと思うのですけれども、今回のいわゆる規制の緩和になるのですが、実質上、防災、安全の上で問題が生じてくるということはあるのかどうか、伺いたいと思います。","respondent":"長尾建築課長","answer":"接道規制の適用除外に係る認定の中の省令事項にかかわる部分ですけれども、こちらの省令事項に書いてあるような基準を満たすような敷地は、これまでの許可実績等も確認してみたのですが、品川区内では想定されるような案件がなさそうであるという見込みです。","voiceIndex":15,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"続きまして、２点目の改正内容なのですが、仮設興行場等とは何を差すのか、まずお伺いします。そのことによって安全上、問題が出てこないのか伺いたいと思います。","respondent":"長尾建築課長","answer":"仮設の興行場が何を差すかということですけれども、１つの例としましては、例えばサーカスのテントなどが考えられると思います。","voiceIndex":17,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"仮設興行場というのは、例えばサーカスのテントということでしたけれども、ちょっとお伺いしたいのが、例えば、今、これはまだ規定ができていないので、通常の手続にのっとってつくられるとは思うのですけれども、劇団四季の劇場ですとか、あるいは旧第一日野小学校跡地に今建てられています五反田メッセという。","respondent":"長尾建築課長","answer":"個別の建物に関しては、仮設許可を得ているか得ていないのかというところは捕捉をしかねるのですけれども、今までは１年以内の期間である場合は仮設の許可をとってというところになっておりますので、おそらく仮設ではなくて常設の建築物として建てていたものと考えられます。","voiceIndex":19,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"確認","question":"接道義務の緩和ですけれども、先ほどのやりとりの中で、区内にはあまり見当たらないのではないかという課長のご答弁だったのですけれども、省令事項の中の農道に該当するものがないということですが、通路等というのは道路に当たらないので、こういう土地で確認申請が特定行政庁の建築許可だけでできるようになるというのは、それはすごい画期的なことだなと思ったのですけれども。","respondent":"長尾建築課長","answer":"２つ目の仮設興行場等の１年を超える許可の部分については、やはり例示ではオリンピック・パラリンピック施設が出ていることもありまして、１年を超えて設置することも想定されるというところから、国の法改正もなされているということです。","voiceIndex":21,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"わかりました。最初に背景を伺えばよかったんですけれども、１番については、緩和というよりも、逆に裁量の幅が大分狭くなったという形で捉えればいいということですね。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"法第８５条第６項、第７項というのは、今のあくつ委員と課長のご答弁の中で例示も示されて、あらあらわかりました。お願いします。","respondent":"長尾建築課長","answer":"利用者が少数である建築物の基準として例示されております２００m2以内の戸建住宅という基準を満たしていれば、通常の建築基準法の基準では建てられない敷地であっても、建てることができるようになるというところになります。","voiceIndex":24,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"仮設興行場等はオリンピックということで具体的に事例を挙げていただいたので、これは意外とスムーズに理解をできたところですけれども、この第４３条第２項、これはどのような世の中の具体的な動きがあったのかということを伺いたいと思いまして、例えば密集なのか、空き家、これはちょっとわからない、たまたま例として密集なのか、空き家対策なのか、いろいろな農地を整備して何かやるだの。","respondent":"長尾建築課長","answer":"国の資料の中では、オリンピック・パラリンピック施設のような例示が特になかったのですけれども、例えば農道だけに接している宅地の中で住宅を建てたい場合であるとか、そういったことが想定されるのですけれども、こちらの改正の内容ですと。","voiceIndex":26,"id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"昨日、世田谷のほうに行ってきましたけれども、まだ農道が残っているところがありまして、品川はどう見ても農道はあり得ないわけでして、品川区として、国の動きの中で、例えば東京近郊なりの地域でもいいのですけれども、農地を宅地に変更する動きが世の中で増えてきた、あるいは、そういう事例が増えてきたということで。","respondent":"長尾建築課長","answer":"全国的に見れば、そういった側面もあると思います。","voiceIndex":28,"id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"手数料についてお伺いしたいのですけれども、特に仮設興行場等で、手数料１９万５,０００円となっておりまして、一見すると結構高額な料金かなと思っているのですけれども、その手数料は、どのような基準というか、趣旨で決まったのかをお知らせください。","respondent":"長尾建築課長","answer":"こちらは、別紙１の１ページ目のところに、これまで１年以内で許可をしていた際の手数料が載っております。３９番に書かれています。今まで仮設等の場合は、１件当たり１０万８,０００円の手数料がかかっておりました。","voiceIndex":31,"id":"exchange-009"},{"speaker":"横山委員","kind":"確認","question":"仮設興行場等のところですけれども、今、手数料のお話がありましたけれども、こちらの期間ですが、１年が存続期間の上限ということで、特別の必要がある場合に、建築審査会の同意を得て認めた場合には、例えば何年までですとか、期間の部分は何か定めがあるのでしょうか。","respondent":"長尾建築課長","answer":"どのぐらいの期間、仮設建築物として設置するかというところにつきましては、安全上、防火上、衛生上問題がないかどうかというところの確認と、あと、建築審査会の中で考え方として同意が得られるかどうか、そういったところを踏まえて、期間の設定をされるもので。","voiceIndex":33,"id":"exchange-010"}]},{"id":"topic-02","title":"の第７４号議案 平成３０年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"の第７４号議案 平成３０年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひこの制度を多くの方に使っていただいて、結果、安全な地域につなげていただきたいのですけれども、いかがでしょうかということが１つです。それと、制度の内容については、助成内容、除去費と工事費助成とあって、2)のほうも細かく言えばブロックとフェンスの部分に分かれていると思うのですが、そこら辺は併用ができるのかどうか確認させてください。３点目です。","respondent":"長尾建築課長、溝口公園課長","answer":"こちらの軽量フェンスの設置工事については、補助率が２分の１となっておりますので、そういった観点で言いますと。やはりそれぞれ制度を目的を持ってやっていくところです。引き続き、安全な市街地、またはうるおいのある品川区をつくる、そういったところの観点で、両課しっかり連携しながら進めていきたいというふうに考えておるところです。","voiceIndex":47,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、もちろん最優先すべきは防災上の安全の確保だと思いますけれども、それぞれ目的も違う事業だということは承知しているのですが、ちょっとわかりづらくならないような工夫も含めて、こういった制度の周知に当たっては、生け垣の助成もありますよということも一緒にあわせて、わかりやすいように周知していっていただいたほうが、区民の皆さんにとってもいいのではないかと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１つ、もし先ほど説明があったのなら大変申しわけないのですが、確認の意味で伺いたいのですけれども、この調査延長が約９３４kmということなのですが、これはいわゆる区内の区道、都道、国道、私道を含めて道路といわれる、建築基準法上の道路については全て調べるということでいいのかどうかというところが１つ。","respondent":"長尾建築課長","answer":"事業の助成制度の周知につきましては、広報しながわであるとか、区のホームページ、また、大阪府の地震が起こった際に、ツイッターやフェイスブックなどを活用して情報の提供をさせていただきましたが、そういった媒体は積極的に活用して。","voiceIndex":51,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問","question":"ですから、広報しながわにおいても、情報の重さ、軽さはあると思うのですけれども、これは命にかかわることですので、ちょっと取り上げ方に工夫をしていただいて、パッと目に飛び込むような掲載の仕方をお願いしたいのと、あと、ケーブルテレビ品川等において、かなりの方がご覧になっている媒体なので、所有者に届くような周知の方法の検討をお願いしたいところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-014"},{"speaker":"横山委員","kind":"質問","question":"幾つかお伺いいたします。現在はすぐに対応する必要がない部分があったとしても、やはり経年劣化していくようなものかと思いますので、そのあたりも先々を見込んだあたりもどのように対応していくのか、広報をどのように行っていくのかというところをお知らせいただけたらと思います。調査の基準というか、進め方について詳しく教えてください。","respondent":"長尾建築課長","answer":"今、危険性が高いと思われる塀については、近隣の方などから建築課のほうにお問い合わせいただいておりまして、そういった場合につきましては、職員が現地確認を行いまして、塀の所有者の方にお話をさせていただいてという個別対応をしておりますので。","voiceIndex":54,"id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"数もたくさんありますでしょうし、期間もかかります。今回、２０件ということで助成をされるようなのですけれども、おそらくこれよりも多い部分が対象として出てくるのかなというふうに予測しているのですけれども、先々、次年度以降のことも計画的に進めていただけたらと思いますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-016"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、本日いただいた資料に、工事の助成予算額１,０１１万２,０００円とありますけれども、この額の内訳は、補正予算の事項別明細書の工事費助成１,００８万円と、事務費の３万２,０００円を合わせた合計額ということでよろしいでしょうか。","respondent":"長尾建築課長","answer":"委員がおっしゃっているとおり、助成の費用と事務費を足した金額となっております。","voiceIndex":57,"id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"先ほど、軽量フェンスとブロック積み等の助成は併用が可能というようなお話がありましたけれども、この軽量フェンスの形は、この絵にかいてあるとおりのもの、大体こういったブロック積みの上に軽量フェンスを乗せるという形が基本形になるということでよろしいのでしょうかということと、また、基礎調査は先ほど目視とおっしゃられましたけれども、大体どのくらいの期間がかかるものなのでしょうか。","respondent":"長尾建築課長","answer":"調査期間につきましては、助成制度と同じように１２月に入りましたらすぐ調査を開始できるようなことを想定しております。区内全域ですので、おそらく年度末ぎりぎりまでかかるかと考えています。３カ月前後はかかると考えております。","voiceIndex":59,"id":"exchange-018"},{"speaker":"安藤委員","kind":"提案","question":"なぜ品川だけやらないのか。国からの設置の提案というのがあったのかどうか。あったのか、ないのか、それを伺いたいと思います。資料の２についてですけれども、落下防止基準とは何でしょうか。具体的に中身をお伺いしたいと思います。そして、基準の義務化というのはどういう意味なのか。強制力や罰則とかはあるのでしょうか。これで区の求めるような落下物ゼロというのは実現するものなのかどうか伺います。","respondent":"鈴木都市計画課長","answer":"ハード的なところとしましては、これまでの落下物の事例等を踏まえまして、項目としては１９０項目ほどあるですが、具体的には、吸水用パネル等の取りつけのヒンジの交換ですとか、あるいは、改良型フックの交換ですとか。","voiceIndex":73,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"情報発信拠点はつくられればいいというものではないですけれども、ぜひ早めに設置できるように努力していただきたいと思います。実施計画はつくるけれども、それが実際に守られるかどうかというのは、義務化されていないということだと思うので、これで区の求めるような落下物ゼロというのは実現するものなのか、改めて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"ただ、国のほうもこの中身について、しっかり航空会社に守っていただいて、ゼロを目指すと申しておりますので、区としては、こうした取り組みがしっかり実施されていくように、今後、引き続き、国のほうに求めていきたいです。","voiceIndex":75,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"こちら側が認識できていなかった面もあると思います。伺いたいのは、その連絡会というのは実はまだ１回も開かれていないのです。出席状況は２５区市とありますが、この４月３日の幹事会には、品川区の部長は参加したのでしょうか、しなかったのでしょうか。発言をしたのでしょうか、しなかったのでしょうか。それと、来るべき連絡会、品川区としては何を発言をするのか、ぜひ伺わせていただきたいと思います。","respondent":"鈴木都市計画課長","answer":"直近の東京都開催の幹事会ですが、部長は出席しています。その場で、これまでも一貫して求めていることですが、区民への丁寧な説明、周知、それとともに落下物防止対策、騒音影響の軽減に向けた取り組みというところを強くその場で、国の方も出席していますので、求めたです。","voiceIndex":77,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"来るべき連絡会で品川区として何を発言するのかというのは、まだ日程が決まっていないので未定ということですけれども、それはそうだと思いますが、１年間の間に必ず行われるわけです。それは都議会でも東京都みずからが答弁しております。今の時点で行われることは明らかなのですから、どういったことを発言するのか、区長選挙でも新ルート計画の問題が争点となって大議論となりました。","respondent":"鈴木都市計画課長","answer":"これは国が今、第５フェーズ説明会に向けて準備をしているということも伺っておりますし、そういった動向も踏まえながら、そういった会が開催されれば、区民への丁寧な周知も含めて、先ほど申しましたとおり、安全対策、落下物。","voiceIndex":79,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは私は重要だと思っていまして、そこで、自民党にもお伺いしたいのですけれども、国の対応策が今後示されないのであればというのは、およそいつぐらいまでがタイムリミットだと考えておられるのか、さっきも言ったように、あと１年少し後には飛んでしまうわけですから、タイムリミットはおのずとあると思うのです。そこら辺をどう考えていらっしゃるのか、ぜひ伺いたいと求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-023"},{"speaker":"大沢委員","kind":"質問・要望","question":"私の質問ではないので、そこの行間を読むところは非常にはかり知れぬところがあるのですけれども、質問者のニュアンスをもう１回私のほうから確認をし、よく理解をしなければ、この質問には答えられませんので、この場でのお答えは差し控えさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそこは確認していただいた上でお答えいただきたいのですが、自民党を代表しての一般質問ということもありますので、ぜひそこら辺は自民党・子ども未来としてのお答えを伺いたかったところなのですが、それは残念ですが、ぜひお答えを後日聞かせていただきたいという思いがあります。区議会公明党は、国交省に対して、品川区上空を飛行しないルートの再考を強く求めていきたい」と表明されました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私どもは、会派として濱野区長を、現職の区長を応援いたしましたが、この問題も非常に大事な論点の１つとして、濱野区長は公約にも掲げておりましたけれども、これは国の問題ですから、それについてワンイシューのみで戦うというのは、これは党利党略、戦略であって……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これははっきりと申し上げておきます。今日のこの資料、この前の陳情審査、区長選が終わってからの経過の中での変化ということでご提示をいただいたのですけれども、具体的な手法をさらに求めていくと区はおっしゃっているのですけれども、これをもって納得がいく説明と思われているのかどうか、そこについて品川区の具体的な見解を求めたいと思います。","respondent":"鈴木都市計画課長","answer":"先ほど、ご説明しました落下物の取り組みについては、基準が公表されて義務化がされましたが、やはり実施担保性をどうやってとっていくのかというところも、今後、区としても強く求めていかなければいけないという内容で考えてあります。","voiceIndex":88,"id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問・要望","question":"具体的に、今、区としての考え方を伺ったのですけれども、私どもとしては、先ほど申し述べた結論のほかに、区議会公明党は国交省に対して、品川区上空を飛行しないルートの再考を強く求めていくということに関しては、これは一般質問の中で表明をしていますので、これも私どもは強く皆さんにお伝えしていきたい、このように考えております。","respondent":"鈴木都市計画課長","answer":"区としては、今後も国のほうにこういったところは情報をしっかり確認しながら進めていきたいです。","voiceIndex":90,"id":"exchange-028"},{"speaker":"あくつ委員","kind":"確認","question":"前から申し上げているとおり、土地の価格が下落するかどうかはわかりません。上がるかもしれない。この前の選挙戦において、私はどうしても看過できなかったのは、こういう不安をあおるような未確認の情報を選挙に勝つがために、これを喧伝をされたということ。本当に区民のことを考えているのかというところで、私は非常に個人的に、ちょっとこれは見過ごせないなと思ったので、確認をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-029"},{"speaker":"大沢委員","kind":"質問","question":"今、あくつ委員の質問の中で、資産価値の下落についてのお話がありましたけれども、私の知り得るところでは、伊丹はそういうことは一切なかったというような話を伺っておりますけれども、そこのところ、担当の課長は把握をされていらっしゃると思いますけれども、ご答弁願います。","respondent":"鈴木都市計画課長","answer":"伊丹、また福岡空港周辺ですが、航空機騒音により不動産価格が下がるといった直接的な因果関係は把握されていないということで聞いております。","voiceIndex":93,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"騒音対策についてですけれども、先ほど、対策が拡充されつつあるというお話をいただいたのですけれども、やはり住民の方が一番心配されている点で、また、仮に通過されることになった場合、せめて一般の住宅の防音措置はやってほしいという声が非常に多いのですけれども、そうしたことを区としまして、一般住宅の防音措置というのは、これをしっかり求めていっていただきたいのですけれども。","respondent":"鈴木都市計画課長","answer":"〔同日後刻に「住宅は拡充の対象には含まれない」と答弁訂正あり〕 防音対策、騒音軽減の取り組みについては、区が再三再四強く申し上げてきた中で、時間を限定した取り組みが国のほうから示されたわけですが、何か対象がさらに拡大される仕組み、取り組みがないかというのは。","voiceIndex":95,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"万が一の墜落事故やら落下物事故で非常に大きい事故が起きた場合の航空会社の損害賠償が問題になると思うのですけれども、被害がかなり大きくなった場合、航空会社が損害賠償の支払能力があるのかといった問題も出てくると思うのですけれども、航空会社によっては支払いきれないとか、そういった問題の可能性もあるのですけれども、そのあたり、国としてどういうふうに捉えているのか。","respondent":"鈴木都市計画課長","answer":"その中身は、やはり落下物、これは、どの便のどの飛行機から落ちたかと特定するのが非常に難しいというところもあって、ただ、それを待っていると、やはり補償に時間がかかったりするということで、航空会社が保険に加入をして、共同してそういった事例に対応していこうと。","voiceIndex":97,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"先日の一般質問でも質問させていただきまして、その際、明確なご答弁をいただけなかったのですけれども、横田空域の問題で、まさに国が新飛行ルートの実施をするかどうかということが今とまっている、膠着状態が続いているのですけれども、そうした今の状態を好機と捉えて、区としても撤回していくことも求めていくべきかと、撤回してくださいというふうに申すべきだと考えておりますけれども、その点。","respondent":"鈴木都市計画課長","answer":"国のほうからも、状況報告といいますか、この件に関してのやりとりはさせていただいているところですが、国としましては、引き続き必要な調整を進めていく、新ルート案の実施に向けて必要な調整を進めていくです。","voiceIndex":99,"id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"もちろん横田空域のことについて、具体的な中身を引き出すというのは、それは国際問題もありますし、国の問題だと思いますので、その辺までは求めていないのですけれども、横田区域の問題で、今、膠着しているということは事実でありまして、そうした事実を生かして、品川区としても、この際ですから。","respondent":"鈴木都市計画課長","answer":"やはり区が行うべきことは、再三再四申し上げておりますが、国が計画案を進めるということを申しておりますので、区としてはこれまでどおり、丁寧な説明あるいは落下物対策、あるいは騒音軽減に向けた取り組みを国のほうに求めていくです。","voiceIndex":101,"id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"しかし、空路変更も含めて交渉をしていくということですから、ぜひとも、国策だという理由で何も交渉できないというのは、区民を守るべき自治体としてはいかがなものかと考えていますけれども、端的にお伺いしたいのですけれども、区が国に対して撤回を求めることができない理由は何なのでしょうか。","respondent":"鈴木都市計画課長","answer":"区が撤回を求められない理由ということで、私、これまで何か答弁を差し上げたことは今までなかったと思うのですけれども、これは撤回を求められない理由というよりも、区として、今、この計画案について国に対して求めていくことについては。","voiceIndex":103,"id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"それが理由で撤回を求めることができないということにはならないのではないかと考えていますけれども、ぜひともルート変更を含めて粘り強く交渉されていくということですから、やっぱり交渉内容の１つとして、横田区域の問題で膠着されているのだったら、今こそ撤回されたらいかがでしょうかということも述べていってもよろしいかと考えておりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"先ほど、あくつ委員とのやりとりの中でちょっとわからなかったことがあったので、防音対策上の飛行時間についても品川区のために国が改正したのだみたいな答弁があったと思うのですが、それは新たな動きがあったということなのでしょうか。保育施設等に広がったのも品川区が交渉したからだみたいなニュアンスのご答弁のようにも聞こえたのですけれども、そこら辺についてもう少し伺わせてください。","respondent":"鈴木都市計画課長","answer":"そうした意味では、１つの用途的な拡充と、それからあわせて、騒音防止工事費を助成する基準として、羽田空港における新たな飛行経路の運用に対応した航空機騒音の強度および頻度の基準を追加ということで、航空機騒音、この用途だけでは当然対象にならないものでして。","voiceIndex":108,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"単純に今までは１日の中でならしていたから、ほとんど防音の対象工事となるところは品川区内にはなかったのですけれども、今回、１５時から１９時という規定が加わることで、それが変化する可能性があるということなのでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"そういった国の拡充ということで、まず告示の内容は、基準的なことしか示されておりませんので、先ほどご答弁申し上げたとおり、そういった拡充がされて、区内のどういった建物が対象になるかというところを、今、国のほうに情報を求めているところです。","voiceIndex":110,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"区からも２つの政党に対して、意見、質問を受けとめているという答弁がなされたということですから、にもかかわらず、さきの本会議で共産党の鈴木ひろ子区議が、新ルートは住民の理解が得られていないということを区は認めるのですかと質問しました。改めて伺いたいのですけれども、品川区はこの新ルート計画に品川区民が理解をしていないということを認めないということなのでしょうか。伺います。","respondent":"鈴木都市計画課長","answer":"区としてもそういう認識です。これまでもご答弁申し上げておりますが、そうした声に対して、やはり教室型説明会等、直接的に区民の方に説明いただける場を国にしっかり求めて、区民の理解、周知を国のほうで行っていただきたいです。","voiceIndex":112,"id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"もう一度伺いますけれども、知らないという人もいるというのも事実だと思いますけれども、そうした知らないという人も含めて、現時点では区民の理解がないというのが、少なくとも議会の共通認識です。しかし、品川区としては、区民にこの計画の理解を得られていないということを認めないのですか。もう一度お伺いします。","respondent":"中村都市環境部長","answer":"したがいまして、区といたしましては、やはり区民の理解が得られているか、得られていないか、そういった二択ではなくて、今現在は、区民の理解が十分ではないという認識です。したがいまして、国に対してさらなる丁寧な説明を求めているです。","voiceIndex":114,"id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"さまざまな意見があるのは事実ですけれども、ただ、賛成という方は本当にごく一部の一握りの方だと思います。知らないという方ももちろんいます。あえて賛成もあったということを品川区が強調しているように聞こえますが、しっかりと区民の願い、このルートに対する反対の声を受けとめていくべきだと思いますし、それを受けとめた上でしっかりルートの撤回を国に強く求めていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-041"},{"speaker":"松永副委員長","kind":"質問","question":"先ほど、課長のご答弁の中に、第５フェーズの説明会が行われそうだというお話を聞いたのですけれども、今まで第１フェーズから第４フェーズまで行われて、約３,３００名の方が参加されたというふうに伺っています。ですので、何か区として新たな周知方法はご検討されているのか、その辺を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"これまで第１から第４フェーズの開催周知につきましては、このニュースレターですとか、そういった開催の案内について、区の都市計画課の窓口ですとか、そういったところで周知をしてきたところですが、委員ご指摘のとおり。","voiceIndex":117,"id":"exchange-042"}]},{"id":"topic-03","title":"平成３０年陳情第２０号 コミュニティバスの運行を求める陳情","agenda":"平成３０年陳情第２０号 コミュニティバスの運行を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"区長がコミュニティバス運行を公約に掲げて実施を表明しているという以上、この陳情はそういった方針の後押しをするものでありますので、ぜひ採択するべきではないのかと思います。歓迎したいと思います。一般質問でも聞いたのですけれども、特に答弁がなかったかと思ったのですが、運行することに方針を変えた理由は、何か状況の変化とか何かあったのでしょうか。伺いたいと思います。これが１点です。","respondent":"鈴木都市計画課長","answer":"来年度よりコミュニティバスの導入について検討を始めていくというところの理由ですが、やはり先ほども申しましたが、鉄道、バス、こういった地域交通につきましては、非常に区民にとって日常生活に必要不可欠なライフラインだという認識です。","voiceIndex":151,"id":"exchange-043"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそういった施策の土台があるということで、日常生活にとって不可欠なライフラインという認識も示されましたけれども、移動の権利保障という点もしっかりと踏まえた上で検討していただきたいと思います。７時台は１時間に１本、９時台も１時間に１本、１０時から１３時台は１台もないということでないのです。以上２点伺います。","respondent":"鈴木都市計画課長","answer":"既存のバスルートの運行本数が少ないということに対しての考え方ですが、コミュニティバス導入に向けた検討に当たっては、一番大事なところ、一番といいますか、大きな課題となるところが、やはり既存のバス路線との競合についてというところだと思います。","voiceIndex":153,"id":"exchange-044"},{"speaker":"安藤委員","kind":"提案","question":"難しいというのは、ちょっと理由がわかりませんが、なぜ全域で走らせるのが難しいと考えておられるのかお伺いしたいと思います。区民の声を聞きながら検討していくという答弁が本会議でもありましたけれども、ルート選定の調査内容の中に、やっぱり具体的に区民の皆さんが感じている不便な行き先を調査する必要があると思いますし、そちらを提案したいと思いますけれども、こちらについてはいかがでしょうか。","respondent":"鈴木都市計画課長","answer":"地域の声をお聞きしながらというところは、当然ながら検討を進める中ではさまざまな手法を使って地域の方の声を聞きながら検討を進めていくというところはしっかりやっていきたいです。","voiceIndex":155,"id":"exchange-045"},{"speaker":"安藤委員","kind":"提案","question":"ちょっとぼやっとしているのですが、私が伺ったのは、区民の皆さんが感じている不便な行き先ということです。一部地域にとどまっては困ってしまうと思っていまして、そういった地域はたくさんあるのではないかと思うので、先ほどから調査をしたらどうかという提案をさせていただいているのですけれども、今の時点で一部地域というのは、およそどこに当たるのか、現時点での区の考えを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"一部地域、遠い地域につきましては、やはり公共交通、これ、民間のバス会社がしっかり地域に、品川区内を網羅して走っていただければ一番バスの運行的にはいいのかですが、やはりそういった意味でバス停から遠い地域を挙げるとすれば、道路の狭い荏原地域ですとか大井地区が。","voiceIndex":157,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望になりますけれども、実際に暮らしていて、移動に不便を感じているのは区民の皆さんなわけですから、こういった形で地域から声が上がるということは非常に重要だと思うのです。こういったこともきちんと踏まえて、コミュニティバスの事業化を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"特定の会派がいたずらに根拠もないような要望を出して、それに対して区が検討しませんという、考えておりませんという答弁を出されてしまって、非常にやりにくい中で、私どもとしては、どういう根拠があればこれは検討していただけるのかということで、平成２４年の第３回定例会の一般質問で地域公共交通会議、これは先日の一般質問でも、たけうち委員長のほうからございましたけれども、この設置を求めて。","respondent":"鈴木都市計画課長","answer":"当然ながら、区民の方のお声、アンケートですとか、そういったところをとりながら、しっかり区内のコミュニティバスの効率的なあり方について、検討会でもご意見をいただきながら、しっかり検討していきたいです。","voiceIndex":160,"id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどの私の質問を訂正させていただきたい。根拠がないというのは確かに言い過ぎでした。根拠はあります。ただ、批判をするような、そういうやり方、交渉、一方的な言い分だけを述べる、こういうやり方をすると、どうしても区役所のほうから否定的な答弁が返ってくる、これは事実でありましたので、指摘をさせていただいた次第です。これは意見ですけれども、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-049"},{"speaker":"大沢委員","kind":"質問","question":"もちろんもう一致しているから、このような実現に向けての具体的な取り組みを行政側が始めたと思うのですけれども、そこはやはり首長と現場をお考えになっている行政当局の考え方、一致をしているというのが前提のことなのですけれども、どうなっているか、現状をお伺いしたいのですが。","respondent":"鈴木都市計画課長","answer":"それを補完するところが１つ行政の役割なのかというところは、担当として痛感しているところでございまして、ただ一方では、さまざまな視点で検討する中では、やはり公的な事業として、税金を投入するわけですので、しっかり事業採算性についても検討しながら、本当に効率的な。","voiceIndex":163,"id":"exchange-050"},{"speaker":"大沢委員","kind":"質問・要望","question":"確かに一番身近な行政であります区政は、地域の方に対して耳を傾けて地域の要望に十分にこたえていくというのは大前提でありますけれども、先ほど、あくつ委員もおっしゃったように、福祉的な部分の兼ね合いも考えながらなのですけれども、やはり区の事業である以上は、採算度外視というのは、あまりいただけないと私は考えておりますけれども、そこらあたりの補完をされる手立てなり。","respondent":"鈴木都市計画課長","answer":"やはり実施検討に当たっては、その事業採算性的なところは重要な課題ですので、しっかり検討してまいりたいと思います。","voiceIndex":165,"id":"exchange-051"},{"speaker":"大沢委員","kind":"質問","question":"過疎地においては、つい近ごろ、新聞紙上で、タクシーでの荷物輸送が解禁されたという報道も目にしましたが、先ほど、課長がおっしゃったように、コミュニティバスは、基本、狭隘な、大型バスが通れないところの交通の便が悪いところを運行するというような特性があるので、その狭隘なという部分に関しては、タクシーのほうがより小回りがきくし、利便性も速さも。","respondent":"鈴木都市計画課長","answer":"当然ながら、検討を進める上では、こうしたタクシー事業者の方からも意見を伺いながら、しっかり検討してまいりたいというふうに考えております。","voiceIndex":167,"id":"exchange-052"},{"speaker":"筒井委員","kind":"質問・要望","question":"この陳情にもありますとおり、福祉目的はもちろん、各地域間の交流、商業、観光の活性化という視点からでも、ぜひルートとかバス停の所在等々を考えていただきたいのですけれども、この各地域間の交流、商業、観光の活性化という点において、区としては現時点でどうお考えなのでしょうか。","respondent":"鈴木都市計画課長","answer":"観光視点、あるいはそういったところが品川区としてなじむかどうかというところも含めて、あらゆる視点で検討は進めていきたいです。","voiceIndex":169,"id":"exchange-053"},{"speaker":"筒井委員","kind":"質問・要望","question":"地域間の交流ということで、特に品川区の東西を結ぶような路線をつくっていただきたいということを前から述べさせていただきましたけれども、その点に関連しまして、補助２６号線が有効に活用できるかとは考えられるのですけれども、補助２６号線は、先ほどのほかのバスとの競合という点もありますけれども。","respondent":"鈴木都市計画課長","answer":"当然ながら、コミュニティバス導入の検討に当たっては、補助２６号線の開通は大きいところですので、こうしたところも視野に入れながら検討していきたいです。","voiceIndex":171,"id":"exchange-054"},{"speaker":"筒井委員","kind":"確認","question":"今、そうした確認をとらせていただいたのは、平成２３年８月の第２回品川区まちづくりマスタープラン策定委員会の議事録を見てみますと、当時の都市計画課長が、補助２６号線開通とともに、東急バスが世田谷－武蔵小山－大井町を結ぶ路線で運行するということが確定しておりますということを答弁されているので、そうしたことになっているのかと思ったのですけれども、今ご答弁いただいた状況では。","respondent":"鈴木都市計画課長","answer":"それについてバス事業者から前向きな回答はいただいているところですが、何か文書をお互い正式に取り交わしたということではございませんので、そうした意味でご答弁させていただいたものでございまして、状況としては変わっていないです。","voiceIndex":173,"id":"exchange-055"},{"speaker":"安藤委員","kind":"意見","question":"本日を結論を出すで、採択ですが、やはりこれまでこのような陳情をはじめとする区民の意見が今の区長をしてコミュニティバス運行にこぎ着けたということで、この陳情は採択して、今後さらに区政を進めていく必要があると思いますので、採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":178,"id":"exchange-056"},{"speaker":"松永副委員長","kind":"質問","question":"我が会派は、継続でお願いします。先日行われました第３回定例会でも、コミュニティバスについての質問があり、今後、各公共機関、関連会社と、地域交通検討会で既存路線などの議論を重ね検討されていくということで説明があったので、私たちの会派としては、その検討会の動向を見据えながら今後について考えていきたいと考えていますので、この陳情に関しては継続とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":179,"id":"exchange-057"}]},{"id":"topic-04","title":"の戸越六丁目東地区のまちづくり","agenda":"の戸越六丁目東地区のまちづくり","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の６ページで、左上の説明会についてというところで、なぜ公聴会を開かないのかという質問に対して、「法第１６条の主旨を踏まえ、公聴会と同様に」という答えが出されておりますが、ということは、都市計画審議会には、この公聴会と同様にということがありますので、８月７日の説明会で出された意見というのは、その意見書の内容とあわせて、資料として提出されるのでしょうか。これがまず１点です。","respondent":"鈴木都市計画課長","answer":"前回の説明会でいただいたご意見、またこれから開催する説明会でいただいた意見の都市計画審議会への提出につきましては、基本的にはする方向で考えていきたいと考えています。","voiceIndex":186,"id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ都市計画審議会、私も委員ではあるのですが、ちょっと審議が停滞しているといいますか、ほとんど意見が出ないのです。これ以上の形骸化を防ぐために、ぜひそういった措置はやっていただきたい、これは要望です。まち並みに大きな影響を与える計画です。説明会の案内の仕方、どういうふうに多くの方に参加してもらうような工夫ができるのか、対象の範囲ややり方について伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"こちら、今日配付している資料と同様の案内書をポスティング、それから郵送の資料としてご案内をする予定となっています。区のホームページでもご案内の予定もありますし、それから、広報しながわの１１月２１日号にも掲載の予定としております。","voiceIndex":188,"id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"ですから、今回そういったところに大きな影響を与えるという点では、この範囲の中に住んでいる住民だけへの周知でいいのかと私は思います。少なくとも時間帯を変えて、曜日を変えて、増やすべきだと思いますけれども、いかがでしょうか。伺います。","respondent":"東野まちづくり立体化担当課長","answer":"こちらにつきましては、この内容について一定のお知らせをするということで、働いている方のことも想定しまして、夜という時間を設定させていただいてあります。この日程で、２回目の説明会となりますので、十分な内容のお知らせができるというふうに考えてあります。","voiceIndex":190,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひもう少し一歩進んで、まちづくりのことですから、この計画そのものの賛否はいろいろ立場の違いはあるにしても、少なくともこういった問題を住民の方に知らせるということについては、まだまだ努力が足りないのではないかというふうに思いますので、改善をぜひ考えて行っていただきたいと強く申し上げたいと思います。資料であと２点ほど気になる点があったので伺います。伺います。","respondent":"鈴木都市計画課長","answer":"説明会の中で補助２９号線自体は東京都が平成３２年度を目標に掲げて取り組んでいるというところのご説明をさせていただきました。","voiceIndex":192,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"今のご説明を聞いても、補助２９号線、防災のための事業だと説明されてきましたけれども、やはり防災とは関係ないのかなというふうにどうしても思わざるを得ないような印象です。それと、私が伺ったのは、７ｍ、３００％が延焼を防ぐ機能を果たすという根拠はあるのですかということで、なるべく高いほうがいいですということしか書いていないのですが、何も根拠はないということでよろしいでしょうか。","respondent":"鈴木都市計画課長","answer":"そうした中で、当然ながら、延焼を防ぐためには高い建物が必要なわけですが、そこに都市計画的な規制をかけて、例えば２０ｍ、３０ｍというのは、当然ながら現実的ではないというところでございまして。","voiceIndex":194,"id":"exchange-062"},{"speaker":"安藤委員","kind":"意見","question":"やはりなるべく高いほうがいいとか、あるいは、なるべく早くつくられたほうがいいけれども、特に目標年度はありませんというようなところで、やはり防災のことを考えている事業だとは到底思えません。この計画案を私はやめるべきだというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":196,"id":"exchange-063"}]},{"id":"topic-05","title":"の平成２９年度指定管理者による管理に対するモニタリング・評価","agenda":"の平成２９年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"それと、対応方針のところで、それに対しては、「出来るだけ早期に連帯保証人と連絡を取り、滞納額が少額の段階での着実な納付促進を行っていく必要がある」、とあるのですけれども、できるだけ早期に連帯保証人と連絡をとる、こういうふうな改善策が書いてあるのですが、具体的にどの時点のことをおっしゃっているのか、１回でも滞納したら連帯保証人に連絡をとるというのが現実的なのか、そこについて。","respondent":"森住宅課長","answer":"当然、弁護士も入って相談しながらやっているということです。ただ、６カ月を超えてしまうような場合につきましては、まずそれだけの使用料を払っていただけていないということで、明け渡しを求めるということを進めているところです。","voiceIndex":206,"id":"exchange-064"},{"speaker":"あくつ委員","kind":"確認","question":"ちょっと私も意地悪な言い方をしましたけれども、ただ、すごい高い水準での収納をしていることは間違いないので、実態的にはものすごい良いお仕事をしていただいたいるのかなとは思いますので、そこのところを指摘したかったわけではないので、ただ、文書の表現的に確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"宅建センターのところで、ご説明の中で収納率の向上を今回の重点項目にしたと、改善が図られたということがあったのですが、今年度の目標に収納率の向上を書かれたという理由と、もう１つは、ちょっと説明がありましたけれども、効率・効果的な納付指導を行った結果というのがありましたけれども、収納率が上がった理由について、もう少しお伺いしたいというのが１つです。伺います。","respondent":"森住宅課長、古郡交通安全担当課長","answer":"これは、平成２６年以前のところはもう表が切れてしまっていますけれども、この前まではそれほど高い数字ではございませんでしたが、今回、先ほども申しました定期的な連絡をとりながら。人員体制の関係については、職員については全部で７４名、場長が全部で１１名ということで、離職率については把握はしておりません。","voiceIndex":209,"id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"こういったサービスの評価にかかわる大事なところは、私は人員体制だと思いますので、ぜひ、今ご答弁いただきましたけれども、何名の方がどのような従事をされているのか、常勤なのか、非常勤なのか、やはり離職率のあたりを、区としてもサービスの状況がどうなっているのかにかかわってきますので、把握していただきたいと思いますし。","respondent":"森住宅課長","answer":"総括シートにつきましては、全庁共通で決めているものでありますので、大きく変えるということは考えてございませんけれども、宅建については、２ページ目の４番で専従職員６名というような記載をさせていただいているところです。","voiceIndex":212,"id":"exchange-067"},{"speaker":"横山委員","kind":"質問・要望","question":"自転車等駐車場について教えてください。業務改善というところで、フリーゾーン制の導入ということもしていただいて、こちらも利用率が向上されたということなのですけれども、自転車だけなのか、バイクもなのか、また、管理者の方がいらっしゃって、どういう運用や利用の補助をされているのかというところを教えていただきたいと思うのですけれども、お願いいたします。","respondent":"古郡交通安全担当課長","answer":"以前は番号を指定して、そこだけしか使えないという状況でございました。満足度の向上については、自転車のチャイルドシートの関係で、お子さんを乗せている場合や物が多かったりした場合について、管理員が補助をしてやっているという状況です。","voiceIndex":214,"id":"exchange-068"}]},{"id":"topic-06","title":"の品川区空き家等対策計画の素案について（パブリックコメントの実施）","agenda":"の品川区空き家等対策計画の素案について（パブリックコメントの実施）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"大きいＡ３の１枚目の資料の左下のほうに、２０１７年度末現在の状況が書いてありますけれども、この計画をつくった以降もどんどん増えているとは思いますが、この計画にこういったさまざまな対策が書いてあるのですけれども、おおよそどの程度、空き家を改善していくお考えがあるのか。目標についてお伺いしたいと思いますし、どの程度進むと想定されているのか伺います。","respondent":"森住宅課長","answer":"当然、相続とか、特養ホームに入居されてしまったりとかして、どうしても空き家になってしまうということは避けられない部分もありますけれども、そういった改善についても、セミナーとか、あるいは記載しておるそれぞれの事業を進めまして、数字上、なかなか難しいですが。","voiceIndex":221,"id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"特に目標というのは答弁の中ではないのかと思ったのですが、現状の数が示されていますけれども、例えばこの数を増やさないようにしていこうとか、新たに空き家になったりとか、空き家解消になったりというプラスマイナスの例はあると思うのですけれども、例えば、そういったような目標も特にこの計画では書かれているものではないということでよろしいのか確認させていただきたいのと、それともう１つは。","respondent":"森住宅課長","answer":"はこれを適正な管理にしていくというところが目標としては挙げられるかと考えております。それから、維持管理を行っていない理由、１９件になってありますが、アンケートの中で回答をいただいたものがこの数です。","voiceIndex":223,"id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"今のお話ですと、実際、維持管理をどうにかしたいと思って悩んでいるというのではなく、そもそも維持管理をしなくてはいけないという認識がないということが一番の要因だということで、そういう区の認識ということでよろしいですか。","respondent":"森住宅課長","answer":"当然、さまざまな要因がありますけれども、管理の促進の通知を送っている中では、返ってきた答えとして、遠くに住んでいるということもありまして、なかなか日常の生活の中で品川区内にある空き家について考えるということがなかなかないというようなところなのかというのは。","voiceIndex":225,"id":"exchange-071"},{"speaker":"安藤委員","kind":"質問","question":"それに対応して対策を立てていくというのは重要だと思います。ですから、ここにいろいろ書いていますけれども、公的利活用の検討というのは、どういうことなのか。あるいは、実施体制というところで、町会・自治会という名前が出ていますけれども、町会・自治会による所有者への適正管理や利活用に向けた情報提供ですとか、あるいは、これは情報提供というのは、どういうことを意味するのか伺いたいと。","respondent":"森住宅課長","answer":"地元への情報提供ということで、個人情報の関係もありますので、なかなか難しい部分もありますが、空き家に関する相談をどんどんいただいて、それに対する検討状況であったり、所有者の活用状況であったり、そういうようなことを情報提供していきたいと考えております。","voiceIndex":227,"id":"exchange-072"},{"speaker":"安藤委員","kind":"質問","question":"最後ですが、やはり地域にとってもプラスになるような空き家の活用につなげていくのがいいかなと思っていまして、冊子のほうの３７ページで、先ほどの質問させていただいたところで、具体的な施策ということで、公的利活用の検討の項目に、「所有者等が空き家等を公的活用のために無償提供する場合、地域活性化のための施設等の活用を検討します」とあるのですが、無償提供となりますと。","respondent":"森住宅課長","answer":"他区の状況を見てみますと、有効活用の中で、用途変更に応じて固定資産税が上がるものを対策してもらえばとか、費用面の課題もありそうなので、そういった意味も含めながら、活用については所有者の意向にこたえながら進めていきたいと考えております。","voiceIndex":229,"id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど、意向調査もまたやるというお話でしたけれども、そこからどう一歩踏み込むのか、先ほどの専門家の団体の方たちからお話を伺うと、年に１回でしょうか、２回でしょうか、情報交換会のようなものをやられているということでしたけれども、正直、多分、やりたいことは、またできることはたくさんあるのですというのが、多分、業界団体の専門家の方たちのお考えだと思うのです。","respondent":"森住宅課長","answer":"居住支援協議会のお話がありまして、今の検討状況ですが、８月の末ごろ、関係各課を住宅課で集めまして、各課長と情報共有を行っているところです。","voiceIndex":231,"id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"一点突破というご答弁があったのですけれども、本当にここ数年、時の住宅課長が非常に悩まれて、本当にここは全庁対応と書いてありましたけれども、全庁対応が本当に必要な中で、福祉的用途であったり、そういったものも盛り込んでいなければいけないというご苦労は、ずっともうここ数年、お聞きしてきまして、本当に１件でも２件でも、１件でも突破していただきたいというのが正直な思いですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":233,"id":"exchange-075"},{"speaker":"大沢委員","kind":"質問","question":"この住宅の全体的な需要と供給のバランスを考えた場合、将来的なもので、ある程度の目安なり規制をかけていかないと、ますます空き家等というのが、要は、住む家はあるけれども、入る人間が少なくなってくるわけですから、そこら辺のバランスが崩れていく。教えてください。","respondent":"森住宅課長","answer":"適正な規模というお話もございましたけれども、空き家につきましては、基本的に相続がきちんとなされて、流通が促進されてというようなことが一番原則としてはあるかと考えておりますが、区としましては、セミナーとか、そういったことの中で、空き家になる前から。","voiceIndex":234,"id":"exchange-076"}]},{"id":"topic-07","title":"の都市再生機構（ＵＲ）との木密事業に関する協定について（西品川２・３丁目地区）","agenda":"の都市再生機構（ＵＲ）との木密事業に関する協定について（西品川２・３丁目地区）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"協定の目的というところが書いていないのですけれども、協定書には目的はないのでしょうか。内容をお持ちであれば、ご紹介いただきたいというのと、あと、資料の４番目の協定の骨子というところで、「区が地域への周知や」とあるのですけれども、これは具体的に何をどのように周知するのか伺います。それと、こういった手法は、他区や全国、ほかのところでも一般的に行われていることなのか伺います。","respondent":"高梨木密整備推進課長","answer":"そういった土地がありましたら、どんどん情報をくださいといった土地の提供に対する住民への啓発も同時に行いたい、このように考えているところです。","voiceIndex":241,"id":"exchange-077"},{"speaker":"安藤委員","kind":"質問・要望","question":"先行している豊町４・５・６丁目、二葉３・４丁目および西大井６丁目地区ということで、こちらの事業効果といいますか、どのような状況になっているのか少しご紹介いただきたいということが１つと、それと、今回、なぜＵＲとなのかというのは、木密事業の事業促進業務委託先ということがありましたけれども、もしそれ以外で何かあればお伺いします。","respondent":"高梨木密整備推進課長","answer":"なぜＵＲと締結するのかというところですが、今おっしゃっていただいたように、まずは西品川２・３丁目地区の事業促進業務委託をＵＲと締結しているというのが一番大きな理由ですが、ＵＲとは、平成２０年に品川区における防災まちづくりに関する協定ということで。","voiceIndex":243,"id":"exchange-078"},{"speaker":"安藤委員","kind":"質問・要望","question":"このようにＵＲと協定を結ぶに当たっても、地域環境に配慮したような一定の節度を持った高さは、区としてはしっかり求めていく必要があるのではないかと思いますけれども、協定の中にそのようなことを盛り込めれば盛り込んでいただきたいと思うのですけれども、そのようなことが可能なのかということと、あと、防災が主な目的の事業でありますが、地域環境との調和という点では。","respondent":"高梨木密整備推進課長","answer":"西品川２・３丁目地区におきましては、先ほど冒頭で説明いたしましたとおり、今年度から密集市街地整備の新事業を入れております。","voiceIndex":245,"id":"exchange-079"},{"speaker":"安藤委員","kind":"質問・要望","question":"未接道宅地の解消ですとか、あるいは行きどまりの道の解消ですとか、そういったことはこの地域でも非常に課題になってくる件ではありますので、今、課長も言っていました共同化ということに特化したわけではないと思っていますので、さまざまな工夫を重ねながら、そういった地域の課題の解決を目指していっていただきたいと思いますし、協定とは直接関係ないかもしれませんけれども、進めるに当たっては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":247,"id":"exchange-080"}]},{"id":"topic-08","title":"のゆうぽうと跡地のにぎわいのあるまちづくりに関する協定","agenda":"のゆうぽうと跡地のにぎわいのあるまちづくりに関する協定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"内容ですが、店舗が１階ということですけれども、店舗は１階だけなのかという部分と、それと、この概略ですけれども、およそこういったものが固まる時期といいますか、固める時期はいつごろと聞いているのか伺いたいと思います。それと、もともとあった建物の高さと階数と比べて、今回の２０階１００ｍ程度というのは、どの程度のボリューム感になるのか。そこら辺についてもお伺いしたいと思います。","respondent":"稲田都市開発課長","answer":"以前の建物ですけれども、メートル数ではわからないのですけれども、以前の建物は地上１５階、地下４階建てというふうに記録されております。","voiceIndex":252,"id":"exchange-081"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、今回は日本郵政不動産株式会社ということですが、もともとは郵政、郵便局だったわけですから、公務員というか、公共的なところが持っていたわけですが、今は、いろいろありまして、民間企業になっているわけですけれども、今回、民間は民間ですから、区は口出しできませんということではなくて、過去のそういった経緯もあるのかとは思うのですけれども、一定、地域からの要望に基づきということで。","respondent":"稲田都市開発課長","answer":"そういう中におきましては、地元の要望が、ホール、当初は前と同じぐらいと言われたのですけれども、小さくなりましたが、何とかにぎわいをつくってくれというところで、区もそのとおりだというふうに思いまして、そういうことで以前から日本郵政に対しては、にぎわい施設の検討。","voiceIndex":254,"id":"exchange-082"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、ホール施設の条件整備を協議ということで、賃借するに当たっては、やはりなるべく低廉な使いやすい、区民の方が文化を振興するに当たって、使いやすいような仕組みにしていただきたいと思うのですけれども、例えば、ホールを使うに当たっての空き状況の確認ですとか、あるいは使用申込のやり方は、わかりやすいものに、簡単にできるように、現在行っている施設管理システム。","respondent":"稲田都市開発課長","answer":"使い方等々ですが、これは今後の運営方法というところで、当然その辺は考えているところですが、今後、検討していくです。","voiceIndex":256,"id":"exchange-083"},{"speaker":"筒井委員","kind":"質問","question":"前にもこのお話が出たときにご説明していただけたかと思うのですけれども、この協定書のところで、区がホール施設を賃借するということになっていますけれども、丸々品川区が通年ずっと借りて、貸出とかの管理も区がやるということなのでしょうか。どのような仕組みになるのかをお知らせください。","respondent":"稲田都市開発課長","answer":"今、委員おっしゃったように、区が丸々借りて、委託とか指定管理とかの手法はあるかもしれませんけれども、区が運営するという形を考えています。","voiceIndex":258,"id":"exchange-084"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"所管質問というよりも、その他でもしかすると報告があるかもしれないのですけれども、１０月２５日の自民党・子ども未来の鈴木真澄議員の一般質問で、大井町のまちづくりの中で、区庁舎のオイルダンパー、免震装置について……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":264,"id":"exchange-085"},{"speaker":"安藤委員","kind":"質問","question":"実際に品川区庁舎のところの免震装置４つのうち１つのダンパーがそれに関係していたということもあったかと思うので、そこら辺について、現状どうなっているか。その対策の見通しについてお伺いします。","respondent":"長尾建築課長","answer":"その後の対応の状況のところまでは、現時点では把握はしていないのですけれども、先ほどお伝えしたように、不適合の状況を製造事業者から報告を受けた上で、基準法上の不適合状況の確認や安全性検証結果を踏まえた適正指導というところが、この総合庁舎につきましては。","voiceIndex":270,"id":"exchange-086"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4246#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":77727,"voices":272}},{"id":"h30-20181029-9","meetingId":"h30-cm10","date":"2018年10月29日","dateIso":"2018-10-29","committee":"文教委員会","time":"午前１０時００分～午後 ３時２２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を106件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第７５号議案、品川区立保育所条例の一部を改正する条例","agenda":"第７５号議案、品川区立保育所条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"八潮南保育園の関係で、八潮わかば幼稚園と幼保一体施設になるということなのですが、完成したときのそれぞれの定員数を教えていただきたいのと、それから八潮北保育園についても、工事が終了してもとに戻るときの定数、それと平成３２年４月なので期間があと１年半ぐらいあると思うのですけれども、そうすると、この間の議論では、公設民営、民営化。","respondent":"吉田保育施設調整担当課長","answer":"民営化のところですけれども、八潮北保育園については、平成３４年から民営化いたしますので、平成３２年度に業者を選定する予定としています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"幼保一体施設のほうについてなのですが、幼稚園部分と保育園部分、それぞれの定数を改めて確認したいので、別々に教えていただきたいと思います。そうすると、職員はどういうふうな処遇になるのか、全取っ替えになってしまうのか、ちょっとその辺が全くわからないので、今の考え方でいいですから教えていただきたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"平成３４年に委託になりますけれども、平成３３年度あたりで引き継ぎ保育を行いまして、平成３４年から受託した事業者に速やかに移行できるように１年間程度の猶予を考えて今のところ予定しているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"幼保一体施設のほうなのですけれども、幼稚園部分といわゆる保育園部分と、あわせて、定員が９７人という理解でいいのですか。ちょっと違うのかなと思ったので、再確認で、それぞれの定数を教えていただきたいと思います。引き継ぎという言葉では。それから、八潮西保育園は八潮北保育園が終了してから引っ越し、改修というふうに同じようなスタイルでいく、そういうことでいいのかどうかを教えてください。","respondent":"吉田保育施設調整担当課長、佐藤保育課長","answer":"八潮西保育園につきましても、同様に、１年あとになりますけれども、平成３２年度に改修した後、平成３５年度から民営化のほうを進めていく予定で進めているところです。民営化実施時の保育士の採用の関係ですが、現時点での考え方になりますけれども、現行と同様に退職者の数に応じて新規の採用をしていますから、そういった形でやっていきたいと考えております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"この民営化の問題は、品川区にとって初めてですよね。ここに来て、ごっそりと５園分を民営化するという方向が一、二年前から出されて、非常に懸念をしていたのです。しかし、進んでいるわけですから、保護者はもちろん、近隣の方々の理解も含めて、やはりきちんとそごのないように、信頼を持っていただけるような、そういう移行の仕方を強く求めておきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。だけど、その辺のそういう意見もあるということは十分受けとめて、プロジェクトで検討中だということなのですけれども、しっかりと対応していただきたいということをちょっと悔しい思いも込めながら申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"今回は４園の所在地の変更と追加ということなのですけれども、やはり今、南委員が質問したように、民営化絡みの大規模改修が入っているということで、共産党としては問題視をしています。今もその考えは変わりがないのかどうかお伺いするのが１点です。３点目は、民営化が決まっている園を改めて伺います。いつから、どこの保育園が民営化されるのか、改めて伺います。","respondent":"吉田保育施設調整担当課長","answer":"考え方としては、先ほどの１番目で申し上げました施設水準のいいところから委託をしていくというところがありまして、この間、委託に関するプロジェクトチームで他の自治体から話を聞いた中で、やはり建物がある程度新しくないと。","voiceIndex":15,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"施設をきれいにリニューアルして委託をするというのは、受託業者にとって当たり前ですが、大変有利は有利ですよね。初めにできた古い保育園が全然改修されないで、そのまま放置をされている。やはり私たちはこの点、ちょっと納得できないのですが、いかがでしょうか。もっときちんと改修してほしい保育園があるのですけれども、どう考えていらっしゃるのでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"土地の確保、ここはなかなか難しいところですので、今のところ、大規模な建て替え、確かに建ててから５０年過ぎのものも結構たくさんあるのですけれども、なかなか計画を立てて、ここからやろうというのは難しい状況です。","voiceIndex":17,"id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、やはり声がないというのは、知らないでいるというのがかなり多いのではないかと思うので、やはり今後の状況を親御さんたちにきちんと伝える手だてをとっていただきたいと思うのですが、その点はいかがでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"その後につきましては、保育園の入園のご案内等において、ここの園はいついつから民営化いたしますということを記載しています。そのため、お入りいただくのはそれが前提ということで考えておりますので、今のところ、第１回目の説明以後、説明のほうはしていないところです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そうですよね、０歳の子だって、３年後だと、３年間いた後の問題ですよね。入園のご案内に民営化しますと書いても、民営化が一体どういうものなのかというのがわかる方というのはほとんどいない、品川区がまだ民営化されていないというところにおいて、想像がつかないと思うのですよね。これは本当にしていただきたいと思うので、どうでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"周知の方法については、また今後検討してまいるところです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ確認をさせていただきたいのですが、いわゆる旧荏原第四中学校跡地の敷地内にほうさん保育園と南ゆたか保育園の二つの保育園ができるということですよね。一つの敷地に二つの保育園があるというのはなかなかほかのところではないケースだと思うのですが、この二つの園でのさまざまな調整が必要になってくるのかなと思います。","respondent":"吉田保育施設調整担当課長","answer":"それから動線については、この図ではわかりづらいかもしれませんが、入り口が分かれております。校庭の使い方については、前回文教委員会でご報告したとおり委託事業者が決まったところですので、その辺は区とまた事業者のほうで調整しながら進めてまいりたいと今検討しています。","voiceIndex":23,"id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いわゆる問題がないようにしっかりと、調整というよりも連携というのですかね、そういったことをやっていただきたいと思いますので、それは区のほうも一緒になってやっていただければと考えています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-011"},{"speaker":"渡部委員","kind":"質問・要望","question":"せっかくですから、そういうところもそろそろ改築期に来ているのであれば、やはりこれは行革的な話になるのかもしれないのですけれども、一旦全庁的にこれをどうするかというのを話し合った上で、方向性を見据えて早目に周知を始めていいのではないかなと私は思うのですが、どういうふうに民営化等もこれから先に進めていこうかとか、何かビジョンがあってやっているのか。","respondent":"吉田保育施設調整担当課長","answer":"今ある区立保育園の民営化につきましては、５園ほどお試し期間といいますか、民営化して、それでその状況等を鑑みながら今後の方針をどういうふうにしていくかを定めていきたいと考えているところです。","voiceIndex":26,"id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"お試し期間という話だったので、その辺を受けてこれからやるにしても、区のほうでも採用計画等もありますでしょうし、保育をする公務員の方々も何百人、６００人強でしょうか、いらっしゃって、それをどうするかというのも考えていかなければならないでしょうし、逆にここの旧荏原第四中学校跡地は広いですから。","respondent":"吉田保育施設調整担当課長","answer":"行財政改革特別委員会などでも報告があったと思いますが、旧荏原第四中学校跡地の使用方法につきましては、企画の部門から５年間という制限を承っているところがありまして、その５年間の中で何ができるかというところで公設民営と建て替えにつきまして。","voiceIndex":28,"id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"大変失礼いたしました。承知しております。ここがあるうちに一気に仕掛けられることは仕掛けていただきたいなという要望だけをして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"八潮のほうなのですけれども、先ほど引き継ぎ保育の話が出ましたが、ほかの自治体で引き継ぎ保育を非常にきちんとやって、要するにそれをまたいで民営化した保育園に預けている保護者の声の中で、そこできちんとやってもらえたので民営化した後も安心して預けることができたというお話を伺ったことがあるので、ぜひそこのところをきちんとやっていただきたいという、確認です。","respondent":"吉田保育施設調整担当課長","answer":"給食施設については、現状の八潮わかば幼稚園のところの工事を今進めており、そちらの給食室のほうは、１２月中にはでき上がる予定で進めております。","voiceIndex":31,"id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そうすると、園児の移動については、混乱が出るため１カ月日程のずれがあるということですけれども、入園して１カ月で動くので、お子さんたちの慣れぐあいといいますか、ちょうどそういう混乱の時期なので、移動は十分配慮してお願いしたいと思います。給食室ですが、旧荏原第四中学校のほうの保育園の給食室はどうなるのですか。","respondent":"吉田保育施設調整担当課長","answer":"大変失礼いたしました。旧荏原第四中学校のほうの建て替えのほうの給食施設につきましては、この図で言いますと、ピンク色のところの左側のほうに給食室をつくっているところです。そちらのほうで給食の用意を行う予定です。","voiceIndex":33,"id":"exchange-016"},{"speaker":"高橋（し）委員","kind":"質問","question":"旧荏原第四中学校のほうは、ピンク色の一番左側のところでつくって、そこから外を通って運ぶわけですか。両方に持っていくわけですか。","respondent":"吉田保育施設調整担当課長","answer":"説明が不足して申しわけございませんでした。南ゆたか保育園とほうさん保育園は、それぞれ別々に給食室があります。","voiceIndex":35,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"園庭に出さないとか、外に出ないとか、そういうふうに縮こまる保育であってはならないわけで、やはりそういう点でご近隣の方々へのそういう不安だとか、困ったというような状況に対しては、区がしっかりと説明をしていただいて、そして職員の方があまりそういうことを気にせずに保育が進んでいけるようにしていただきたいのですが、その件についてどうかというのを一つ伺いたいです。２点です。","respondent":"吉田保育施設調整担当課長","answer":"確かに時代の変化等で子どもの声が耳ざわりだと言われるような状況、最近はそういう状況も見受けられますが、近隣への配慮や近隣への上手な周知といいましょうか、ご理解をいただきながらこの辺は進めていければと考えているところです。","voiceIndex":38,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"八潮わかば幼稚園の関係ですけれども、私が言いたいのは、区がやはりきちんと住民に対して責任を持って対応していただきたいと、そこの姿勢を確認したいということです。４園は、実施するに当たってのテストと、そういう状況で捉えているということですか。そうであるとしたら、とんでもないと、ちょっとあまりにも無責任だなと私は思いますので、その辺についてどうなのかを確認したいと思います。","respondent":"吉田保育施設調整担当課長","answer":"子どもの声等につきましては、八潮といわず、どこでもある問題でもありますので、区のほうとしても苦情への対応、地域、近隣への理解、この辺につきましては、今後も進めてまいるところです。","voiceIndex":40,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"１０億円かかるということの意味がよくわからないので、もう一度説明していただきたいのと、民間活力とコスト削減、この２つがテストとしてやる、この４園の民間委託だと、そういうことでいいのですか。","respondent":"吉田保育施設調整担当課長","answer":"民間への委託というところは、今後も財政負担の、繰り返しになってしまいますけれども、区の一般財源の使用を抑えられるという意味では、国の補助金が使えるような民間園というのは、これはある一定程度必要なものと考えております。","voiceIndex":42,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"子どもを育てるのに経費を削減することが優先されていいのでしょうか。建て替えだけではなくて、取り壊しの費用とかも入れたら、それ以上にかかるのだろうと思うのですけれども、１０億円というのはちょっと考えられないような数字だというふうに私は思うので、ここはちょっと正確にしていただきたいと思います。次回のときでいいのですけれども、ここはきちんとご答弁をいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-021"},{"speaker":"つる委員","kind":"質問","question":"今、民営化の部分でかなり質疑があった中で、今最後のほうにちらっとありましたけれども、過去の質疑を見ると大体１００名定員ぐらいだと、１園当たり、ざっくり１億５,０００万円ぐらいの運営費という考え方ですかね。そうすると、国とか都の補助金をあわせると３０％で、それが来ると。だから、３分の１弱だと思うのですけれども、それぐらい来る。","respondent":"佐藤保育課長","answer":"サービス、環境、人材、特に人材の育成に関しましては、６月補正でいただきましたのびしなプロフェッショナルスクール等を創設して全力で取り組んでまいりたいと考えております。","voiceIndex":45,"id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"ちなみに、参考までに、八潮すこやか園に八潮南保育園が移転するに当たって、人数規模からすれば、若干名の定数の減なのですけれども、単独で例えば運営していたときに、１億５,０００万円ぐらいの運営費がかかるわけですが、幼保一体施設の中で一緒になることで、保育園の部分について、そういう意味での経費の削減というのは何かしら一緒の施設が一体になることで。","respondent":"吉田保育施設調整担当課長","answer":"例えばですけれども、保育園と幼稚園が一緒になったことによって、運動会だとかその他の事業とかを一緒にできる、こういったメリットが出てきます。金銭的なメリットのところにつきましては、今後検討の部分です。","voiceIndex":47,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"反対しますが、意見を一言、二言言わせてください。南ゆたか保育園、八潮南保育園、この３保育園の住所変更、また追加については可とします。しかし、今回のこの条例の一部改正は、住所変更という単純なものではありません。民営化反対、中止をこれからも求め続けていきますので、その点はしっかり言っておきたいと思います。以上、反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-024"}]},{"id":"topic-02","title":"第７６号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第７６号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"家庭的保育事業の実態を知りたいので教えていただきたいと思います。一つは、まず家庭的保育事業の事業内容をざっくりと教えていただきたいのと、事務事業概要によると給食の提供が今、２カ所書かれていて、定員が５名と３名と２カ所あるのですけれども、ここでの給食の提供が現状どうなっているのか、具体的に中身を教えてください。","respondent":"大澤保育支援課長","answer":"家庭的保育事業ですけれども、短時間認定のお子さんを対象に８時から１８時までお預かりしている施設です。給食の状況ですけれども、今２施設あるうち、１施設は自園調理となっております。もう１施設は、外部の給食事業者からの搬入という形をとっております。","voiceIndex":60,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"一つは、外部の給食事業者の搬入と言われましたけれども、どういうところから、どんな給食内容が届けられるのか、あと費用等はどうなっているのか教えてください。","respondent":"大澤保育支援課長","answer":"外部搬入ですけれども、離乳食ですとか、アレルギー対応も可能な事業者から、それに対応した内容となっております。費用につきましては、運営費の中からお支払いしているという形になります。","voiceIndex":62,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"５人とか３人とか少ないところなので、なかなか自園でやっていく自園方式というのは難しいかなとは思うのですけれども、また反対に外からこのデリケートな離乳食のようなものを持ち込むということにおいて、やはり細菌の繁殖とか衛生面においても、アレルギー対応についても問題があるのではないかなと思うのですけれども、条例は本来５年以内に自園方式にするように求めているのだと思うのですが。","respondent":"大澤保育支援課長","answer":"区としましても自園調理が原則ということは認識してございまして、そこを変えるつもりはありません。","voiceIndex":64,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"保育ママの事業者の方からなかなか管理が困難ということでということですけれども、この前の段階で５年間という経過措置はあったにしても、とにかく自園方式で安全・安心な給食を提供してほしいという思いがあったからこそ法律ができて、条例に盛り込まれたのだと思うのですね。ぜひ区が支援をして、一刻も早く実現をすべきではないかと思っていますけれども、この辺はいかがでしょうか。","respondent":"大澤保育支援課長","answer":"もう１事業者に関しましては、今のところ調理員の確保についてもなかなか困難だというような状況もありますので、５年延長して、その中で区としてもできる支援はさせていただいて、何とか平成３７年度までには自園調理ができるように支援していきたいと思います。","voiceIndex":66,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区でできる支援というのは、どんなことを考えているのですか。条例の第７条のところに、連携協力を行う保育所と書いてあるのですけれども、これはどういう意味で、どこがこれに当たるのかを教えてください。","respondent":"大澤保育支援課長","answer":"もう一つですけれども、今５年の延長をということでご要望があるのは、調理設備が事業所内に確保することが難しいことと、先ほど申し上げたように、衛生面、維持管理が給食となると厳しいですので、なかなかそこまでは手が回らないと聞いております。","voiceIndex":68,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"ぜひここはお願いしたいと思います。連携園は日ごろいろいろな面で連携して支援が何か得られているということなのか、もう少しその中身を教えてください。","respondent":"大澤保育支援課長","answer":"連携園につきましては、家庭的保育事業が例えばお休みのときに区立園で預かるとか、そのような連携をしております。３歳以降に入る園を既に決めておりますので、卒園後はそちらの連携園で受け入れるという形になってあります。","voiceIndex":70,"id":"exchange-030"},{"speaker":"南委員","kind":"確認","question":"当面、平成２７年度から５年ということで始まったわけですけれども、この期間、品川区として外部より搬入している、そういう保育園に対して自園方式に転換していきましょうという働きかけはしてきたのかどうかの確認をしたいと思っているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-031"},{"speaker":"南委員","kind":"確認","question":"だから、この５年間品川区としてはずっと働きかけをしてきたかどうか、そこのところを一番確認したいと思っているので、今のご答弁では働きかけはしてきているようにも受け取られたのですけれども、ちょっと明確にしたいと考えていますので、もう一度お願いします。","respondent":"大澤保育支援課長","answer":"働きかけというのは具体的にどういうことか、ちょっと今明確になっていないのですけれども、自園調理をしていただきたいということでお願いはしてきておりますが、まだ経過措置の最中ですので、無理やり、強制的にすぐにやるようにというふうには働きかけてはおりません。","voiceIndex":77,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"意見","question":"反対します。自園方式が一番ということで、基本には据えていますけれども、経過措置があるからといって待つのではなく、やはり一刻も早く区が独自で支援して早急に実現すべきであると思っています。先延ばしは許されないと思いますので、反対をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-033"}]},{"id":"topic-03","title":"第７７号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例","agenda":"第７７号議案、品川区私立認定こども園、私立幼稚園および特定地域型保育事業の利用者負担額に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"この改正の根拠、国のところなのですけれども、わかったら教えていただきたいのと、なぜ第３階層の(1)、(2)が該当になるのか、ここだけなのかというのを教えてください。今区外の支援制度の第３階層の方が対象となりますというご説明だったのですけれども、何人くらいいらっしゃるのか教えてください。","respondent":"大澤保育支援課長","answer":"国の政令の公布の日付につきましては、今正確な日付がわかりかねます。申しわけありません。国の改正の趣旨としましては、低所得世帯の経済的負担軽減を図るためとなっていますので、第３階層が対象となっています。区内に今のところ５名対象者がいらっしゃいます。","voiceIndex":92,"id":"exchange-034"}]},{"id":"topic-04","title":"第８０号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第８０号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"１点だけ。２の主な改正内容のところについて、「主な」とついているのですが、中身的には政令の介護補償の限度額に準じて改正ということで、この額の変更のみなのかどうか、その１点だけお願いします。","respondent":"篠田学務課長","answer":"今回の改正内容は、それぞれ記載されておりますとおり支給限度額の改正です。","voiceIndex":106,"id":"exchange-035"}]},{"id":"topic-05","title":"第７４号議案、平成３０年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第７４号議案、平成３０年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"ここに示された電気設備工事設計委託のところでは、小学校１９校、中学校６校になっていますが、学校名を確認したいなと思うのです。時間の関係もあるのであれですけれども、先ほど申し上げたように、これからのところについて何校かということを伺いたいのと、工事の実施はいつごろから行われて、どういうふうになっていくのかという説明がないので、そこは教えていただきたいと思います。病児保育が。","respondent":"有馬庶務課長、佐藤保育課長","answer":"それからいつから工事かということですけれども、できるだけ早期にということですが、具体的には次年度予算の編成の中と、今この補正予算である調査結果、これらを踏まえて検討していきたいというふうに思っているところです。一方、公立保育園の保育士の一定負担にもなっているという部分もあり、区民の方のニーズも確実に病児保育室のほうに向いていますので、病後児保育室は徐々に狭めていく、縮小していく方向で検討したいと考えております。","voiceIndex":122,"id":"exchange-036"},{"speaker":"南委員","kind":"確認","question":"議事録を確認しないで来てしまったので申しわけないのですけれども、前回のたしか、おおしまこどもクリニックの６月の補正の最後に主張したのですけれども、保育士がなかなか休めないという現状の中で、やはり保育士も自分の子どもの具合が悪いときにきちんと休めるような、そういう状況を確保していかないと。","respondent":"有馬庶務課長、佐藤保育課長","answer":"工事するのは全ての学校ですので、この下のほうに書いてある設置の検討委託経費というほうにも、改築が済んでいる学校もあわせて検討はしていくということで、全校をやっていくという基本姿勢です。１点目の施設数は幾つぐらいつくるのかというところで、あくまで８００ぐらい受け入れられる施設であれば３つということで、定員によって受け入れられる人数が違いますので、一概に３施設、４施設というのは今現在は言えないところと。","voiceIndex":125,"id":"exchange-037"},{"speaker":"南委員","kind":"質問・要望","question":"職員配置も含めてちゃんととっていただくということが区の責任だと思いますので、そこは強く強調したいと思います。できるだけ第１回目のグループ、第２回目のグループというふうにしないで、来年の夏に間に合うような、そういう対応をしていただきたいというふうに思っています。そういうふうに受けとめていいのかどうかというのを確認して終わりたいと思います。","respondent":"有馬庶務課長","answer":"できるだけ早目にということでは考えておりますけれども、現実問題としてもある程度設備、設計して機械を入れるということですので、せっかく補正予算も組んでいますので何校かは夏に間に合わせたいなとは思っていますが。","voiceIndex":128,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"補正予算書の１７ページのところに、病児保育施設開設経費助成と書いてあるので、この助成の中身とか割合を教えていただきたいのが１点です。","respondent":"佐藤保育課長","answer":"２点目の病後児保育と病児保育の線引きの部分ですけれども、病後児保育は病気が治った回復期に、回復しているにもかかわらず集団保育が難しいと判断した場合にお預かりする施設でございまして、病児保育に関しましては、重症ではないけれども。","voiceIndex":131,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問","question":"親の思いからすると、なかなかそこは難しくて、骨折とか、そういうのだとわかるのですけれども、病状がどういう段階にあるのかという判断はなかなか難しいと思うのですよね。その辺はどこで判断するのか、親の立場からすると、医師がすぐそばにいる病児保育のほうが安心かなという気がするのですが、その線引き等はどなたが判断するのかというあたりを教えてください。","respondent":"佐藤保育課長","answer":"その辺が１点目で強いところでございまして、委員のご指摘は、電話で事前に各保育園に病後児保育を受けたいと相談した場合のご心配だと思うのですけれども、そこはまさにちょっと保育士のほうで説明がなかなか行き届かなくて誤解を受けたりする問題もありますので。","voiceIndex":133,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問","question":"熱があるか、これははっきりしていると思って、医師にかかるということが前提ということですか、医師にかかった場合に、何か証明とかが必要なのですよね。それにはお金がかるのか、かからないのか、面倒ではないのか等教えてください。","respondent":"佐藤保育課長","answer":"病児保育の児童連絡票の関係ですが、医師会のほうにお願いして、無料で出していただいているところです。","voiceIndex":135,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"意見","question":"学校の空調の設備なのですけれども、１校およそ幾らぐらいで設計段階から設置までかかるのかというのと、先ほど早期にという願いに対して、来年の夏はちょっと難しい、でもなるべく早くとのことですが、その辺のめどがどのくらいなのかというところ、あともう一点は、避難所の機能としてもすごく期待をされるわけですけれども、やはり心配されるのが電源の問題なので、その辺をどう考えていくのか。","respondent":"有馬庶務課長","answer":"通常あるものは、やはり夜間でも避難所のトイレに行ける照明等にも使っていかなければいけないので、それを全部振り分けてクーラーに使っていくというのは、現状では難しいのではないかなというふうに考えております。","voiceIndex":137,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"新たに冷暖房、空調設備が全学校の体育館につくというのは本当にうれしいことですし、避難所の環境改善にも大いに役立つのでうれしく思っています。電源確保の問題はさまざまな検討が必要かと思います。この間の本会議場でも自然エネルギーの活用とか、いろいろ出されていたので、本当にせっかくついた空調が稼働できるような電源の確保を考えていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-043"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"学校の屋内運動場等についてですが、我々もかねてからこの要望をずっとしてきて、実現に向かって動き出したのは大歓迎をしますが、一方で、今改築をしているところについて、いわゆる３、経費内訳の(1)の部分ですけれども、もし仮に改築をする段階で体育館に空調設備を入れるということを計画していたら、どれだけ今記載されている経費よりも削減ができたのか、まず１点教えていただきたいです。","respondent":"有馬庶務課長","answer":"３、経費内訳の(1)、上のほうからの電気設備と設置検討の絡みですけれども、基本的にこれは対象の学校が異なっていまして、電気設備工事というのは、まだ改築が終わっていない学校を対象としておりまして、今持っている電源設備、いわゆるキュービクル。","voiceIndex":140,"id":"exchange-044"},{"speaker":"石田（し）委員","kind":"確認","question":"設計委託の件ですけれども、いわゆる３の(1)の1)に関しては、古い学校で全体的なものをまず調査をかけないとわからないということですよね。3)は一定改築等がされていて、配管とかはある程度準備はしているけれども、何方式にするかというのを検討するということですよね。３段階あるということでいいのか、確認をさせてください。","respondent":"有馬庶務課長","answer":"設置検討した後、実施設計工事というふうに進むのかというところですけれども、現状からいけばそういうふうな形で進みます。","voiceIndex":142,"id":"exchange-045"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"やはりそこはできる限り未来を見据えたもの、可能な部分についてで、想定外の話は別ですけれども、例えばインターネット関係にしても、高齢者施設でインターネットの回線をつくらず、そのまま工事をしたというのが以前ほかのところの施設であって、今後絶対必要となっていくのに、それを見据えないで工事設計をしているなどというのはおかしい話ですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"学校屋内運動場について予算書を見ると、一般財源になっているのですけれども、国と都の補助金のところが今後どうなるのか、どうしていくのか教えてください。","respondent":"有馬庶務課長","answer":"体育館については今後どうなるのか様子を見ていきたいと思っています。東京都のほうについては、はっきりと屋内運動場についての補助金を計画しているという情報が来ておりますので、今後その概要は見ていきたいと考えています。","voiceIndex":145,"id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"質問","question":"冷暖房に関しての早急な取り組みは大変素晴らしいことだと思います。改築工事進行中の小学校でこの数字に出てきているのは３校ですね、鮫浜小学校と浜川小学校と第四日野小学校は改築に向け計画中ということなので、1)の芳水小学校的な予算の流れで、つまり改修が終わったときには何校か、芳水小学校のように入るという考え方でよろしいのでしょうか。","respondent":"有馬庶務課長","answer":"今そのほかに改築をしています浜川小学校、鮫浜小学校、これから行います第四日野小学校等につきましては、これから実施設計の段階で、体育館がいつまで使えるのかというところも見据えながらという形になります。","voiceIndex":147,"id":"exchange-048"},{"speaker":"つる委員","kind":"提案","question":"一般質問でも私どもの会派から屋内運動場についての空調設備設置についてはさせていただいたので、そこでの質疑も伺っているところでありますけれども、先ほど予算といいますか補助金等の話もあって、一応東京都からは一般質問でお伝えしましたが、都議会の公明党の代表質問で提案して、区市町を支援する、さらにあわせて、重ねて知事が直接受け取って、緊急要望ということで。","respondent":"有馬庶務課長","answer":"１点目の補助金の関係ですけれども、東京都のほうからも実際現状の考え方といいますか、そんな調査も来ましたので、そういったものにもしっかり回答して、補助制度活用に向けて努力してまいりたいと考えています。","voiceIndex":150,"id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"今回の場合、東京都に、都知事にも要望したのは、冷房だけではなくて、あくまでも冷暖房ということで、公明党としてはしっかりと明確に、小池知事に直接行って、そこでもしっかりお願いしますと言っております。１点、先ほど既に現在もというところで、戸越台中学校に設置されていると伺ったので、参考に利用状況というのでしょうか、夏、冬、教えていただければと思います。","respondent":"有馬庶務課長","answer":"基本的に何度になったら何というふうに決まりがあるのかはちょっと正式にはわかりませんけれども、夏場、冬場、セントラル方式になっており、スイッチを入れれば使えるという状況になっておりますので。","voiceIndex":152,"id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"この辺、既存の学校によって、さっき石田しんご委員のほうからもあったいろいろな学校の、また体育館の状況に応じて、３の(1)の1)、2)、3)にあるような形で対応が出てきてしまうというところがあるので、どんな形であれ、再三言っているように来年の夏に間に合うような形でというのを求めなければいけないところなのですが、事前にいろいろ確認させていただいた中では、現在の体育館、いわゆる別棟。","respondent":"有馬庶務課長","answer":"光熱水費抑制という面からも直していくときにはきちんと対応していきたいというふうに思っております。","voiceIndex":154,"id":"exchange-051"},{"speaker":"つる委員","kind":"確認","question":"最後に、１点だけ、２の導入効果の３点目のところに、一般開放における区民スポーツ活動の促進とあるのですね。学校の中でどこをそうするのかは、私も全部確認できているわけではないのですが、そういうしつらえがあるところ、ないしそれに当てているところへの冷暖房設備、このあたりの考え方はいかがでしょうか。","respondent":"有馬庶務課長","answer":"今どの学校の体育館のそばに更衣室が、幾つあるかというのはわかりませんけれども、体育館が入って、そこの更衣室もということは当然要望も出てくるかと思います。例えば個別空調で対応できるものなのか、その一体の中でできるものなのか、あわせて検討していきたいと思います。","voiceIndex":156,"id":"exchange-052"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひそういったところも細かい配慮になると思いますので、今回の議案は屋内体育館ということでのご説明でしたが、あわせてそこも全体の中でぜひ積極的に検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-053"}]},{"id":"topic-06","title":"平成３０年陳情第１８号、認可外を含む私立保育所職員に対する品川区独自の処遇改善を求める陳情","agenda":"平成３０年陳情第１８号、認可外を含む私立保育所職員に対する品川区独自の処遇改善を求める陳情","exchanges":[{"speaker":"南委員","kind":"質問","question":"今品川区内の区立の保育園は別として、私立の認可保育園、とりわけ新しくできた保育園のいわゆる賃金に関する処遇についてはどのようになっているか、改めてどう認識しているかを伺いたいと思います。とりわけ初任給がどうなのか、３年、５年経過して、その賃金はどのように推移しているのか、具体的な状況をつかんでいたら教えてください。","respondent":"大澤保育支援課長","answer":"今年の４月は２０万円から２３万円が初任給の額、来年の４月は今のところ２０万５,０００円から２３万５,０００円で、大体どこも５,０００円程度のアップはしているような状況です。","voiceIndex":173,"id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"こういう状況、今数字を示していただいたのですけれども、一般の働く人たちとの賃金との関係で見ると、高いといっていいのか、低いのか、その辺の状況も教えていただきたいと思います。区立で働いていただいている職員の皆さんの状況とも比較をすると、どういうふうに見ているのか、その辺も教えてください。","respondent":"大澤保育支援課長","answer":"先ほど申し上げましたように、５割以上が３５０万円の収入になっておりますので、ほぼ同じような状況ではないかというふうに考えております。","voiceIndex":175,"id":"exchange-055"},{"speaker":"南委員","kind":"質問","question":"そうしますと、一番最初に説明していただいた５割以上が３５０万円以上になっていると、こういうことですが、短大卒という３０歳から３４歳の、ここと比較して、３５０万円以上というこの方々の年齢というのは、短大卒の３０歳から３４歳というここの年齢とほぼ同じで見ていいということなのでしょうか。","respondent":"大澤保育支援課長","answer":"今持っているのが平成２８年度の状況ですけれども、保育士の平均年齢が３４歳、平均経験年数が５.５年ですので、ほぼ同じような状況ではないかというふうに考えております。","voiceIndex":177,"id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"以前、直接保育支援課にお問い合わせさせていただいたときに、初任給は比較的高く募集して、そして数年経過すると、初任給のときは高かったけれども、伸びる率がずっと少なくなって、むしろ額が低くなっているというふうに説明していただいたのを記憶しているのですけれども、そういう状況ではなくなっているという認識でいいのかどうか、改めてそこを伺っておきたいと思います。","respondent":"大澤保育支援課長","answer":"数年たってから差が出るというのは、多分区の職員との差のことをおっしゃっているのかというふうに認識しておりますけれども、今保育士、私立は新しい園ができている関係で、かなり若い方が多いため、単純な比較はできないかと思いますが。","voiceIndex":179,"id":"exchange-057"},{"speaker":"南委員","kind":"質問","question":"この辺のとりわけ３歳児が２０対１のところを１５対１に区が加算しているという、そこのところの区の考え方について、また看護師を０歳に入れている、加配が必要だということの認識でこういう対応をしているということだというふうに私は理解するのですけれども、この辺についての加配の考え方、なぜここに加配をしているのか、それについて伺いたいと思います。","respondent":"大澤保育支援課長","answer":"加算ですけれども、０歳児園への看護師配置、また３歳児への１５対１の配置加算については、やはり保育の質という面で区の考え方をあらわしています。","voiceIndex":181,"id":"exchange-058"},{"speaker":"南委員","kind":"質問・要望","question":"確か１年前のときにも１歳児を６対１ですけれども、４対１に引き上げてほしいと、そういう趣旨の陳情が出されたというふうに記憶しているのですが、私は本当にそういうことで底上げをしていく、一人ひとりの子どもをしっかり捉えて、信頼関係をもって、その子の要求が受けとめられる、そのことによってほかの子どもとのかかわりができる、いろいろな遊びに展開していけると。","respondent":"大澤保育支援課長","answer":"最初に国の処遇改善ですけれども、勤続年数によって違うことについては、３年以上とか７年以上ということで、なるべく長く働いていただきたいという思いもあって設定しているものだというふうに認識しています。","voiceIndex":183,"id":"exchange-059"},{"speaker":"南委員","kind":"意見","question":"トイレに行けない状況、とんでもないことだと思いますよね。そういう自然生理現象に対してきちんと要求が満たされないような職場なんていうのはとんでもないことだというふうに思います。そういう状況、発言は非常に残念ですし、そういうこと自体が異常なわけです。だから、引き上げをしてほしいというのは当然の要求だというふうに思います。きちんとした底上げが必要だということを強調したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":185,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど課長からご説明いただいて、区の個別の調査をしたら、５割以上が年収３５０万円以上であったという報告があったのですが、この調査というのはどこの部分までだったのか、今日出されている陳情は認可外を含め、私立保育園職員に対する処遇改善を求めているのですが、区が行った調査というのは、認可外とか認証とか、その他のところも含まれているのかどうか、それを１点教えていただきたいのと、冒頭。","respondent":"大澤保育支援課長","answer":"区の調査は、私立認可保育園の給与の調査です。平成２９年度は上がった額としては、平均ですけれども、６万６,０００円の見込みとなります。","voiceIndex":186,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"私立認可保育園で平均６万６,０００円の見込みだったということなのですけれども、認可外とか、認可以外のところは調べられていないのでしょうか。今日訴えていらっしゃる方の中には、結構認可外とか認証とかで働いている方がたくさんいらっしゃるところでの訴えなのです。","respondent":"大澤保育支援課長","answer":"給与の話ですけれども、認可保育園は公定価格として区が出している部分とキャリアアップも区を通して出しているので、一人ひとりの給与を報告していただくことはできますけれども、認可外については給与についての補助金を出していませんので。","voiceIndex":188,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今のところで、研修を受けなくても７割の園で出ているということですが、３割というのはなぜ受けていないのか、何か障害があるのかどうか、ちょっとそこを教えていただきたいのが１点です。保育士の配置基準のところなのですか、これによると３歳児、１５対１というふうに基準でなっているのですけれども、２０対１が１５対１に変わったのではなかったですかね。","respondent":"大澤保育支援課長","answer":"処遇改善IIというのがいわゆるキャリアアップの国の部分の加算ですけれども、行っていない園はやはり園の中で配分するのが難しいという理由で実施していませんが、平成３０年度はその配分についてかなり緩やかになって、園の中の３分の１の人しかだめであるとか。","voiceIndex":190,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問・要望","question":"５人を１人では絶対見られないというところにおいて、やはりこの基準をどうしていくのかというのが保育の質を上げていくまず第一であろうなと、保育士の目が届く、一人ひとりの気持ちがくみ取れるような保育をしていくためには、ここに例えば５対１と書いてありますけれども、６対１が戦後ずっと続いているこの基準を国にも求めなければいけないし、国が変えないのだったら。","respondent":"大澤保育支援課長","answer":"４歳児で一番今多い園が２４名ですけれども、担任は２４人に対して常勤２名と非常勤１名の３人で担当しております。国基準の３０対１では確かにきついという認識はありますので、それ以上の配置はしているところを確認しております。","voiceIndex":192,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問","question":"国基準というのは、これをベースにして公定価格で人件費などが払われているということになっていくのですが、今、看護師加配とおっしゃったけれども、品川区は看護師が配置されている分、保育士と置きかわっているのではないですか。昔は保育士がちゃんと３対１で配置されて、プラス看護師がいたのですが、そういうところが少しずつ削られて加配になっていない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":194,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、国基準が不十分なので、地方自治体に対して、品川区に対してもっと引き上げてほしいと求めているというところを……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"はい、ぜひぜひ受けとめていただきたいと思います。やはりフランスなど、よその国の例などにぜひ目を向けていただきたいし、保育者の悲願なのですよね。それを保育課自体が受けとめられないということ自体が、変わっていかない大きな原因ではないかなと思っています。職員の声というのはどういうふうに受けとめているのか、最後に伺います。","respondent":"大澤保育支援課長","answer":"看護師は保育士のカウントに入れていません。１歳児は１対５、３歳児は１対１５で基準をつくって運営しております。","voiceIndex":198,"id":"exchange-067"},{"speaker":"つる委員","kind":"質問・要望","question":"平均でどのぐらい上がっているのかという先ほどの質疑の中で、６万６,０００円と、どこを基準にするかだと思うのですけれども、昨年は７万４,０００円が平均ですというご答弁があったのですが、ちょっとその数字だけ確認させていただきたいと思います。","respondent":"大澤保育支援課長","answer":"平成２９年度については、６万６,０００円の見込みですけれども、まだ平成２９年度の集計が終わっていませんので、結果として幾らになるかについては今集計中です。","voiceIndex":200,"id":"exchange-068"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう機会があるかどうかはあれですけれども、こうした質疑の中でもそれがわかった段階でまたある程度教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":202,"id":"exchange-069"},{"speaker":"石田（し）委員","kind":"質問","question":"賃金に関してはもちろん区独自でやるという視点もなくはないですが、やはり待機児童対策も含めて考えた場合には、国レベル、東京都レベルである程度広域的に取り組んでいかなければいけない課題かなという中で、区として先ほどからのご説明で国、また東京都のさまざまな改善策、制度を使ってこれまで賃金アップに取り組んでおられるということでしたが、区として。","respondent":"大澤保育支援課長","answer":"都で待機児童対策協議会等がありますので、そういう場面で意見として出していくことはしております。特に処遇改善IIの研修については、必須だとなかなか難しいということで、それは各自治体から出た意見をもとに平成３４年まで延長されたです。","voiceIndex":203,"id":"exchange-070"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いわゆる離職率が高い中で、何とかそのまま継続して、保育士として働けるような環境をつくろうということで、さまざまな加算、また制度がつくられていると思うのですが、実際ここ数年こういった改善、いわゆる賃金の中で改善がされている中で、保育士のいわゆる離職というのがどういうような傾向に来ていて、今後どのようになる見通しを区が持っているのか教えてください。","respondent":"大澤保育支援課長","answer":"そういう意味で、離職、園を変わるという意味では、少しこれからの競争の中で、もしかすると高くなってくる可能性があるのではないかというふうに考えています。","voiceIndex":205,"id":"exchange-071"},{"speaker":"渡部委員","kind":"質問・要望","question":"本日結論を出して、不採択にしたいと思います。この１時間の議論の中でさまざまな話を聞かせていただきました。そのような感じで、賃金等に関しても上がってきておりますし、制度に対しましてもそれぞれ国基準プラスアルファをなされているわけですから、引き続きこのまま続けていただきたいと思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-072"},{"speaker":"つる委員","kind":"質問・要望","question":"理由は、先ほど質疑をさせていただきましたことと、また、ほかの委員からの質疑も確認させていただいて、昨年の議論を参考にしながら、渡部委員のほうからもありましたけれども、答弁にもあったとおり、事業者のほうから、例えば当然保育士一人ひとりの処遇を改善してあげたいという強い思いは何度も伺ったこともありますし、逆に保育士からも処遇を改善してほしいという声もありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":210,"id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日結論を出すということで、採択を主張したいと思います。タイトルにありますように、この陳情は、認可外を含む私立保育所職員に対する品川区独自の処遇改善を求める陳情ということで、今日の説明からすると、認可外を含めた職員に対する処遇というのはまだまだ不十分ですし、報道で取り上げられたり、報告にあるほどの額が手元に行っていないということがここにしっかり書かれています。それが１点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":211,"id":"exchange-074"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"しかし、一方で、先ほど質疑の中でもお伝えしましたが、これは区独自のもの、また東京都、国、そういった広域でやらなければいけない課題というのは、しっかり分けて、区でできることはもちろん全力で取り組んでいただきたいのですが、東京都や国に関しては、しっかり区が持っているノウハウや知識をぜひ届けていただいて、全体でさらに改善ができるように、その辺はお願いしたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-075"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そこのところで、区としての役割はそういった声を上げていく、また実効的であるかどうか、一番身近なところですのでチェックを今後もしていただくというような立場であるかと思います。区独自の加配や先ほどの看護師のお話ですが、そちらは区としてできることは進めているということですので、その点についても常に検証して、今後に向けて努力は続けていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-076"}]},{"id":"topic-07","title":"平成３０年陳情第１９号、「（仮称）空のはねこども園はたのだい」（旗の台２丁目）の事業者指導等を求める陳情","agenda":"平成３０年陳情第１９号、「（仮称）空のはねこども園はたのだい」（旗の台２丁目）の事業者指導等を求める陳情","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そのとおりだなというふうに思っているのですが、こういうことについては、書面をもって対面で説明をしているというふうな説明だったのですけれども、この私道について、とりわけ私道のところを一つだけ取り上げるのですけれども、どういうふうに区として説明をしてこられたのか、世田谷区のような認識でいるだろうというふうには思っているのですけれども、それについてどうなっているのかを１点。","respondent":"大澤保育支援課長","answer":"事業者からは現在も承諾していただけるように個別に訪問している旨の報告を受けております。先ほどご紹介いたしました保育所を開設するにあたってという事業者への書面については、私道の持ち主に文書で許可を得る必要があるというふうに明記して説明をしているところです。","voiceIndex":221,"id":"exchange-077"},{"speaker":"南委員","kind":"質問","question":"そういう点で説明もしていると、事業者はそれについてどのような対応をこの間にしてきているのか。それについて教えてください。","respondent":"大澤保育支援課長","answer":"しかしながら、それ以外の部分についても承諾を得るよう区としては依頼しておりますので、事業者のほうは今努力をしているというふうに報告を受けております。","voiceIndex":223,"id":"exchange-078"},{"speaker":"南委員","kind":"質問","question":"北と南だと思うのですけれども、そこが私道だということで、もう一方の側は集合住宅と隣接をしているということで、非常に今までにないような地形にあるということで大変心配しておられるわけですけれども、この点、こういう形で似たような地形のところに開設された保育所があるのかどうかを聞いたのですけれども、その点についてはどうだったでしょうか。","respondent":"大澤保育支援課長","answer":"その片方が私道でございまして、そちらに公園から５ｍに満たないぐらい私道を通って保育園の出入口があるというような設計になっています。私道を避難経路として設定している園はほかにもございまして、そのときにも承諾書をとっていただいています。","voiceIndex":225,"id":"exchange-079"},{"speaker":"南委員","kind":"質問","question":"私が先ほど説明したようなこういう地形、隣がこうなっているという、そういうところで、同じような状況で保育園をつくっているところがあるという認識でいいのでしょうか。","respondent":"大澤保育支援課長","answer":"同じようなというのは、公園があって、私道があってという意味ではございません。避難経路として私道を使用しているところはあります。","voiceIndex":227,"id":"exchange-080"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、園庭もない、遊戯室もない、廊下もなくて、年齢ごとの保育室が配置されている、しかもあの周辺は私道である、こういう保育園について品川区としてもう少しきちんとした形で保育園のあり方というところの考え方を、待機児童が少ない中で保育園ができることは私もそれは受けとめていきたいとは思ってはいますけれども、つくるのであれば、やはりお隣、ご近所から理解される。","respondent":"大澤保育支援課長","answer":"区といたしましては、保育事業者が近隣要望を勘案して定員削減をしたこと、また一方で、区は集団保育の重要性や入園を希望される区民の方が多数いることから、認可保育所の定員は６０名を基本としておりますので。","voiceIndex":229,"id":"exchange-081"},{"speaker":"南委員","kind":"質問・要望","question":"当面２年間は４０名でいくということで、それで品川区の基準が６０名定員というふうなことなのですけれども、これはやはり園とか、その地域の状況とか、立地条件とか、そういうことを勘案して、６０名というところにこだわる必要はないのではないかなと思うのですけれども、６０名としている、その根拠というのはどういうことなのか、改めて伺いたいです。","respondent":"大澤保育支援課長","answer":"認可の平面図に関しましては、認可基準に則していれば、区としてその平面図がいけない等というような権限はございませんし、特にこの園がほかと比べて著しく劣っている配置図になっているというふうには認識してございません。","voiceIndex":231,"id":"exchange-082"},{"speaker":"南委員","kind":"質問・要望","question":"そちらから申し出たらということだけではなくて、地域の皆さんのご意見、ご要望を受けとめた形で区として健全な保育を進めていくというところの意見を事業者にお伝えいただくということがとりわけ必要なのではないかというふうに思うので、最後にそこだけ伺って、とりあえずこの関係での質問は、今は終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":233,"id":"exchange-083"},{"speaker":"南委員","kind":"質問","question":"さっきも申し上げているのですけれども、２階のところを例に挙げて言いました。１歳児室の平米数が有効面積として５９.３５m2、そして２歳児、３歳児が同じ平面図のところに２歳児、３歳児となっていまして、有効面積が５８.２４m2で、ほぼ２階の面積の半分を分割して１歳児、２・３歳児となっているのです。ですから、それぞれ出入りをするときに、それぞれの保育室を通っていかないといけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":235,"id":"exchange-084"},{"speaker":"南委員","kind":"質問・要望","question":"指導として、それが必要だと思うのです。そういう点で何回も繰り返しこの問題について質問をしているわけですが、必要ないというふうな、そういう考え方というのはいかがなものかということで、私はぜひそこは考えていただいて、保育の内容についてきちんと大事にしていただける、そういう立場で指導をしていただきたいと考えています。答弁が同じであれば、それはそれでいいですけども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":240,"id":"exchange-085"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区がどうして早い段階でこの計画をとめるような助言ができなかったのか、私は最初の入り口のところがきちんとできなかったために、こうやって地域の住民の方と保育事業者のトラブルといったらいいのですかね、住民の方にとっては青天の霹靂というか、降って湧いた災難というか、本当に知らないままにどんどん進められ、気がついたときに意見を言っても、どこも取り上げてくれなかったという。","respondent":"大澤保育支援課長","answer":"認可基準を満たしている申請が行われましたら、認可しなければいけない、東京都もそういうことになっておりますし、区市町村としても待機児童がいる以上、基本的な要件を満たしている限り提案を受け付けなければいけないということになっておりますので。","voiceIndex":244,"id":"exchange-086"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そこのところが多分違うのであろうなと思います。品川区も募集要項がありますよね。世田谷区と中野区の例が出ていましたけれども、その募集要項に一つひとつ、周辺住民に対する対応とか近隣とうまく物事を進めていく上でのことがきちんと書かれているのですよね。あくまでも民と民の問題だというよりも、品川区の責任であると重く受けとめていただきたいのですが、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"保育所整備に関しましては、品川区においてもきちんと責任を持って住民に説明してくださいということは書面をもって、また対面でご説明をしているところです。","voiceIndex":246,"id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それを誰の責任にするのですか。区は責任がないと言えるのでしょうか。私はこれだけでなく、これからも起こってくると思うのです。これ、事実に反していませんか。こういったことで、住民が知らない間にどんどん進んでいる、これってないのではないでしょうか。私はとんでもないことだと思うのですが、事業者参入のときの手続の手順と区がどうかかわってきたのか、今の部分を教えてください。","respondent":"大澤保育支援課長","answer":"時系列で申し上げますと、９月の頭には保育園の開設について町会長のほうに事業者からお話をしています。同時期に、近隣住民の方に建設のお知らせを投函しています。１１月になってから具体的に説明会開催について周知をしたところです。","voiceIndex":248,"id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問","question":"私が時系列的に言ったあたりで、住民の方が知らない間に区から都にいろいろ申請とか協議書が提出されているという問題は、事実と違うと思うのですが、この件に関してはどうでしょうか。","respondent":"大澤保育支援課長","answer":"９月に建設のお知らせについては投函していますので、時期としてずれてはいないというふうに認識しています。","voiceIndex":250,"id":"exchange-089"},{"speaker":"飯沼委員","kind":"質問","question":"何枚チラシが、どこの地域に入ったかわかりませんけれども、そうやってチラシを配布しましたというので、それで、これ、保育所の説明会を実施するほか、近隣住民の理解を得る努力を適切に行っている、または行う予定と、これで次の段階に行くのですかね。課長、ちょっとここのところ、事実をきちんと把握しているのかどうか、これは住民の方が怒るのは当然だと私は思うのですけれども、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"説明会と意見交換会については、それぞれ４回、３回と実施しておりますので、特に事実に反しているというふうに認識してはございません。","voiceIndex":252,"id":"exchange-090"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この４回の説明会というのは、多分一方的な説明、打ち切られたり、１月に入って行われた部分で、決裂していたりとか、そういう中身であるので、やはりそれをやったという実績にしてしまうというのはおかしいし、私が言っているのは、住民説明会前の区の手続なのですよ。私はこれを課長に認めていただきたいと思うのですが、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"申しわけありません、質問の意図がよくわからなかったのですけれども、説明会をする予定も含まれているはずなので、きちんと説明会をするという報告を受けて、説明会を実際にしていますので、何をもって違っていると言われているのか、ちょっとよくわからないので。","voiceIndex":254,"id":"exchange-091"},{"speaker":"飯沼委員","kind":"質問","question":"説明会が先にありきではないでしょうか。予定ですというところで、順調に進んでいますと区から都に報告が先に行っていること自体に問題があるのではないかと私は言っているのです。問題ではないですかね。やはり、ここのところで住民に説明がきちんとされる、話し合いがされていれば、違った部分もあるのではないでしょうか。私が言っていること、おかしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":259,"id":"exchange-092"},{"speaker":"飯沼委員","kind":"質問・要望","question":"両者のことを一番よく知っているのは区ではないですか。世田谷区と中野区の例も紹介されましたけれども、やはりトラブルを防いでいくために、物事をスムーズに進めていくためにという意味で基準をつくってほしいとか、住民への対応のあり方、あと事業者の要件なども明記してほしいというところがありますので、ぜひ進んでいるところの中身は取り入れて改善をしていただきたいと思いますが、いかがでしょうか。","respondent":"大澤保育支援課長","answer":"多分民と民という言葉が出てきたのは、ご要望の内容によっては区の権限の範囲を超えてしまうために対応できないということについての説明や、保育事業者に何かを義務づけるにはどうしたらよいかというご質問に対し。","voiceIndex":263,"id":"exchange-093"},{"speaker":"飯沼委員","kind":"質問","question":"強制力がないからといってできないわけではなくて、強制力を持たなくても、三者の話し合いを地道に続けていく。合意のもとで行われる、事業者と住民の方をつなぐために区がしっかりと入って、三者の話し合いを続けていく、やはりこういうところをしっかりとお約束をしていただくことで住民の方がこれから本当に一緒にやっていくという立場に立てるのだと思うのですね。その辺はいかがでしょうか。","respondent":"大澤保育支援課長","answer":"繰り返しになりますが、要望については、今までも事業者に検討を促してまいりましたし、今後もそれは続けてまいります。","voiceIndex":265,"id":"exchange-094"},{"speaker":"飯沼委員","kind":"質問・要望","question":"よその優れた部分は品川区の要項にも取り入れてほしいということに対してぜひお答えをしていただきたいのと、あと最後に定員のことなのですけれども、私は６０人にこだわる必要はないと思います。でも、ここに書かれている５０人が適切かどうかという判断材料はちょっと持っていません。０歳から１・２歳までは２０人以上、でも、広げた場合は、４５人以上は確保できる面積、建物にしてほしい。","respondent":"大澤保育支援課長","answer":"ただ、他区の先行事例でよいところがあれば、それを受け入れる準備はもちろんありますし、今後は認可そのものが区が認可をすることに、４年たつとそうなってきますので、そういうときにはさまざまな事例を研究して。","voiceIndex":267,"id":"exchange-095"},{"speaker":"渡部委員","kind":"確認","question":"私道に対しても指導をなさっているということで、特段通園に対して問題はないけれども、なるべく全員の方の承諾をとってくださいというような努力をされているということですけれども、通園に支障がないという確認をとれていれば、そういうところもクリアされているのかなと思うので、クリアされていない大きな問題というのは見えないのですけれども、何なのでしょうか。","respondent":"大澤保育支援課長","answer":"合意書についても、町会のほうと合意書を締結したいということで、それは町会長からも、事業者から相談を受けている旨聞いておりますので、最終的には今定員のところかなというふうに私は認識しています。","voiceIndex":270,"id":"exchange-096"},{"speaker":"渡部委員","kind":"質問","question":"行政が中に入るという話ではなくて、しっかりと助言をいただいてということはなさっているわけですから、今まで文教委員会の中で結構さまざま入ってくるときに、いろいろな問題点というのは当然あって、多分保育園等ができていくためには、１年間のうちに何回かこの話というのはあるのかななどという気はするのですけれども、今までもそうだったのですけれども、基準に則っていて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":272,"id":"exchange-097"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点、いわゆるこの場所に保育園ができるのはどうなのかというような話が質疑の中であったのですが、近くに別の保育園がたしかあるのです。そこは特段問題がないのか、要はそのエリアだから保育園ができるのはどうなのかというようなことが質疑の中であったので、そこをまず確認させてください。","respondent":"大澤保育支援課長","answer":"今保育園は望まれていますので、一番近いところでは、同じ建物の上と下で保育園をつくったり、隣でつくったりというようなケースもあり、それでも入園の方はいらっしゃいますので、特にそこで問題があるというふうには認識しておりません。","voiceIndex":273,"id":"exchange-098"},{"speaker":"石田（し）委員","kind":"確認","question":"そこの保育所が、これができて問題があるというのではなく、そのエリアにいわゆる保育園ができるのは好ましくないというような質疑があったと思うのです。なので、その近くに実際にある保育園が何かその地域にあって、今までこの地域にあるから問題だというのがあったのかどうかというのを確認したいので、そこを改めてお答えください。","respondent":"大澤保育支援課長","answer":"地域的には何も問題ございません。","voiceIndex":275,"id":"exchange-099"},{"speaker":"石田（し）委員","kind":"意見","question":"もちろん住民の方の理解、先ほどからいろいろな方が住民の理解が必要だというのは、我々も同じ考えですけれども、ただ、いわゆる不備がない中で、住民の方の声もできる限り聞いて、何とかお互いの折り合いをつけるところをどこかで持たないと、それこそ保育事業者、運営サイドも運営サイドの思いがありますし、どうしてもそうせざるを得ない部分というのもあるのでしょうし、一方で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":277,"id":"exchange-100"},{"speaker":"渡部委員","kind":"意見","question":"結論を出して、態度については不採択です。先ほどお話しさせていただいたように、しっかり話を区としてもなさっていますし、事業者と住民の方々でさまざま、まだこれから少しお話し合いがあるのかなと思うのですが、区としては十分やるべきことはやっていると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":280,"id":"exchange-101"},{"speaker":"つる委員","kind":"質問・要望","question":"質疑も伺いました。それで、この地域性というところでも、石田しんご委員から確認があって、やはり再三申しあげるのですけれども、形として最終的にそこに保育園ができたときに、子どもたちというのは、すごく心が敏感で、保育していただいている保育士とか周りの方とかの言動というのは、子どもの発達にとって非常にセンシティブで影響が大きいのかなというのを私自身は懸念しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":281,"id":"exchange-102"},{"speaker":"南委員","kind":"質問","question":"保育園施設を迷惑施設にしてはならないし、保育する責任があるのは区ですから、やはり今後基準などもつくって、責任を果たしていくということが大事であると思っています。地域から大事にされる保育園であってほしいし、地域の住民の方々の生活も守る、この指導が大事であって、私たちは区にこういった面で今後大いに期待をしていきたいと思っています。ですから、この陳情に対しては採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":282,"id":"exchange-103"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"結論を出すで、態度としては不採択です。理由は、先ほど意見を述べさせていただいたとおりであります。ただし、区としてしっかり事業者、また住民の、地域の方たちの声を聞いていただき、できる限りいわゆる間に入って調整というのは引き続きしていただきたいというのはありますので、ここは見します。態度としては不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":283,"id":"exchange-104"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出す。今多くの議論を伺って、またこの陳情を出された方々のお考えも読ませていただきました。今区側の、事業者に対する姿勢として、事業者のほうとつないで説明をしている、あるいは住民の方のお話をつないでいるなど対応していて、今後も要望をつないでいくというお話もありました。そういった形に向かうように現状までの対応を今後も続けるとありましたので、つないでいっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-105"}]},{"id":"topic-08","title":"本定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","agenda":"本定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"５年という存続を見据えて考えていて、心配ないというご答弁をいただいたのですが、その行方がどういうことなのか、もう少しお伺いしたいなと思っています。１人でも出してはいけないと思っていますが、そのあたりで待機児童ゼロと言われている計算式のところ、何がどう取り除かれて、認可保育園の待機児童がなくなっているのかというあたりをもう少し詳しくお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":293,"id":"exchange-106"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4954#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":73457,"voices":295}},{"id":"h30-20181029-5","meetingId":"h30-cm10","date":"2018年10月29日","dateIso":"2018-10-29","committee":"総務委員会","time":"午前１０時００分～午後 ０時２２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年請願第１５号、固定資産税及び都市計画税の軽減措置の継続","agenda":"平成３０年請願第１５号、固定資産税及び都市計画税の軽減措置の継続","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"それと、この請願は、ずっと採択されてきていて、毎年、これに携わる方というのは、ぜひ次も軽減措置の継続を求める意見書を出してくれということなのですが、ここまで来れば恒久的なものにしてもいいのかなという思いで、過去の総務委員会でいつも質問をしています。なかなかその辺について品川区としてお答えはできないとは思うのですが、品川区の思いはどういうものなのかお聞かせいただきたいと思います。","respondent":"伊東税務課長","answer":"ただ、地方税法改正とかの中で、そちらである程度クリアできればいいと思うのですけれども、なかなか全国一律ということでの改正というのは難しいかなと思いますので、その中では、その時々の地価変動を都が判断して、継続、場合によっては廃止など。","voiceIndex":6,"id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今、課長から廃止という話が出ましたが、それはぜひ考えないでいただきたい。それは、先ほども申し上げたように、小規模事業者にとっては品川区、２３区全体にも言えることですが地価は高いですし、それなりに賦課される税金も多いと思いますので、この軽減措置は必要不可欠だと思っています。ぜひ強い発信力で、品川区も東京都に対して意見書を提出していただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"小規模住宅用地に対する軽減措置、小規模非住宅用地に対する減免措置、商業地等の負担水準上限引き下げ減額措置を平成３１年度以降も継続してほしいということですけれども、品川区としても東京都に対して求めていくことが必要ではないかと思うのですが、その点はいかがでしょうか。","respondent":"伊東税務課長","answer":"この話は区の方にも声が届いている状況です。機会を見まして、東京都にはお話しするということを考えておりますけれども、具体的にいつの時点で、どういう形というのは言えないところです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"東京都にお話しをするということですけれども、品川区からも、また２３区からもこういう意見が上がっているということを、東京都に伝えることは必要だと思うのですけれども、伺ったのは、品川区としても、この３つの軽減措置の継続が必要ではないかということを東京都に伝えることが必要ではないかということですので、改めていかがでしょうか。","respondent":"伊東税務課長","answer":"お話は伝えると申し上げましたけれども、もともと現状の制度では、東京都が賦課徴収する形になってありますので、こちらからというよりは、周りからのお話が東京都に集まった中で、東京都が判断されるのかなと考えております。","voiceIndex":12,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん、東京都が判断することだと思いますけれども、だからこそ品川区としても、これを継続してほしいと東京都に要望を上げる必要があると思います。この３つの軽減措置の継続というのは欠かせないと思いますので、区としても東京都にこのことを伝えていただきたいと、強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"毎年この軽減措置の継続について意見書を求める請願が出ております。地価が当時これをつくったときから比べれば、相当上がっている。その辺について、どう思われますか。意見書については毎年、こういう仕組みだから出していかなければしようがないけれども、実際、路線価が、もう倍以上になっているのではないかなと思うので本当に不思議に感じるのですが、どう思われますか。","respondent":"伊東税務課長","answer":"確かに何年たっても同じような状況が続いているのかと思いますけれども、国もそれなりに対応すると思いますが、現状ではやはり東京都が２３区の状況というところで、東京都がそれぞれ判断すると思います。","voiceIndex":16,"id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"これは東京都の話なので、確かにつらいですよね。ただ毎年こうやらなければいけないのは、何か腑に落ちないところもあるのですけれども、その都度、チャンスがあれば都に話しを持っていき、先ほどほかの委員からありましたけれども、恒久的な仕組みになればありがたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-007"},{"speaker":"中塚委員","kind":"意見","question":"第１５号、第１６号、ともに結論を出すということと、採択をして、都に意見書を提出すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-008"},{"speaker":"いながわ委員","kind":"質問・要望","question":"結論を出すということで、先ほども申し上げたように、私の思いとしては、近い将来、恒久的なものになることがよろしいのではないかなと思いますので、ぜひそういう思いの中で、しっかり東京都に意見書を出していただきたいと思います。採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-009"}]},{"id":"topic-02","title":"平成３０年陳情第１５号、正しい公文書の情報管理と開示を求める陳情","agenda":"平成３０年陳情第１５号、正しい公文書の情報管理と開示を求める陳情","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"１点目が、公文書管理という言い方が正しいのかどうか、わからないのですけれども、品川区において公文書管理は何を根拠に行っているのか。国の公文書管理法とか、法律もあろうかと思いますので、それをお伺いしたいのです。それから公文書管理に関しては、品川区における公文書管理の正しいあり方を検討する会などの審議体または会議体があるのかどうなのかを、お聞かせいただきたいと思います。","respondent":"米田総務課長","answer":"文書管理に伴う審議体というものですけれども、現状のところ、そういうものはあるものではございませんが、国から定期に通知等があったり、あるいは区内の行政において課題が生じたというときに、一定程度、私どもを中心に検討を行っていく必要があるのだろうと。","voiceIndex":34,"id":"exchange-010"},{"speaker":"いながわ委員","kind":"質問","question":"要は、「この法令をもとに品川区は文書管理をしていますよ」ということではないということでいいのでしょうか。","respondent":"米田総務課長","answer":"これは絶対的な縛りというものとは違いますが、当然その趣旨を踏まえて、活用していくべきであろうと思います。それを品川区においては文書取扱規程というものに落とし込みながら、あるいは手引等に落とし込みながら、事務を進めているものです。","voiceIndex":36,"id":"exchange-011"},{"speaker":"いながわ委員","kind":"質問・要望","question":"たしか八王子市か何かが、結構そういった会議体をつくって、いろいろ、どうあるべきかを検討されていて報告書がネット上に出ていましたけれども、もし今後いろいろな形でＩＴ化を進めていくとか、そういうことを進めるのであれば、しっかりとした会議体をつくって、その中でどういう方向性が正しいかを、ぜひいろいろ議論していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"公文書の管理は、保存の仕方と、公文書のつくり方と、両方から考えなければいけないなというのがあって、そういう意味で質問をしたのですけれども、もうちょっと文書のつくり方も品川区として、どういう形できちんとつくっていくべきかということとか、管理のあり方というのがきちんとあったほうがいいのではないかと思いました。","respondent":"米田総務課長","answer":"その中では、まだ紙決裁、紙で印鑑で押してという稟議のものは、まだ多数残っていると認識はしておりますが、起案文書の件名などについては電子化で、例えば件名だったりということについてはシステムに入れていこうという動きがありますので。","voiceIndex":40,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。例えば、きちんと公文書として残していこうというものについて、品川区全体で何かガバナンスといいますか、品川区としてはこう考えているということがあるのかどうか、それについても伺いたいのですが、いかがでしょうか。","respondent":"米田総務課長","answer":"それに付随して、対外的にお知らせしていくようなものであるとかということについては、必然的にその意思決定の中で、添付書類として発生してくるものだと考えておりますので、まずはそこのところがきちんと適正に行われているか、この辺のところが肝になるものだと思います。","voiceIndex":42,"id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。もう片方が延べ人数で出てきた。だから、どういう文書を公文書として管理していこうとしているのかということを、品川区としてどうお考えかを伺ったのです。その解決方法がＩＴ化なのかは、私にも判断がつかないのですけれども、文書管理のあり方として、品川区としてこういうふうに管理していこうというものがあるべきなのではないかなと思いますが、その辺についてはいかがでしょうか。","respondent":"米田総務課長","answer":"ただ、今お話のあったものについては、基本的には所属のほうでとり方の判断、それは、所属のほうにも文書を取り扱う担当がおりますし、あるいは部の中にもおるわけですので、もしそこの中で対応しきれないようであれば、総務部のご相談を申し上げるという形だろうと思います。","voiceIndex":44,"id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"言いたいのは、文書の抜けたものが、昨年の１２月に開示がされている。先ほども言いましたけれども、ＩＴ化で全てが解決するのかは、私にもわからないのですけれども、少なくともＩＴ化を区議会も進めておりますし、ＩＴ化は文書の管理をしやすくする手段の一つとして検討していくべきなのではないかなということで、もしできましたら、今後の方向性について一言いただきたいと思いますが、いかがでしょうか。","respondent":"米田総務課長","answer":"当然、エラーもあるので、そのエラーをどう潰していくか、あるいは対外的な所で重大な間違いというものを、どう潰していくかということは当然あるのですけれども、その辺も十分加味しつつ、ＩＴ化というものは、今までも平成１５年に導入して以来。","voiceIndex":46,"id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"意見","question":"ご説明ありがとうございました。私はＩＴ化を推し進めていくというのは、本当に重要なことだと思うのですけれども、一方で今も区がやっているような紙ベースも必要なのではないのかなと思います。ただ、他の自治体、東京都を含めてですが、どのぐらいの区がやっているのか、それから、ＩＴ化に取り組んでいる区からみて、本区は遅れているのか、どうなのかというところを聞きたいと思います。","respondent":"米田総務課長","answer":"そういった意味で、まだそう多くの自治体で、実施されているわけではないと感じているところでありますが、導入することによる課題なども含め、研究を行っていく必要はあるだろうと考えています。","voiceIndex":48,"id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１０の自治体ということで、港区とか、葛飾区とか、板橋区もやっていると思うのです。ですから、そういった要望、区民が情報を公開してくれというのは、区に寄せられているのかどうかということをお聞きしたいと思います。","respondent":"米田総務課長","answer":"今のところ、陳情の内容にあるような趣旨での声というものが聞こえてくるということではないと考えています。むしろ、お聞きするケースはほとんどないかということではありますが、その中でも、他自治体の動向等は見きわめる必要があると思います。","voiceIndex":50,"id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひほかの区の動向を見きわめながら、区としても研究をいろいろしていただきたい。これは要望であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"やりとりを聞いていまして、幾つか伺いたいのですけれども、まず区民が求めている情報や、その根拠となる公文書は、しっかり区が責任を持って示すという重要な役割があると思います。事実の確認として、先ほど、実人数と延べ人数ということで数字のとり方が異なっていたというお話がありましたけれども、なぜ区民に異なるものが示されたのか、その原因と対策についてお聞きします。","respondent":"米田総務課長","answer":"指定管理書類一式の中で抜け落ちていたというのは、完全にそれを提供するのを失念していたというところのようですので、その辺については、一定程度適切な範疇であるという認識がありながらも、漏れていたということがあるようですので、その辺については。","voiceIndex":54,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれの課でしっかり対応していくということが大事だと思いますけれども、公文書の作成や整理や保存、また区民への説明について、一体化した仕組みをつくる責任というのは、総務課が旗を振る役割があるのかなと思うのですけれども、そういう意味で公文書の取り扱いに関する各所管への指示や研修や対応というのは、総務課が所管しているのか、確認させていただきたいと思います。","respondent":"米田総務課長","answer":"確かに公文書管理法の第３４条の中に、今お話しいただいた、保有する文書の適正な管理に関しまして必要な施策を策定し、及びこれを実施するよう努めなければならないということがございまして、国の法律ではありますが。","voiceIndex":56,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"この高い志の中で文書管理を行っていく、そうした意識をそれぞれの課に根付かせていく責任が、総務課には求められていると思うのです。先ほど、ほかの自治体も見ながらいろいろ進めていきたいと、ご答弁がありましたけれども、具体的に研修やシステムの構築など、何を進めていくのか、伺いたいと思います。","respondent":"米田総務課長","answer":"ただ、万全はございませんので、その辺のところは、毎年度行っております研修、役職者向け、新任者向け、それから必要に応じて適宜、文書事務を学びたい者向けの研修であったりということを実施して、ご質問にありました公文書等の管理に関する法律の冒頭等に述べられているのは。","voiceIndex":58,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的には言いませんけれども、そういう意味では、今、体系的にできているとは言い難いと指摘をさせていただきたいと思います。ぜひ改善をしていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、今、一歩一歩徐々に公文書管理、情報開示を進めていると思いますが、私は徐々に、慎重にやっていただきたいと思います。品川区には今、公文書管理課というのは特段あるわけではないし、アメリカの事例を聞きましたら、政府において３,０００人規模で情報の管理担当者を配置していると。それが合っているのか、正確なのかどうなのか、管理する。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-024"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"結論を出すということで、今回の陳情の趣旨からいいますと、区民との情報共有が推進されますようといったことだったのですけれども、区としてもオープンデータ化などをしていますし、現在これで私は十分だと思っています。これから先はＩＴ化を加速というか、調査研究をしていただいて、前向きに検討していただきたいということで、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-025"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"今回この方は、自分が要望したことに対して、ちょっと違った文書が出てきたということとか、少し期間がかかっているということとか、そういうこともおっしゃっておられますが、そのことはそのことで、また受けとめていただいて、今後また区民の方が情報公開される文書を求められた場合には、意思の疎通をしっかり図っていただきながら、正確な文書を出していただきたいということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-026"},{"speaker":"中塚委員","kind":"意見","question":"本日結論を出すということと、私は採択でお願いしたいと思います。理由は、今回のやりとりでも、区の公文書管理はとても不十分だと思います。このことは、区政の発展のためにも、とても大事な指摘だと思いますので、採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":66,"id":"exchange-027"},{"speaker":"いながわ委員","kind":"質問・要望","question":"本日結論を出す。一方では、こういう１つのご指摘ということで受けとめるのであれば、今後こういうことがないように、窓口での説明や公文書の出し方についてのスキルアップといいますか、そういうことをしっかりやるべきではないかなというのがあります。しかしながら、ＩＴ化をするとかそういうのは、先ほどもありましたけれども、時期尚早ということで、不採択にさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-028"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですが、先ほども申し上げましたけれども、大変だと思いますが、何かいい方策、対応、施策を考えていただいて、区も少しずつ、こういうご意見に対して少しでも近づけるように、私はやっていただきたいと思います。今回に関しては、本日結論を出すということと、私はこの件に関して、今回の陳情には不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"本日結論を出すということでお願いします。先ほども質問させていただきましたけれども、一言。そうすると、団体に調査して得るものの基準が違うものを取得してしまうということ自体が、本当にそれは所管の意識の問題でありますが、それについてもＩＴ化が全てではないと思いますが、少なくともＩＴ化はその業務をやりやすくする１つの手段であると考えますと、私は採択をすべきと主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-030"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"こういう事故は、こちらの不注意もあるかもしれないですけれども、向こう側の不注意もある。ただ、それは、なかなかその場で、どう判断するか難しいと思います。そういうことも今後考えていただければと思います。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-031"},{"speaker":"いながわ委員","kind":"意見","question":"資料に自動二輪車と書いてあるのですけれども、品川区役所の施設整備課が所有している自動二輪車、原動機付自転車ではなく、自動二輪車を所有しているのかどうなのか。通常であれば保険を使用するわけであって、保険を使用するのであれば、次の掛金は多分、多少上がるのか、それとも企業同士で契約すると、そういうのは全くないのかどうなのかだけを、詳しくではなくていいので、お願いします。","respondent":"小林施設整備課長","answer":"自動二輪につきましては、おっしゃるとおり自動二輪車でございまして、施設整備課が所有しているものです。全額保険にて出捐していますが、自動二輪車については区施設営繕事務費で処理しております。","voiceIndex":77,"id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問・要望","question":"自転車にも毎日乗っていますけれども、注意をして、事故を起こさないように、もちろん努力もしていかなければいけないし、横断歩道に人がいれば、絶対停車するし、そういう思いで運転する人間というのはやっていかなければいけないと思うので、これは１つの課がどうこうではなく、品川区、もちろん清掃事務所も含めて、その辺はしっかり指導していくべきではないかなと思いますので、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-033"}]},{"id":"topic-04","title":"品川区総合庁舎に設置されている免震オイルダンパー","agenda":"品川区総合庁舎に設置されている免震オイルダンパー","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"そういう思いの中でこの装置を設置しているわけですから。そうではなくて、ここまでいろいろとマスコミも騒ぎ、ほかの２３区の区役所でもそういうものがあるとか、該当するとかしないとか報道されている。なぜこういうことが実際に起きたかというのは、今、問い合わせているというのですけれども、本当に行政を欺いて商品を納品してきたわけですから、許されないことではないのかなと思うのです。","respondent":"立木経理課長","answer":"全容が明らかになったところで、行政としての、例えば業者の指名停止であるとかという行政処分などの何らかの対応というのは、行政として検討していくべきだろうと考えております。","voiceIndex":85,"id":"exchange-034"},{"speaker":"いながわ委員","kind":"質問・要望","question":"例えば今の免震オイルダンパーで、本来１０発揮しなければいけないのを、８しか発揮できないという改ざんがあったと。そうなると、今度は地面と庁舎をつないでいるアンカーがあるわけではないですか。相談とかがあって、実はこうなのだけれども、という話もあったのではないですかということも地域から聞くので、そういうのを払拭するためのことをやっていただければと思います。","respondent":"立木経理課長","answer":"ですので、そこの部分は部品をかえることによって、当初の性能が確保できるものと考えておりますので、メーカーにはそういったところをしっかり対応するようにということで、私どもも求めていくという考え方です。","voiceIndex":87,"id":"exchange-035"},{"speaker":"いながわ委員","kind":"質問","question":"それは１つ安心したところなのですが、先ほど言ったように、免震オイルダンパーを取りかえるというのは、新しいのをつければいいのですけれども、両側のアンカーの部分というのは、それに耐えられるのですか。免震オイルダンパーに負荷がかかるということは、アンカーの部分が４カ所でとまっていましたけれども、そこにも当然負荷がかかるわけではないですか。","respondent":"立木経理課長","answer":"もともと私どもの設計会社で当初見込んでいた性能の品物が入ることによって、当然そこは担保されるものですが、現状ついているデータ改ざんされたものが、ＫＹＢ株式会社からの発表によりますと、大臣認定の誤差の中には入っているけれども。","voiceIndex":89,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"今回のデータ改ざんの不正についてですけれども、先ほど課長は、残念でならないとおっしゃっていたのですが、そういう問題なのかと思うのです。これに対しては、もっと強い態度で対応していく必要があるだろうし、私は看過できない抗議すべき事案だと思うのですけれども、そこはいかがでしょうか。","respondent":"立木経理課長","answer":"先ほど私も、残念という表現を使ったのですけれども、こういったことが起きてしまったこと自体を大変残念に思っているということの意味でございまして、今、委員がおっしゃられましたとおり、不特定多数の来庁者の方がいらっしゃる建物ですので、そこの部分は今後。","voiceIndex":92,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"率直に言って看過できない事態だと、品川区として抗議する。そういうことをしっかりと態度表明するべき事案だと思うのです。本会議の質問に対する答弁の中で、遺憾と言ったのか、よく覚えていないのですけれども、残念だとかそういう思いではなくて、許されないという態度表明が必要ではないかと思うのですけれども、改めていかがでしょうか。","respondent":"立木経理課長","answer":"委員おっしゃられるとおり、本当に許されることではないと考えておりますので、抗議の部分に関しましては、また内部で検討させていただきたいと思います。","voiceIndex":94,"id":"exchange-038"},{"speaker":"須貝委員","kind":"質問","question":"３つがよくて、１つが悪いと。工業界でいえば、４分の１、２５％の確率で不良品が出た。これが全国に出ていると。オイルでシリンダーが動くわけですから、できないならできないと言うだろうし、できると言ってつくった以上、私はますます信じられないのかなと思います。でも、それも場所的に考えれば、私は難しいのではないかなと思うのですが、その点に関しては、どう思われますか。","respondent":"小林施設整備課長","answer":"先ほど見ていただいた一番手前のところだったとすると、駐車場の壁を一回壊して、そこから搬入して取りかえるという方法もあれば、駐車場のマシンハッチという床を壊して外して、そちらから入れるべきなのかとか、位置によっても全然違いますので。","voiceIndex":96,"id":"exchange-039"},{"speaker":"須貝委員","kind":"質問・要望","question":"施設整備課においても、品川区全体においても、まさか寝耳に水で、こんなことは考えられない状況です。まして病院とか公共施設という多くの方が利用する、また先ほどもありました防災拠点となる、本当にそれだけ多くの区民の方が心配されていると思いますので、できるだけ早期にいい方向に向かうように努力していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今までほかの委員の方からもさまざまな意見がありましたけれども、これは本庁舎と議会棟にまたがっているところなので、新設の杭を含めた再調査は、先ほど課長がおっしゃっていましたけれども、まずこれを調査していただいて、免震オイルダンパーについては、全部点検するというところなのですが、全国で１,０００件あって、製品が１万個ある中で。","respondent":"立木経理課長","answer":"既に設計会社、施工会社とも打ち合わせを始めております。そういった中で、できるだけ早期に交換の方向でいけるように調整を進めてまいりたいと思います。","voiceIndex":100,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問","question":"今まで皆さんのご質問を伺っていて、契約関係でいうと、区は直接ではないから、直接の損害賠償が難しいということなのですか。契約関係でいうと、どういうふうになっているのか。あくまで品川区としては、元請の方たちとの契約なので、その中で要求していくということになるのでしょうか。その辺の契約関係がどうなっているのか、教えてください。","respondent":"立木経理課長","answer":"ただし、それをＫＹＢ社から納品を受けて設置するというのは、確かに施工会社の工事になっておりますので、そういった面でもう一度整理をさせていただきまして、どういった形で進めていけるのか、４社での話になると思いますので。","voiceIndex":102,"id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうことかと思いますが、一応、区がもともと発注してたものと違う性能のものが入ってきたということは、もともとの性能を満たすものを品川区として施工業者に求めていたわけですよね。その辺のことも含めて、それから安全性の検証等というのは、どこに対して、どういうふうにやっていくことを求めているのか、あわせて教えてください。","respondent":"小林施設整備課長","answer":"それと元請業者、これが品川区が発注した契約相手。そちらと相談をしながら検証していって、その際、取りかえる必要性が出てくれば、どういうふうに施工するのか、それは早期にわかり次第、検討に入りたいと思います。","voiceIndex":104,"id":"exchange-043"},{"speaker":"吉田委員","kind":"質問・要望","question":"要は、契約で求めたとおりの性能が確保されていなかったということに対しては、契約違反という形で厳しく追及していただきたい。その追及については、契約を交わしたのが、管理をお願いした設計会社と施工会社であれば、そこを通して厳しく安全性の検証も、客観性を担保するため、まるきり違う第三者によって確認した上で、厳しく追及していただきたいなと思います。これについては要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-044"}]},{"id":"topic-05","title":"今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問でありますが、今定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"項目の正式名称を忘れてしまったのですけれども、藤原議員が質問なさった、さきほどの陳情にもかかわることで、公文書についてです。メモとか音声とかと公文書の境目、線引きという言葉を使われました。線引きはどこにあるのかということは、先ほどの公文書の管理の問題にも大きくかかわるところだと思います。ご答弁がなかったように認識しているのですけれども、その辺について改めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2120#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":33552,"voices":114}}]);
